import React, { useState } from 'react';
import {
  Loader2,
  Check,
  Download,
  ChevronDown,
  ChevronRight,
  Layers,
  SkipForward,
  AlertCircle,
  Circle,
  Copy,
  ClipboardCheck,
  Terminal,
} from 'lucide-react';
import type { CapabilityDashboardRecommendation } from '../types';
import type { StepStatus } from '../hooks/useCapabilityInstall';

export interface CapabilityCardProps {
  recommendation: CapabilityDashboardRecommendation;
  onAccept: () => void;
  onDismiss: () => void;
  isAccepting?: boolean;
  stepStatuses?: StepStatus[];
  isInstalled?: boolean;
  isEnabled?: boolean;
  onToggle?: () => void;
  installedVersion?: string;
  /** Visual variant: 'agentic' (purple) or 'static' (grey). Default: 'agentic' */
  variant?: 'agentic' | 'static';
}

const StepStatusIcon: React.FC<{ status: StepStatus['status'] }> = ({ status }) => {
  switch (status) {
    case 'running':
      return <Loader2 className="h-3 w-3 animate-spin text-blue-500" />;
    case 'completed':
      return <Check className="h-3 w-3 text-green-500" />;
    case 'failed':
      return <AlertCircle className="h-3 w-3 text-red-500" />;
    case 'skipped':
      return <SkipForward className="h-3 w-3 text-gray-400" />;
    case 'pending':
    default:
      return <Circle className="h-3 w-3 text-gray-300" />;
  }
};

export const CapabilityCard: React.FC<CapabilityCardProps> = ({
  recommendation,
  onAccept,
  onDismiss: _onDismiss,
  isAccepting = false,
  stepStatuses,
  isInstalled = false,
  isEnabled: _isEnabled = false,
  onToggle: _onToggle,
  installedVersion,
  variant = 'agentic',
}) => {
  const [expanded, setExpanded] = useState(false);
  const [showInstallPrompt, setShowInstallPrompt] = useState(false);
  const [copied, setCopied] = useState(false);
  const showSteps = expanded || (stepStatuses !== undefined && stepStatuses.length > 0);
  const stepCount = recommendation.stepDescriptions.length;
  const allStepsComplete = stepStatuses !== undefined && stepStatuses.length === stepCount && stepStatuses.every(s => s.status === 'completed');
  const hasUpdate = isInstalled && installedVersion !== undefined && installedVersion !== recommendation.version;

  const installPrompt = `/install ${recommendation.installerId}`;

  const handleCopyPrompt = async () => {
    try {
      await navigator.clipboard.writeText(installPrompt);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback: select the text for manual copy
    }
  };

  const handleInstallClick = () => {
    setShowInstallPrompt(prev => !prev);
  };

  return (
    <div className={`border rounded-lg p-4 ${variant === 'static' ? 'border-gray-300 dark:border-gray-500 bg-gray-100 dark:bg-gray-600' : 'border-purple-300 dark:border-purple-500 bg-purple-50 dark:bg-purple-900/40'}`}>
      <div className="flex items-start justify-between gap-4">
        {recommendation.phaseEmoji && (
          <div
            data-testid="phase-emoji"
            className="flex-shrink-0 w-16 h-16 rounded-xl border border-border bg-white dark:bg-gray-900 flex items-center justify-center text-4xl self-center"
          >
            {recommendation.phaseEmoji}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <h4 className="font-medium text-sm bg-gradient-to-r from-pink-500 to-blue-500 dark:from-pink-400 dark:to-blue-400" style={{ WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>{recommendation.name}</h4>
            <span className="text-xs px-2 py-0.5 rounded bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400">
              {recommendation.category}
            </span>
            <span className="text-xs px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-mono">
              v{recommendation.version}
            </span>
          </div>
          <p className="text-sm text-muted-foreground">{recommendation.description}</p>
          <p className="text-xs text-muted-foreground mt-1 italic">{recommendation.reason}</p>

          {stepCount > 0 && (
          <div className="flex items-center gap-3 mt-2">
            <button
              onClick={() => setExpanded(!expanded)}
              className={`flex items-center gap-1 text-xs transition-colors ${
                allStepsComplete
                  ? 'text-green-600 dark:text-green-400'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
              aria-label="Show steps"
            >
              {showSteps ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
              <Layers className="h-3 w-3" />
              {stepCount} {stepCount === 1 ? 'step' : 'steps'}
            </button>
          </div>
          )}

        </div>

        <div className="flex items-center gap-2 flex-shrink-0">
          {isInstalled ? (
            <>
              {hasUpdate && (
                <>
                  <span className="text-xs px-2 py-0.5 rounded font-medium bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300">
                    Update available
                  </span>
                  <button
                    onClick={onAccept}
                    className="flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-md bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 hover:bg-blue-100 dark:hover:bg-blue-900/30 border border-blue-200 dark:border-blue-800 transition-colors"
                    aria-label={`Update ${recommendation.name}`}
                  >
                    Update
                  </button>
                </>
              )}
              <span className="text-xs px-2 py-0.5 rounded font-medium bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300">
                Installed
              </span>
            </>
          ) : (
            <button
              onClick={handleInstallClick}
              disabled={isAccepting}
              className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-md bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 hover:bg-green-100 dark:hover:bg-green-900/30 border border-green-200 dark:border-green-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              aria-label={`Install ${recommendation.name}`}
            >
              <Download className="h-3 w-3" />
              Install
            </button>
          )}
        </div>
      </div>

      {showInstallPrompt && !isInstalled && (
        <div className="mt-3 p-3 rounded-lg border border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-900/20">
          <p className="text-xs text-blue-700 dark:text-blue-300 mb-2">
            Paste this command into Claude Code to install:
          </p>
          <div className="flex items-center gap-2">
            <code className="flex-1 px-3 py-1.5 rounded bg-white dark:bg-gray-900 border border-blue-200 dark:border-blue-700 text-sm font-mono text-blue-800 dark:text-blue-200 flex items-center gap-2">
              <Terminal className="h-3.5 w-3.5 flex-shrink-0 text-blue-500" />
              {installPrompt}
            </code>
            <button
              onClick={handleCopyPrompt}
              className="flex items-center gap-1 px-2.5 py-1.5 text-xs font-medium rounded-md bg-blue-100 dark:bg-blue-800 text-blue-700 dark:text-blue-200 hover:bg-blue-200 dark:hover:bg-blue-700 border border-blue-300 dark:border-blue-600 transition-colors"
              aria-label="Copy install command"
            >
              {copied ? (
                <>
                  <ClipboardCheck className="h-3 w-3" />
                  Copied
                </>
              ) : (
                <>
                  <Copy className="h-3 w-3" />
                  Copy
                </>
              )}
            </button>
          </div>
        </div>
      )}

      {showSteps && (
        <div className="mt-3 p-3 rounded-lg border border-border bg-card/50 space-y-1.5">
          {recommendation.stepDescriptions.map((step, i) => {
            const stepStatus = stepStatuses?.[i];
            const status = stepStatus?.status ?? 'pending';

            return (
              <div key={i}>
                <div className="flex items-center gap-2 text-xs text-muted-foreground" data-step-status={status}>
                  {stepStatuses ? (
                    <span className="w-4 h-4 flex items-center justify-center">
                      <StepStatusIcon status={status} />
                    </span>
                  ) : (
                    <span className="w-4 h-4 flex items-center justify-center rounded-full bg-muted text-[10px] font-medium">
                      {i + 1}
                    </span>
                  )}
                  {step}
                </div>
                {stepStatus?.error && (
                  <p className="text-xs text-red-500 ml-6 mt-0.5">{stepStatus.error}</p>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};
