import * as React from 'react';
import * as ToggleGroupPrimitive from '@radix-ui/react-toggle-group';
import { cn } from '@/lib/utils';

interface ToggleGroupProps {
  value: string;
  onValueChange: (value: string) => void;
  children: React.ReactNode;
  className?: string;
}

const ToggleGroup = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Root>,
  ToggleGroupProps
>(({ value, onValueChange, children, className }, ref) => (
  <ToggleGroupPrimitive.Root
    ref={ref}
    type="single"
    value={value}
    onValueChange={(newValue) => {
      // Prevent deselection - always require a selection
      if (newValue) {
        onValueChange(newValue);
      }
    }}
    className={cn(
      'inline-flex items-center gap-1',
      className
    )}
  >
    {children}
  </ToggleGroupPrimitive.Root>
));
ToggleGroup.displayName = 'ToggleGroup';

interface StatusCounts {
  notStarted: number;
  inProgress: number;
  complete: number;
}

type StatusFilter = 'not_started' | 'in_progress' | 'complete' | null;

interface ToggleGroupItemProps {
  value: string;
  children: React.ReactNode;
  count?: number;
  /** Status-based counts for plans/fixes (not started, in progress, complete) */
  statusCounts?: StatusCounts;
  /** Currently active status filter */
  activeStatusFilter?: StatusFilter;
  /** Callback when a status pill is clicked */
  onStatusFilterChange?: (filter: StatusFilter) => void;
  /** Whether the archive view is active */
  showArchived?: boolean;
  /** Callback when the archive toggle is clicked */
  onArchiveToggle?: () => void;
  className?: string;
  style?: React.CSSProperties;
}

const ToggleGroupItem = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Item>,
  ToggleGroupItemProps
>(({ value, children, count, statusCounts, activeStatusFilter, onStatusFilterChange, showArchived, onArchiveToggle, className, style }, ref) => {
  const hasStatusCounts = statusCounts && (statusCounts.notStarted > 0 || statusCounts.inProgress > 0 || statusCounts.complete > 0);
  const hasSimpleCount = count !== undefined && count > 0;

  const handlePillClick = (filter: StatusFilter) => (e: React.MouseEvent | React.KeyboardEvent) => {
    e.stopPropagation(); // Prevent triggering the parent toggle
    if (onStatusFilterChange) {
      // Toggle off if clicking the same filter, otherwise set the new filter
      onStatusFilterChange(activeStatusFilter === filter ? null : filter);
    }
  };

  const handlePillKeyDown = (filter: StatusFilter) => (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handlePillClick(filter)(e);
    }
  };

  return (
    <ToggleGroupPrimitive.Item
      ref={ref}
      value={value}
      style={style}
      className={cn(
        'inline-flex items-center justify-center gap-2 rounded-md px-3 py-1.5 min-h-[36px] text-sm font-medium',
        'transition-all duration-200',
        'border border-gray-300 dark:border-gray-600',
        'bg-transparent',
        'text-gray-500 dark:text-gray-400',
        'hover:bg-gray-100 hover:dark:bg-gray-700/50',
        'hover:text-gray-700 dark:hover:text-gray-200',
        'data-[state=on]:bg-gray-200 data-[state=on]:dark:bg-gray-700',
        'data-[state=on]:text-gray-900 data-[state=on]:dark:text-white',
        'data-[state=on]:border-gray-300 data-[state=on]:dark:border-gray-600',
        'data-[state=on]:shadow-sm',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2',
        className
      )}
    >
      {children}
      {hasStatusCounts && (
        <span className="ml-1 inline-flex items-center gap-1.5">
          {/* Order matches sorted list: started, not started, complete */}
          {statusCounts.inProgress > 0 && (
            <span
              role="button"
              tabIndex={0}
              onClick={handlePillClick('in_progress')}
              onKeyDown={handlePillKeyDown('in_progress')}
              className={cn(
                'rounded-md px-1.5 py-0.5 text-xs font-semibold transition-all cursor-pointer',
                'border',
                'hover:ring-2 hover:ring-blue-400 dark:hover:ring-blue-500',
                activeStatusFilter === 'in_progress'
                  ? 'bg-blue-500 dark:bg-blue-600 text-white border-blue-600 dark:border-blue-400 ring-2 ring-blue-600 dark:ring-blue-400'
                  : 'bg-blue-100 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 border-blue-300 dark:border-blue-700'
              )}
            >
              {statusCounts.inProgress}
            </span>
          )}
          {statusCounts.notStarted > 0 && (
            <span
              role="button"
              tabIndex={0}
              onClick={handlePillClick('not_started')}
              onKeyDown={handlePillKeyDown('not_started')}
              className={cn(
                'rounded-md px-1.5 py-0.5 text-xs font-semibold transition-all cursor-pointer',
                'border',
                'hover:ring-2 hover:ring-gray-400 dark:hover:ring-gray-500',
                activeStatusFilter === 'not_started'
                  ? 'bg-gray-500 dark:bg-gray-500 text-white border-gray-600 dark:border-gray-400 ring-2 ring-gray-600 dark:ring-gray-400'
                  : 'bg-gray-200 dark:bg-gray-600 text-gray-600 dark:text-gray-300 border-gray-300 dark:border-gray-500'
              )}
            >
              {statusCounts.notStarted}
            </span>
          )}
          {statusCounts.complete > 0 && (
            <span
              role="button"
              tabIndex={0}
              onClick={handlePillClick('complete')}
              onKeyDown={handlePillKeyDown('complete')}
              className={cn(
                'rounded-md px-1.5 py-0.5 text-xs font-semibold transition-all cursor-pointer',
                'border',
                'hover:ring-2 hover:ring-green-400 dark:hover:ring-green-500',
                activeStatusFilter === 'complete'
                  ? 'bg-green-500 dark:bg-green-600 text-white border-green-600 dark:border-green-400 ring-2 ring-green-600 dark:ring-green-400'
                  : 'bg-green-100 dark:bg-green-900/40 text-green-600 dark:text-green-400 border-green-300 dark:border-green-700'
              )}
            >
              {statusCounts.complete}
            </span>
          )}
        </span>
      )}
      {!hasStatusCounts && hasSimpleCount && (
        <span className="ml-1 rounded-md border border-primary/30 bg-primary/20 px-1.5 py-0.5 text-xs font-semibold text-primary dark:text-primary/80">
          {count}
        </span>
      )}
      {onArchiveToggle && (
        <span
          role="button"
          tabIndex={0}
          onClick={(e) => { e.stopPropagation(); onArchiveToggle(); }}
          onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); e.stopPropagation(); onArchiveToggle(); } }}
          aria-label={showArchived ? 'Hide archived' : 'Show archived'}
          className={cn(
            'ml-1 cursor-pointer transition-opacity text-sm',
            showArchived ? 'opacity-100 text-amber-500' : 'opacity-40 hover:opacity-70'
          )}
        >
          📦
        </span>
      )}
    </ToggleGroupPrimitive.Item>
  );
});
ToggleGroupItem.displayName = 'ToggleGroupItem';

export { ToggleGroup, ToggleGroupItem };
export type { StatusFilter, StatusCounts };
