import React from 'react';
import { Search } from 'lucide-react';

interface ListSearchBoxProps {
  /** Current query (controlled). */
  value: string;
  /** Called with the new query on every keystroke. */
  onChange: (value: string) => void;
  placeholder?: string;
  className?: string;
}

/**
 * The shared list search box that sits over the sidebar column, filtering the
 * PRD / Fix / Spike lists by query (see matchesSearch). A controlled input with
 * a leading search icon; the parent owns the query state and the filtering.
 */
const ListSearchBox: React.FC<ListSearchBoxProps> = ({ value, onChange, placeholder = 'Search…', className = '' }) => {
  return (
    <div className={`relative flex-1 min-w-0 ${className}`}>
      <Search className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
      <input
        type="search"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        aria-label={placeholder}
        className="w-full rounded-md border border-gray-300 dark:border-gray-600 bg-white/70 dark:bg-gray-900/40 pl-8 pr-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-tb-blue-400/50"
      />
    </div>
  );
};

export default ListSearchBox;
