import React from 'react';
import CopyIdButton from './CopyIdButton';

interface DetailHeaderBarProps {
  /** The item title, rendered as the heading. */
  title: string;
  /** The item id; when set, a CopyIdButton is shown next to the title. */
  id?: string;
  /** The kind shown in the copy tooltip ("Copy the {idKind} ID"). */
  idKind?: string;
  /** Right-hand slot for status / severity pills and actions (e.g. Archive). */
  right?: React.ReactNode;
  /** Extra classes for layout. */
  className?: string;
  /** Override the test id (adopters keep their stable per-view hook). */
  testId?: string;
}

/**
 * The shared detail-view identity bar — one gradient header used by the PRD,
 * Fix, and Spike detail views so their chrome stays consistent (title size,
 * id-copy affordance, status-pill styling). Title + optional id-copy on the
 * left; a caller-supplied slot for pills/actions on the right.
 */
const DetailHeaderBar: React.FC<DetailHeaderBarProps> = ({ title, id, idKind = '', right, className = '', testId = 'detail-header-bar' }) => {
  return (
    <div
      data-testid={testId}
      // bg-fixed anchors the gradient to the viewport so this bar and the
      // sidebar search bar (separate resizable panels) read as ONE continuous
      // gradient instead of two that restart at the seam. A FIXED h-[60px]
      // (not min-h) keeps all three detail headers + the search bar exactly the
      // same height regardless of right-slot content — the spike carries only a
      // status pill while PRD/Fix carry a taller archive button, which a min-h
      // floor would leave a few px short.
      className={`flex-shrink-0 border-b px-4 h-[60px] flex items-center justify-between gap-4 bg-fixed bg-gradient-to-r from-[oklch(0.97_0.015_320)] to-tb-blue-50 dark:from-[oklch(0.30_0.03_320)] dark:to-tb-blue-900 ${className}`}
    >
      <div className="flex items-center gap-2 min-w-0">
        <h2 className="text-base font-medium truncate">{title}</h2>
        {id && <CopyIdButton value={id} kind={idKind} className="flex-shrink-0" />}
      </div>
      {right && <div className="flex items-center gap-2 flex-shrink-0">{right}</div>}
    </div>
  );
};

export default DetailHeaderBar;
