import { format } from 'date-fns';

/**
 * Formats an ISO timestamp or date-only string for display on detail
 * panes. Date-only inputs (e.g. `2026-01-07`) suppress the time
 * suffix; anything carrying a time component renders as
 * `do MMM yyyy HH:mm`. Centralised so SpikeDetail, FixDetail and any
 * future container detail share one format and don't drift in
 * isolation.
 */
export function formatDateTime(dateStr: string): string {
  const date = new Date(dateStr);
  if (dateStr.length === 10 && !dateStr.includes('T')) {
    return format(date, 'do MMM yyyy');
  }
  return format(date, 'do MMM yyyy HH:mm');
}
