import type { TaskRowTask, TddPhase } from '../types';
import {
  derivePhase as coreDerivePhase,
  isPhaseComplete as coreIsPhaseComplete,
  isPhaseInProgress as coreIsPhaseInProgress,
} from '@magic-ingredients/tiny-brain-core/phase-derivation';
import type { PipelineStep, PhaseDeriveInput, DerivedTddPhase, PhaseConfig } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { ADVERSARIAL_STEP } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';

const DEFAULT_PIPELINE: PipelineStep[] = [ADVERSARIAL_STEP];

/**
 * Build the ordered phase list for a given review pipeline.
 * Returns ['red', 'green', 'review:type1', 'refactor:type1', ..., 'complete']
 */
export const getPipelinePhases = (reviewPipeline: PipelineStep[] = DEFAULT_PIPELINE): TddPhase[] => {
  const phases: TddPhase[] = ['red', 'green'];
  for (const step of reviewPipeline) {
    phases.push(`review:${step.type}` as TddPhase);
    phases.push(`refactor:${step.type}` as TddPhase);
  }
  phases.push('complete');
  return phases;
};

export const deriveTddPhase = (
  task: TaskRowTask,
  reviewPipeline: PipelineStep[] = DEFAULT_PIPELINE,
): TddPhase => {
  const config: PhaseConfig = {
    combineRedGreenCommits: false,
    reviewPipeline,
  };

  const derived = coreDerivePhase(task as PhaseDeriveInput, config);
  // Map 'not_started' to 'red' for dashboard display (pipeline won't show anyway if not started)
  if (derived === 'not_started') return 'red';
  return derived as TddPhase;
};

// Phase complete: completion SHA for that phase is set
export const isPhaseComplete = (task: TaskRowTask, phase: TddPhase): boolean => {
  return coreIsPhaseComplete(task as PhaseDeriveInput, phase as DerivedTddPhase);
};

// Phase in progress: previous phase done but this one not yet
export const isPhaseInProgress = (task: TaskRowTask, phase: TddPhase, config?: PhaseConfig): boolean => {
  return coreIsPhaseInProgress(task as PhaseDeriveInput, phase as DerivedTddPhase, config);
};
