/**
 * SSE-driven trigger for newly registered repositories.
 *
 * Fix `dashboard-drops-filewatcher-sse-events`, Task 4 — the server broadcasts
 * `repo-registered` when a repo is registered, but the client had no listener
 * so the repos list needed a manual reload. This hook listens to that channel
 * and invokes `onRegistered` with the event so the repos list can refetch (or
 * append the new repo). Unlike the doc-live hooks this is global, not
 * repo-scoped — a registration is a "a new repo appeared" signal.
 */

import { useEffect } from 'react';
import { sseManager, type SSEEvent, type RepoRegisteredEvent } from '../services/SSEManager';

export function useRepoRegisteredLive(
  onRegistered: (event: RepoRegisteredEvent) => void,
  enabled = true,
): void {
  useEffect(() => {
    if (!enabled) return;

    const handle = (event: SSEEvent): void => {
      if (event.type !== 'repoRegistered') return;
      onRegistered(event);
    };

    return sseManager.on('repoRegistered', handle);
  }, [enabled, onRegistered]);
}
