import React from 'react';
import { LucideIcon, ArrowLeft, FolderGit2, ChevronRight } from 'lucide-react';
import { useLibrary } from '../../contexts/LibraryContext';
import { useCurrentRepo } from '../../contexts/CurrentRepoContext';
import { useLocation, useNavigate } from 'react-router-dom';
import ThemeToggle from '../ThemeToggle';

interface HeaderProps {
  isCollapsed: boolean;
  currentItem?: {
    title: string;
    icon: LucideIcon;
    color: string;
  };
}

export const Header: React.FC<HeaderProps> = ({
  isCollapsed,
  currentItem
}) => {
  const { connectionStatus, hasCredentials } = useLibrary();
  const { repo: currentRepo } = useCurrentRepo();
  const libReachable = connectionStatus === 'connected';
  const location = useLocation();
  const navigate = useNavigate();

  // Check if we're on a detail page
  const isPersonaDetailPage = location.pathname.match(/^\/personas\/[^/]+$/);
  const isRepoDetailPage = location.pathname.match(/^\/repos\/[^/]+$/);
  const repoIdFromPath = isRepoDetailPage ? decodeURIComponent(location.pathname.split('/')[2] ?? '') : null;

  return (
    <header className="h-16 border-b bg-gray-50 dark:bg-gray-900 flex">
      {/* Logo section - above sidebar */}
      <div className={`${isCollapsed ? 'w-16' : 'w-48'} transition-all duration-200 flex items-center justify-center px-4`}>
        <div className="flex items-center gap-3">
          <span className="text-2xl">🧠</span>
          {!isCollapsed && (
            <span className="font-semibold text-lg bg-gradient-to-r from-pink-500 to-blue-500 bg-clip-text text-transparent">tiny brain</span>
          )}
        </div>
      </div>

      {/* Main header section */}
      <div className="flex-1 flex items-center justify-between px-4">
        <div className="flex items-center">
          {isPersonaDetailPage ? (
            <button
              onClick={() => navigate('/personas')}
              className="flex items-center gap-2 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors"
            >
              <ArrowLeft className="h-4 w-4" />
              <span className="font-medium">Back to Personas</span>
            </button>
          ) : isRepoDetailPage ? (
            <div className="flex items-center gap-2 min-w-0">
              <button
                onClick={() => navigate('/repos')}
                className="flex items-center gap-2 -mx-2 px-2 py-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg transition-colors flex-shrink-0"
              >
                <FolderGit2 className="h-5 w-5 text-blue-500" />
                <span className="font-medium">Repos</span>
              </button>
              <ChevronRight className="h-4 w-4 text-gray-400 flex-shrink-0" aria-hidden="true" />
              <div className="flex items-baseline gap-3 min-w-0">
                <span className="font-semibold truncate">{currentRepo?.name ?? repoIdFromPath ?? ''}</span>
                {currentRepo?.path && (
                  <span className="text-xs text-muted-foreground truncate">{currentRepo.path}</span>
                )}
              </div>
            </div>
          ) : currentItem && (
            <div className="flex items-center gap-2">
              <currentItem.icon className={`h-5 w-5 ${currentItem.color}`} />
              <span className="font-medium">{currentItem.title}</span>
            </div>
          )}
        </div>
        
        {/* Right side: theme chooser + PRO badge */}
        <div className="flex items-center gap-3">
          <ThemeToggle />
          {hasCredentials && (
            <span
              title={libReachable ? 'Library connected' : 'Library not reachable'}
              className={`px-2 py-0.5 rounded-full text-xs font-semibold transition-colors ${
                libReachable
                  ? 'bg-gradient-to-r from-pink-500 to-blue-500 text-white'
                  : 'bg-gray-200 text-gray-400 dark:bg-gray-700 dark:text-gray-500'
              }`}
            >
              PRO
            </span>
          )}
        </div>
      </div>
    </header>
  );
};