import React, { useMemo, useState, useCallback, useRef, useEffect } from 'react';
import type { Plan, Task } from '../types';
import { Card, CardContent } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { User, ChevronDown, ChevronRight, Copy, Check } from 'lucide-react';
import ProgressBar from './ProgressBar';
import CopyIdButton from './CopyIdButton';
import WorktreePill from './WorktreePill';
import { formatPrdFeatureSlugPath } from '../utils/task-slug-path';
import FeatureDetail from './FeatureDetail';
import TaskDetailPanel from './TaskDetailPanel';
import { deriveEffectiveStatus, deriveFeatureEffectiveStatus, deriveFeatureWorktreeRef } from '../utils/effective-task-status';
import clsx from 'clsx';

interface PlanDetailsPRDProps {
  plan: Plan;
  repoId?: string;
  onHeaderCollapsedChange?: (collapsed: boolean) => void;
}

interface SelectedTask {
  featureId: string;
  taskNumber: number;
  progressTask: Task;
}

const PlanDetailsPRD: React.FC<PlanDetailsPRDProps> = ({ plan, repoId }) => {
  const [expandedFeatures, setExpandedFeatures] = useState<Set<number>>(new Set());
  const [selectedTask, setSelectedTask] = useState<SelectedTask | null>(null);
  const [copiedId, setCopiedId] = useState(false);
  const [headerCollapsed, setHeaderCollapsed] = useState(false);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const handleCopyId = useCallback(async () => {
    const id = plan.prdId || '';
    if (!id) return;
    await navigator.clipboard.writeText(id);
    setCopiedId(true);
    setTimeout(() => setCopiedId(false), 2000);
  }, [plan.prdId]);

  const handleTaskClick = (featureId: string, taskNumber: number, progressTask: Task) => {
    setSelectedTask({ featureId, taskNumber, progressTask });
  };

  const handleCloseTaskPanel = () => {
    setSelectedTask(null);
  };

  const toggleFeature = (featureNumber: number) => {
    setExpandedFeatures(prev => {
      const next = new Set(prev);
      if (next.has(featureNumber)) {
        next.delete(featureNumber);
      } else {
        next.add(featureNumber);
      }
      return next;
    });
  };

  // Extract PRD information
  const prdInfo = useMemo(() => {
    return {
      id: plan.prdId || 'Unknown',
      path: plan.prdDirPath || 'Not specified',
      status: plan.status,
      created: plan.created,
      lastUpdated: plan.lastUpdated,
      creator: plan.author || plan.gitUserName || plan.gitUserEmail || 'Unknown',
      creatorEmail: plan.gitUserEmail,
    };
  }, [plan]);

  // Extract features from plan
  const features = useMemo(() => plan.features || [], [plan.features]);

  // Auto-expand current in-progress feature
  React.useEffect(() => {
    const currentFeature = features.find(f => f.status === 'in_progress');
    if (currentFeature) {
      setExpandedFeatures(new Set([currentFeature.number]));
    }
  }, [features]);

  // Helper function for terminal statuses
  const isFeatureDone = (status: string) => status === 'completed' || status === 'superseded';

  // Calculate overall metrics. All rollups use the WORKTREE-AWARE effective
  // status (deriveEffectiveStatus / deriveFeatureEffectiveStatus) so work done on
  // a worktree counts toward feature/PRD completion, not just commits on the
  // launch ref.
  const metrics = useMemo(() => {
    const totalTasks = features.reduce((acc, feature) => acc + (feature.tasks?.length || 0), 0);
    const effTaskStatus = (task: Task) => deriveEffectiveStatus(task).status;
    const actuallyCompletedTasks = features.reduce(
      (acc, feature) => acc + (feature.tasks?.filter(task => effTaskStatus(task) === 'completed').length || 0),
      0
    );
    const supersededTasks = features.reduce(
      (acc, feature) => acc + (feature.tasks?.filter(task => effTaskStatus(task) === 'superseded').length || 0),
      0
    );
    const doneTasks = actuallyCompletedTasks + supersededTasks;

    // Feature display status is rolled up from effective task statuses; a feature
    // is "superseded" only when all its tasks are superseded, else "completed".
    const displayAsSupersededFeatures = features.filter(
      f => deriveFeatureEffectiveStatus(f.tasks ?? []) === 'superseded'
    ).length;
    const displayAsCompletedFeatures = features.filter(
      f => deriveFeatureEffectiveStatus(f.tasks ?? []) === 'completed'
    ).length;

    const doneFeatures = displayAsCompletedFeatures + displayAsSupersededFeatures;
    const inProgressFeatures = features.filter(
      f => deriveFeatureEffectiveStatus(f.tasks ?? []) === 'in_progress'
    ).length;

    return {
      totalFeatures: features.length,
      completedFeatures: displayAsCompletedFeatures,
      supersededFeatures: displayAsSupersededFeatures,
      doneFeatures,
      inProgressFeatures,
      totalTasks,
      completedTasks: actuallyCompletedTasks,
      supersededTasks,
      doneTasks,
      progress: totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0,
    };
  }, [features]);

  // Observe sentinel to toggle compact header
  useEffect(() => {
    const sentinel = sentinelRef.current;
    const scrollContainer = scrollContainerRef.current;
    if (!sentinel || !scrollContainer) return;

    const observer = new IntersectionObserver(
      (entries) => {
        setHeaderCollapsed(!entries[0].isIntersecting);
      },
      { root: scrollContainer, threshold: 0 }
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
  }, []);

  return (
    <div className="h-full flex flex-col">
      {/* Compact header — visible when full header scrolls out */}
      <div
        data-testid="compact-header"
        className="flex-shrink-0 border-b px-4 py-3 flex items-center justify-between transition-all"
        style={{ display: headerCollapsed ? 'flex' : 'none' }}
      >
        <div className="flex items-center gap-2">
          <span className="text-muted-foreground text-sm">PRD:</span>
          <span className="font-mono font-semibold">{prdInfo.id}</span>
          <button
            onClick={handleCopyId}
            className="inline-flex items-center hover:text-foreground transition-colors"
            title="Copy PRD ID"
          >
            {copiedId ? (
              <Check className="h-4 w-4 text-green-500" />
            ) : (
              <Copy className="h-4 w-4 opacity-50 hover:opacity-100" />
            )}
          </button>
        </div>
        <div className="flex items-center gap-6">
          <div className="text-center">
            <div className="text-xs text-muted-foreground">Features</div>
            <div className="text-lg font-bold">{metrics.doneFeatures}/{metrics.totalFeatures}</div>
          </div>
          <div className="text-center">
            <div className="text-xs text-muted-foreground">Tasks</div>
            <div className="text-lg font-bold">{metrics.doneTasks}/{metrics.totalTasks}</div>
          </div>
        </div>
      </div>

      <div ref={scrollContainerRef} className="flex-1 overflow-y-auto p-3 space-y-4">
        {/* Header — single branded section (like fixes), existing content inside */}
        <Card className="py-3">
          <CardContent className="px-3">
            <div className="grid grid-cols-2 gap-8">
              {/* Left: PRD Metadata. The PRD id + copy affordance lives next to
                  the title in the fixed header bar (RepoDetailPage), so it's not
                  repeated here. */}
              <div className="flex flex-col h-full text-sm">
              {/* INFO heading mirrors the KPI column labels (FEATURES / TASKS);
                  the rows below drop to the bottom (mt-auto) so they align with
                  the bottom of the FEATURES / TASKS blocks in the taller column. */}
              <div className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Info</div>
              <div className="mt-auto space-y-1">
              <div className="flex justify-between items-center">
                <span className="text-muted-foreground">Creator:</span>
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <div className="flex items-center gap-1">
                        <User className="h-3 w-3" />
                        <span className="text-xs text-blue-600 hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300 cursor-pointer underline decoration-dotted">
                          {prdInfo.creator}
                        </span>
                      </div>
                    </TooltipTrigger>
                    {prdInfo.creatorEmail && (
                      <TooltipContent
                        className="bg-gray-800 dark:bg-gray-700 text-white border-gray-700"
                        arrowClassName="bg-gray-800 fill-gray-800 dark:bg-gray-700 dark:fill-gray-700"
                      >
                        <p>{prdInfo.creatorEmail}</p>
                      </TooltipContent>
                    )}
                  </Tooltip>
                </TooltipProvider>
              </div>
              <Separator className="my-1" />
              <div className="flex justify-between text-xs">
                <span className="text-muted-foreground">Created: <span className="text-foreground">{prdInfo.created ? new Date(prdInfo.created).toLocaleDateString() : 'Unknown'}</span></span>
                <span className="text-muted-foreground">Updated: <span className="text-foreground">{prdInfo.lastUpdated ? new Date(prdInfo.lastUpdated).toLocaleDateString() : 'Unknown'}</span></span>
              </div>
              </div>
              </div>

              {/* Right: Progress Overview — KPI stat blocks. Linear segmented
                  meters (the same idiom as the feature rows below) read more
                  accurately than donut arcs and stay legible for the superseded
                  slice; the headline ratio leads, the meter and breakdown
                  support it. */}
              <div className="grid grid-cols-2 gap-4">
                {[
                  { key: 'features', label: 'Features', done: metrics.doneFeatures, total: metrics.totalFeatures, completed: metrics.completedFeatures, superseded: metrics.supersededFeatures },
                  { key: 'tasks', label: 'Tasks', done: metrics.doneTasks, total: metrics.totalTasks, completed: metrics.completedTasks, superseded: metrics.supersededTasks },
                ].map((stat) => {
                  const pct = stat.total > 0 ? Math.round((stat.done / stat.total) * 100) : 0;
                  const completedPercent = stat.total > 0 ? Math.round((stat.completed / stat.total) * 100) : 0;
                  const supersededPercent = stat.total > 0 ? Math.round((stat.superseded / stat.total) * 100) : 0;
                  const remaining = stat.total - stat.done;
                  const breakdown = [
                    `${stat.completed} done`,
                    stat.superseded > 0 ? `${stat.superseded} skipped` : null,
                    remaining > 0 ? `${remaining} left` : null,
                  ].filter(Boolean).join(' · ');
                  return (
                    <div key={stat.key} data-testid={`kpi-${stat.key}`} className="flex flex-col gap-1">
                      <div className="text-xs font-medium uppercase tracking-wide text-muted-foreground">{stat.label}</div>
                      <div className="flex items-baseline gap-2">
                        <span className="text-2xl font-bold tabular-nums">{`${stat.done}/${stat.total}`}</span>
                        <span className="ml-auto text-sm text-muted-foreground tabular-nums">{`${pct}%`}</span>
                      </div>
                      <ProgressBar progress={pct} completedPercent={completedPercent} supersededPercent={supersededPercent} className="bg-gray-200 dark:bg-gray-700" />
                      <div className="text-xs text-muted-foreground">{breakdown}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Sentinel — triggers compact header when scrolled past */}
        <div ref={sentinelRef} className="h-0" />

        {/* Row 2: Collapsible Features List */}
        <div className="space-y-3">
          <h3 className="text-lg font-semibold">Features</h3>
          {features.map((feature) => {
            // Worktree-aware: count tasks + roll the feature status up from each
            // task's effective (best-across-refs) status, so work done on a
            // worktree marks the feature done here too.
            const featureStatus = deriveFeatureEffectiveStatus(feature.tasks ?? []);
            // Only set once the feature is complete + uniform — shown in the
            // header so a COLLAPSED feature still reveals it was done on a worktree.
            const featureWorktreeRef = deriveFeatureWorktreeRef(feature.tasks ?? []);
            // The feature slug (`<prd>/<feature>`) copied by the header icon —
            // the visible slug row in the feature body (FeatureDetail) is gone.
            const featureSlug = plan.prdId ? formatPrdFeatureSlugPath(plan.prdId, feature.id) : undefined;
            const effTaskStatus = (task: Task) => deriveEffectiveStatus(task).status;
            const totalTasks = feature.tasks?.length || 0;
            const completedTasks = feature.tasks?.filter(task => effTaskStatus(task) === 'completed')?.length || 0;
            const supersededTasks = feature.tasks?.filter(task => effTaskStatus(task) === 'superseded')?.length || 0;
            const doneTasks = completedTasks + supersededTasks;
            const hasSupersededTasks = supersededTasks > 0;

            // deriveFeatureEffectiveStatus already returns 'superseded' only when
            // every task is superseded, else 'completed'.
            const displayAsSuperseded = featureStatus === 'superseded';
            const displayAsCompleted = featureStatus === 'completed';

            const progress = isFeatureDone(featureStatus) ? 100 :
                            totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
            const completedPercent = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
            const isExpanded = expandedFeatures.has(feature.number);

            return (
              <div
                key={feature.id}
                className={clsx(
                  'rounded-lg border overflow-hidden transition-all',
                  displayAsCompleted && 'bg-green-100 dark:bg-green-900/30 border-green-300 dark:border-green-800',
                  displayAsSuperseded && 'bg-orange-100 dark:bg-orange-900/30 border-orange-300 dark:border-orange-800',
                  featureStatus === 'in_progress' && 'bg-blue-100 dark:bg-blue-900/30 border-blue-300 dark:border-blue-800',
                  featureStatus === 'not_started' && 'bg-gray-100 dark:bg-gray-800/50 border-gray-300 dark:border-gray-700'
                )}
              >
                {/* Feature Header - Clickable */}
                <div
                  onClick={() => toggleFeature(feature.number)}
                  className="relative px-4 py-2 cursor-pointer hover:opacity-80 transition-opacity"
                >
                  {/* Progress fill for in-progress features - only in header */}
                  {featureStatus === 'in_progress' && progress > 0 && (
                    <div
                      className="absolute inset-0 bg-blue-200 dark:bg-blue-800/40 transition-all duration-300 pointer-events-none"
                      style={{ width: `${progress}%` }}
                    />
                  )}

                  {/* Mixed progress bar for completed features with some superseded tasks */}
                  {displayAsCompleted && hasSupersededTasks && totalTasks > 0 && (
                    <>
                      {/* Orange background for superseded portion */}
                      <div className="absolute inset-0 bg-orange-100 dark:bg-orange-900/30 pointer-events-none" />
                      {/* Green foreground for completed portion */}
                      <div
                        className="absolute inset-0 bg-green-100 dark:bg-green-900/30 transition-all duration-300 pointer-events-none"
                        style={{ width: `${completedPercent}%` }}
                      />
                    </>
                  )}
                  <div className="relative flex items-center justify-between gap-3">
                    <div className="flex items-center gap-3 min-w-0 flex-1">
                      {/* Expand/Collapse Icon */}
                      {isExpanded ? (
                        <ChevronDown className="h-5 w-5 flex-shrink-0" />
                      ) : (
                        <ChevronRight className="h-5 w-5 flex-shrink-0" />
                      )}

                      {/* Feature status icon */}
                      <div className="flex-shrink-0">
                        {displayAsCompleted && (
                          <span className="text-green-600 dark:text-green-400 text-lg">✓</span>
                        )}
                        {displayAsSuperseded && (
                          <span className="text-orange-600 dark:text-orange-400 text-lg">⏭</span>
                        )}
                        {featureStatus === 'in_progress' && (
                          <span className="text-blue-600 dark:text-blue-400 text-lg">●</span>
                        )}
                        {featureStatus === 'not_started' && (
                          <span className="text-gray-400 dark:text-gray-500 text-lg">○</span>
                        )}
                      </div>

                      {/* Feature number badge */}
                      <div className={clsx(
                        "flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold",
                        displayAsCompleted && "bg-green-600 dark:bg-green-700 text-white",
                        displayAsSuperseded && "bg-orange-600 dark:bg-orange-700 text-white",
                        featureStatus === 'in_progress' && "bg-blue-600 dark:bg-blue-700 text-white",
                        featureStatus === 'not_started' && "bg-gray-400 dark:bg-gray-600 text-white"
                      )}>
                        {feature.number}
                      </div>

                      {/* Feature info */}
                      <div className="min-w-0 flex-1 flex items-center gap-2">
                        <span className={clsx(
                          "text-sm font-semibold truncate",
                          displayAsCompleted && "text-green-800 dark:text-green-200",
                          displayAsSuperseded && "text-orange-800 dark:text-orange-200 line-through",
                          featureStatus === 'in_progress' && "text-blue-800 dark:text-blue-200",
                          featureStatus === 'not_started' && "text-gray-700 dark:text-gray-300"
                        )}>
                          {feature.title}
                        </span>
                        {featureSlug && (
                          <CopyIdButton value={featureSlug} kind="Feature" className="flex-shrink-0" />
                        )}
                      </div>
                    </div>

                    {/* Worktree marker — the shared branch-keyed pill, right-aligned,
                        visible even when the feature is collapsed */}
                    {featureWorktreeRef && (
                      <WorktreePill
                        branches={[{ branch: featureWorktreeRef, hasWorktree: true }]}
                        className="mr-2 flex-shrink-0"
                      />
                    )}

                    {/* Task count — completed (green) and, when any, superseded
                        (orange) on a second row. Fixed min-width so the worktree
                        markers before it line up across feature rows. */}
                    <div className="text-sm flex-shrink-0 flex flex-col items-end leading-tight">
                      {totalTasks > 0 ? (
                        hasSupersededTasks ? (
                          <>
                            <span className="text-green-600 dark:text-green-400">{completedTasks}/{totalTasks} tasks</span>
                            <span className="text-orange-600 dark:text-orange-400">{supersededTasks}/{totalTasks} tasks</span>
                          </>
                        ) : (
                          <span className={clsx(
                            displayAsCompleted && "text-green-600 dark:text-green-400",
                            displayAsSuperseded && "text-orange-600 dark:text-orange-400",
                            featureStatus === 'in_progress' && "text-blue-600 dark:text-blue-400",
                            featureStatus === 'not_started' && "text-gray-500 dark:text-gray-500"
                          )}>{doneTasks}/{totalTasks} tasks</span>
                        )
                      ) : (
                        <span className="text-gray-500 dark:text-gray-500">No tasks</span>
                      )}
                    </div>

                    {/* Status marker — one consistent-width column for every
                        status (Complete / Superseded / % / Not started) so the
                        task counts before it line up across all feature rows. */}
                    <div className={clsx(
                      "flex-shrink-0 ml-2 text-sm font-medium",
                      displayAsCompleted && "text-green-700 dark:text-green-300",
                      displayAsSuperseded && "text-orange-700 dark:text-orange-300",
                      featureStatus === 'in_progress' && "text-blue-700 dark:text-blue-300",
                      featureStatus === 'not_started' && "text-gray-500 dark:text-gray-400"
                    )}>
                      {displayAsCompleted && 'Complete'}
                      {displayAsSuperseded && 'Superseded'}
                      {featureStatus === 'in_progress' && `${progress}%`}
                      {featureStatus === 'not_started' && 'Not started'}
                    </div>
                  </div>
                </div>

                {/* Feature Detail - Expandable */}
                {isExpanded && (
                  <div className="relative border-t border-current/20 bg-white/50 dark:bg-black/20">
                    <FeatureDetail
                      feature={feature}
                      repoId={repoId || ''}
                      planId={plan.prdId}
                      onTaskClick={repoId ? handleTaskClick : undefined}
                    />
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Task Detail Panel - only render when task is selected */}
      {repoId && plan.prdId && selectedTask && (
        <TaskDetailPanel
          isOpen={true}
          onClose={handleCloseTaskPanel}
          repoId={repoId}
          planId={plan.prdId}
          featureId={selectedTask.featureId}
          taskNumber={selectedTask.taskNumber}
          progressTask={selectedTask.progressTask}
        />
      )}
    </div>
  );
};

export default PlanDetailsPRD;
