/**
 * Overlay `DerivedTaskState` (projected from telemetry events by
 * `deriveTaskStateFromEvents`) onto a raw `TaskRowTask` (read from
 * progress.json). Telemetry-derived fields WIN where present; the
 * raw task's fields are the fallback for any field telemetry doesn't
 * cover (or for tasks that have no telemetry events at all — legacy
 * data, fresh clones with no hooks).
 *
 * The dashboard's pipeline icon strip reads from this overlayed task,
 * so the drift cases the fix doc enumerates (one-cycle reject path,
 * chore: follow-ups, working-tree vs .git/tiny-brain split, concurrent
 * writers) render correctly when telemetry has the data — even if
 * progress.json doesn't.
 *
 * Pure / non-mutating: a fresh object is returned. The function never
 * touches either input.
 */

import type { TaskRowTask } from '../types';
import type { DerivedTaskState } from '@magic-ingredients/tiny-brain-core';

export function applyDerivedState(
  task: TaskRowTask,
  derived: DerivedTaskState | undefined,
): TaskRowTask {
  if (!derived) return task;

  // Pull `reviews` out of derived so the top-level spread doesn't
  // clobber the entire map. Reviews need per-gate merging — a task
  // can have a coverage entry from progress.json and an adversarial
  // entry from telemetry; both must survive.
  const { reviews: derivedReviews, ...derivedTop } = derived;

  const merged: TaskRowTask = {
    ...task,
    ...stripUndefined(derivedTop),
  };

  if (derivedReviews !== undefined) {
    // Per-gate merge: each gate present in derivedReviews replaces the
    // raw task's corresponding gate (telemetry is the source of truth
    // where it has data); gates only in the raw task survive untouched.
    merged.reviews = { ...task.reviews, ...derivedReviews };
  }

  return merged;
}

function stripUndefined<T extends object>(obj: T): Partial<T> {
  const out: Partial<T> = {};
  for (const key of Object.keys(obj) as Array<keyof T>) {
    const v = obj[key];
    if (v !== undefined) out[key] = v;
  }
  return out;
}
