import React from 'react';
import { cn } from '@/lib/utils';
import { Clock } from 'lucide-react';
import { SelectableCard } from './ui/selectable-card';
import WorktreePill from './WorktreePill';
import type { SpikeSummary } from '@magic-ingredients/tiny-brain-core';
import {
  SPIKE_STATUS_LABEL,
  SPIKE_STATUS_STYLES,
  SPIKE_TERMINAL_STATUSES,
} from './spike-status';

interface SpikeCardProps {
  spike: SpikeSummary;
  isSelected: boolean;
  onClick: () => void;
}

const SpikeCard: React.FC<SpikeCardProps> = ({ spike, isSelected, onClick }) => {
  const isResolved = SPIKE_TERMINAL_STATUSES.has(spike.status);
  const isInProgress = spike.status === 'in_progress';

  return (
    <SelectableCard
      isSelected={isSelected}
      isCompleted={isResolved}
      onClick={onClick}
      className={cn(isInProgress && 'bg-blue-100/60 dark:bg-blue-900/30')}
    >
      <div className="flex items-start justify-between gap-2">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <h3 className="font-medium text-sm line-clamp-2">{spike.title}</h3>
          </div>
        </div>
        <span
          data-testid={`spike-status-${spike.id}`}
          data-status={spike.status}
          className={cn(
            'text-xs px-2 py-0.5 rounded border font-medium whitespace-nowrap',
            SPIKE_STATUS_STYLES[spike.status],
          )}
        >
          {SPIKE_STATUS_LABEL[spike.status]}
        </span>
      </div>

      {/* Worktree badge — keyed on the branch, decorated because a worktree exists */}
      {spike.worktree && (
        <div className="mt-2">
          <WorktreePill
            branches={[
              { branch: spike.worktree.branch, hasWorktree: true, worktreeName: spike.worktree.name },
            ]}
          />
        </div>
      )}

      {/* Created date left, timebox duration right-aligned */}
      <div className="mt-2 flex items-center justify-between gap-3 text-xs text-muted-foreground">
        <span>Created: {new Date(spike.created).toLocaleDateString()}</span>
        <span className="flex items-center gap-1">
          <Clock className="h-3 w-3" aria-hidden="true" />
          {spike.timebox}
        </span>
      </div>
    </SelectableCard>
  );
};

export default SpikeCard;
