import React, { useEffect, useState } from 'react';
import { Loader2, X } from 'lucide-react';
import { useDetailsPopover } from './GlobalDetailsPopover';
import { getStepEmoji, getStepLabel } from '../utils/step-display';
import { useTheme } from '../contexts/ThemeContext';
import { useCurrentRepo } from '../contexts/CurrentRepoContext';
import { useReviewLive } from '../hooks/useReviewLive';

interface Suggestion {
  priority: 'high' | 'medium' | 'low';
  category: string;
  file: string;
  line: number;
  description: string;
  rationale: string;
  suggestion: string;
}

interface ReviewData {
  summary: string;
  verdict: 'clean' | 'needs-refactoring';
  testQuality: string;
  suggestions?: Suggestion[];
  coveragePercent?: number;
  overallCoverage?: number;
  threshold?: number;
  /** Absolute on-disk path of the persisted review file, supplied by the
   * backend review endpoint. Shown in the popover header. */
  reviewFilePath?: string;
}

interface AdversarialReviewPopoverProps {
  commitSha: string;
  repoId: string;
  reviewType?: string;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

function getReviewTypeConfig(type: string): { emoji: string; label: string } {
  return { emoji: getStepEmoji(type), label: getStepLabel(type) };
}

const verdictHeaderClass: Record<ReviewData['verdict'], string> = {
  clean: 'border-green-200 dark:border-green-900/50 bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-400',
  'needs-refactoring': 'border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-400',
};

const verdictLabel: Record<ReviewData['verdict'], string> = {
  clean: 'Clean',
  'needs-refactoring': 'Needs refactoring',
};

const priorityColors: Record<Suggestion['priority'], string> = {
  high: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
  medium: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
  low: 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-400',
};

/**
 * Priority-keyed oklch tint for an issue card header, matching the dashboard's
 * usual card pattern (see QualityStepCard): light/dark lightness pair, hue by
 * priority (high→red, medium→amber, low→neutral). Returned as inline style
 * values so the band is tinted without bespoke Tailwind classes.
 */
function priorityHeaderTint(
  priority: Suggestion['priority'],
  isDark: boolean,
): { backgroundColor: string; borderColor: string } {
  const hue = priority === 'high' ? 25 : priority === 'medium' ? 75 : 255;
  const chroma = priority === 'low' ? 0.01 : 0.05;
  return {
    backgroundColor: isDark ? `oklch(0.27 ${chroma} ${hue})` : `oklch(0.96 ${chroma} ${hue})`,
    borderColor: isDark ? `oklch(0.40 ${chroma + 0.03} ${hue})` : `oklch(0.85 ${chroma + 0.03} ${hue})`,
  };
}

const ReviewContent: React.FC<{
  commitSha: string;
  repoId: string;
  reviewType: string;
  onClose: () => void;
}> = ({ commitSha, repoId, reviewType, onClose }) => {
  const { emoji, label } = getReviewTypeConfig(reviewType);
  const [review, setReview] = useState<ReviewData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Live-refresh: a review-change SSE for this repo bumps the counter, which
  // re-runs the fetch below (fix dashboard-drops-filewatcher-sse-events T3).
  const [reloadCounter, setReloadCounter] = useState(0);
  useReviewLive(repoId, () => setReloadCounter((c) => c + 1), { commitSha });
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';
  const { repo } = useCurrentRepo();

  // The backend hands back an absolute review-file path; render it anchored at
  // the repo (e.g. `tiny-brain-local/.git/tiny-brain/reviews/…`) rather than the
  // full `/Users/…` prefix. Falls back to the absolute path when it isn't under
  // the current repo (or no repo is in context).
  const repoRelativePath = (abs: string): string => {
    if (repo?.path && abs.startsWith(repo.path)) {
      const rel = abs.slice(repo.path.length).replace(/^[/\\]+/, '');
      return repo.name ? `${repo.name}/${rel}` : rel;
    }
    return abs;
  };

  useEffect(() => {
    const fetchReview = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(`/api/repos/${repoId}/reviews/${reviewType}/${commitSha}`);
        if (!response.ok) throw new Error('Failed to fetch review');
        setReview(await response.json());
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Unknown error');
      } finally {
        setLoading(false);
      }
    };
    fetchReview();
  }, [commitSha, repoId, reviewType, reloadCounter]);

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="bg-gray-200 dark:bg-gray-900 border-b border-border dark:border-dark-border">
        <div className="flex items-center justify-between p-4">
          <div className="flex items-center gap-2">
            <span className="text-lg">{emoji}</span>
            <span className="font-medium text-sm">{label}</span>
            <span className="font-mono text-xs text-muted-foreground">
              {commitSha.substring(0, 7)}
            </span>
          </div>
          <button
            onClick={onClose}
            aria-label="Close"
            className="p-1 rounded-md hover:bg-gray-300 dark:hover:bg-gray-800 transition-colors"
          >
            <X className="h-5 w-5" />
          </button>
        </div>
        {review?.reviewFilePath && (
          <div className="px-4 pb-3 -mt-1">
            <p
              className="font-mono text-[11px] text-muted-foreground break-all"
              title={review.reviewFilePath}
            >
              {repoRelativePath(review.reviewFilePath)}
            </p>
          </div>
        )}
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading && (
          <div className="flex items-center justify-center py-12" data-testid="review-loading">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        )}

        {error && (
          <div className="text-sm text-destructive">
            <p className="font-medium">Error loading review</p>
            <p className="text-xs mt-1">{error}</p>
          </div>
        )}

        {review && (() => {
          const suggestions = review.suggestions ?? [];
          const highCount = suggestions.filter(s => s.priority === 'high').length;
          const mediumCount = suggestions.filter(s => s.priority === 'medium').length;
          const lowCount = suggestions.filter(s => s.priority === 'low').length;
          return (
          <div className="space-y-4">
            {/* Coverage % — always first for coverage reviews */}
            {(() => {
              const coveragePct = review.coveragePercent ?? review.overallCoverage;
              if (reviewType !== 'coverage') return null;
              if (coveragePct == null) {
                return (
                  <div className={`rounded-md border p-3 text-center ${review.verdict === 'clean' ? 'border-green-200 dark:border-green-900/50 bg-green-50 dark:bg-green-900/20' : 'border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/20'}`}>
                    <div className={`text-2xl font-bold ${review.verdict === 'clean' ? 'text-green-700 dark:text-green-400' : 'text-red-700 dark:text-red-400'}`}>{review.verdict}</div>
                    <div className="text-xs text-muted-foreground">No executable code changed</div>
                  </div>
                );
              }
              const threshold = review.threshold ?? 80;
              const passing = coveragePct >= threshold;
              return (
                <div className={`rounded-md border p-3 text-center ${passing ? 'border-green-200 dark:border-green-900/50 bg-green-50 dark:bg-green-900/20' : 'border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/20'}`}>
                  <div className={`text-2xl font-bold ${passing ? 'text-green-700 dark:text-green-400' : 'text-red-700 dark:text-red-400'}`}>{coveragePct}%</div>
                  <div className="text-xs text-muted-foreground">Coverage (threshold: {threshold}%)</div>
                </div>
              );
            })()}
            {/* Verdict header — non-coverage reviews only */}
            {reviewType !== 'coverage' && (
              <div className={`rounded-md border p-2 text-center ${verdictHeaderClass[review.verdict]}`}>
                <div className="text-base font-semibold">{verdictLabel[review.verdict]}</div>
              </div>
            )}
            {suggestions.length > 0 && reviewType === 'mutation-testing' ? (
                <div className="rounded-md border border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/20 p-3 text-center">
                  <div className="text-2xl font-bold text-red-700 dark:text-red-400">{suggestions.length}</div>
                  <div className="text-xs text-red-600 dark:text-red-500">Surviving Mutants</div>
                </div>
            ) : suggestions.length > 0 ? (
                <div className="grid grid-cols-3 gap-2">
                  <div className="rounded-md border border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/20 p-2 text-center">
                    <div className="text-lg font-bold text-red-700 dark:text-red-400">{highCount}</div>
                    <div className="text-xs text-red-600 dark:text-red-500">High</div>
                  </div>
                  <div className="rounded-md border border-yellow-200 dark:border-yellow-900/50 bg-yellow-50 dark:bg-yellow-900/20 p-2 text-center">
                    <div className="text-lg font-bold text-yellow-700 dark:text-yellow-400">{mediumCount}</div>
                    <div className="text-xs text-yellow-600 dark:text-yellow-500">Medium</div>
                  </div>
                  <div className="rounded-md border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50 p-2 text-center">
                    <div className="text-lg font-bold text-gray-700 dark:text-gray-400">{lowCount}</div>
                    <div className="text-xs text-gray-600 dark:text-gray-500">Low</div>
                  </div>
                </div>
            ) : null}
            <div>
              <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-1">Summary</h3>
              <p className="text-sm">{review.summary}</p>
            </div>
            {review.testQuality && (
            <div>
              <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-1">Test Quality</h3>
              <p className="text-sm">{review.testQuality}</p>
            </div>
            )}
            {suggestions.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2">
                  {reviewType === 'mutation-testing' ? 'Surviving Mutants' : 'Suggestions'} ({suggestions.length})
                </h3>
                <div className="space-y-3">
                  {suggestions.map((suggestion, index) => {
                    const tint = priorityHeaderTint(suggestion.priority, isDark);
                    return (
                    <div key={index} className="border border-border dark:border-dark-border rounded-md overflow-hidden">
                      {/* Card header — oklch priority tint; path on its own row underneath */}
                      <div
                        className="px-3 py-2 border-b"
                        style={{ backgroundColor: tint.backgroundColor, borderColor: tint.borderColor }}
                      >
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-semibold text-muted-foreground">#{index + 1}</span>
                          <span className={`inline-block px-1.5 py-0.5 rounded text-xs font-medium ${priorityColors[suggestion.priority]}`}>
                            {suggestion.priority}
                          </span>
                          {suggestion.category && (
                            <span className="text-xs font-medium text-foreground/80">{suggestion.category}</span>
                          )}
                        </div>
                        {suggestion.file && (
                          <p
                            className="mt-1 text-xs text-muted-foreground font-mono break-all"
                            title={`${suggestion.file}:${suggestion.line}`}
                          >
                            {suggestion.file}:{suggestion.line}
                          </p>
                        )}
                      </div>
                      {/* Card body */}
                      <div className="px-3 py-2 space-y-1">
                        <p className="text-sm font-medium">{suggestion.description}</p>
                        {suggestion.rationale && (
                          <p className="text-xs text-muted-foreground">{suggestion.rationale}</p>
                        )}
                        {suggestion.suggestion && (
                          <p className="text-xs">
                            <span className="font-semibold text-muted-foreground">Suggestion: </span>
                            {suggestion.suggestion}
                          </p>
                        )}
                      </div>
                    </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
          );
        })()}
      </div>
    </div>
  );
};

const AdversarialReviewPopover: React.FC<AdversarialReviewPopoverProps> = ({
  commitSha,
  repoId,
  reviewType = 'adversarial',
  open: controlledOpen,
  onOpenChange,
}) => {
  const { open, close } = useDetailsPopover();

  const handleClose = () => {
    close();
  };

  useEffect(() => {
    if (controlledOpen && commitSha) {
      open(
        <ReviewContent
          commitSha={commitSha}
          repoId={repoId}
          reviewType={reviewType}
          onClose={handleClose}
        />,
        { onClose: () => onOpenChange?.(false) }
      );
    } else if (controlledOpen === false) {
      close();
    }
  }, [controlledOpen, commitSha, repoId, reviewType]);

  return null;
};

export default AdversarialReviewPopover;
