import React from 'react';
import { GitBranch } from 'lucide-react';
import { Tooltip, TooltipContent, TooltipTrigger } from './ui/tooltip';
import WorktreeIcon from './WorktreeIcon';

/** A branch carrying an item's work, plus its worktree (when one exists). */
export interface WorktreeBranchRef {
  readonly branch: string;
  readonly hasWorktree: boolean;
  /** The worktree's directory name, when known (assignment-sourced refs). */
  readonly worktreeName?: string;
}

interface WorktreePillProps {
  /**
   * Branches this item's work lives on (the stable identity), each flagged with
   * whether a live worktree exists for it (and its dir name when known). The
   * branch is the label; worktree presence is a decoration, not a separate entry.
   */
  branches: readonly WorktreeBranchRef[];
  /** Extra classes for layout (e.g. text-xs, ml-auto). */
  className?: string;
}

/** Collapse repeated branches; OR the worktree flag and keep any known name. */
function dedupeByBranch(branches: readonly WorktreeBranchRef[]): WorktreeBranchRef[] {
  const merged = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
  for (const b of branches) {
    const prev = merged.get(b.branch);
    merged.set(b.branch, {
      hasWorktree: (prev?.hasWorktree ?? false) || b.hasWorktree,
      worktreeName: prev?.worktreeName ?? b.worktreeName,
    });
  }
  return [...merged].map(([branch, v]) => ({ branch, ...v }));
}

/** A branch whose worktree dir name is known and differs from the branch name. */
function diverges(b: WorktreeBranchRef): boolean {
  return !!b.worktreeName && b.worktreeName !== b.branch;
}

/** Accessible single-line summary for one branch (branch ± worktree name). */
function branchLabel(b: WorktreeBranchRef): string {
  if (diverges(b)) return `branch ${b.branch}, worktree ${b.worktreeName}`;
  if (b.hasWorktree) return `${b.branch} (worktree)`;
  return b.branch;
}

/**
 * One purple pill summarising the branch(es) an item's work lives on. The
 * branch is the identity: a single branch shows its raw name; multiple show
 * "{n} branches" with the full list in the tooltip. A right-aligned W chip
 * decorates the pill when any shown branch has a live worktree — branch and
 * worktree are orthogonal axes (a branch can carry work with no worktree, and
 * a worktree can exist whose branch hasn't diverged), so worktree presence is
 * a decoration, never a separate entry. The tooltip splits the two axes into a
 * GitBranch row (branch) and a W row (worktree dir name) when they diverge.
 */
const PILL_CLASS =
  'inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs border border-[oklch(0.72_0.13_300)] dark:border-[oklch(0.55_0.15_300)] bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-300';

const WorktreePill: React.FC<WorktreePillProps> = ({ branches, className = '' }) => {
  const model = dedupeByBranch(branches);
  if (model.length === 0) return null;
  const anyWorktree = model.some((b) => b.hasWorktree);
  const label = model.length === 1 ? model[0].branch : `${model.length} branches`;
  const title = model.map(branchLabel).join(', ');
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span data-testid="worktree-badge" aria-label={title} className={`${PILL_CLASS} ${className}`}>
          <GitBranch className="h-3 w-3 flex-shrink-0" />
          <span className="truncate">{label}</span>
          {anyWorktree && (
            <WorktreeIcon
              data-testid="worktree-indicator"
              aria-label="has a live worktree"
              className="ml-0.5"
            />
          )}
        </span>
      </TooltipTrigger>
      <TooltipContent>
        <span className="flex flex-col gap-1">
          {model.map((b) => (
            <span key={b.branch} className="flex flex-col gap-0.5">
              <span className="flex items-center gap-1">
                <GitBranch className="h-3 w-3 flex-shrink-0" />
                {b.branch}
              </span>
              {diverges(b) && (
                <span className="flex items-center gap-1">
                  <WorktreeIcon aria-hidden="true" />
                  {b.worktreeName}
                </span>
              )}
            </span>
          ))}
        </span>
      </TooltipContent>
    </Tooltip>
  );
};

export default WorktreePill;
