import { useState, useEffect } from 'react';
import { X, Loader2, FileCode, FolderPlus, CheckSquare, AlertCircle } from 'lucide-react';
import type { TaskDetail, FeatureMarkdown, Task } from '../types';
import { applyWorktreePhaseShas } from '../utils/worktree-aware-shas';
import { deriveEffectiveStatus } from '../utils/effective-task-status';
import { useDetailsPopover } from './GlobalDetailsPopover';
import { useTaskTelemetry, timelineTaskRef } from '../hooks/useTaskTelemetry';
import type { TaskRefInput } from '../hooks/useTaskTelemetry';
import { TaskTimeline } from './TaskTimeline';
import { getStepEmoji, getStepLabel } from '../utils/step-display';
import { formatPrdTaskSlugPath, formatFixTaskSlugPath } from '../utils/task-slug-path';
import { StatusPill, type StatusTone } from './StatusPill';

interface TaskDetailPanelProps {
  isOpen: boolean;
  onClose: () => void;
  repoId: string;
  planId?: string;
  featureId?: string;
  fixId?: string;
  taskNumber: number;
  /** The task from progress.json with commit tracking info */
  progressTask?: Task;
}

const TaskDetailContent: React.FC<{
  repoId: string;
  planId?: string;
  featureId?: string;
  fixId?: string;
  taskNumber: number;
  progressTask?: Task;
  onClose: () => void;
}> = ({ repoId, planId, featureId, fixId, taskNumber, progressTask, onClose }) => {
  const [taskDetail, setTaskDetail] = useState<TaskDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'details' | 'timeline'>('details');

  // Join telemetry on the task UUID (the key new events use post-F4/F5);
  // the positional id + description ride along as soak-window legacy keys
  // so historical events still surface
  // (dashboard-timeline-queries-stale-positional-key).
  const taskRef: TaskRefInput | null = timelineTaskRef(progressTask, { planId, featureId, fixId });

  const { events: telemetryEvents, loading: telemetryLoading, error: telemetryError } =
    useTaskTelemetry(repoId, taskRef, activeTab === 'timeline');

  useEffect(() => {
    if (repoId && taskNumber > 0) {
      if (planId && featureId) {
        fetchFeatureTaskDetail();
      } else if (fixId) {
        fetchFixTaskDetail();
      }
    }
  }, [repoId, planId, featureId, fixId, taskNumber]);

  const fetchFeatureTaskDetail = async () => {
    setLoading(true);
    setError(null);
    const url = `/api/repos/${repoId}/plans/${planId}/features/${featureId}`;
    try {
      const response = await fetch(url);
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to fetch feature details (${response.status})`);
      }
      const data = await response.json();
      const feature: FeatureMarkdown = data.feature;

      const task = feature.tasks.find(t => t.number === taskNumber);
      if (!task) {
        throw new Error(`Task ${taskNumber} not found in feature`);
      }
      setTaskDetail(task);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const fetchFixTaskDetail = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}`);
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Failed to fetch fix details (${response.status})`);
      }
      const data = await response.json();
      const task = data.fix.parsedTasks?.find((t: TaskDetail) => t.number === taskNumber);
      if (!task) {
        throw new Error(`Task ${taskNumber} not found in fix`);
      }
      setTaskDetail(task);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  // Fill phase SHAs missing on the launch ref from the per-ref lattice so the
  // Commit Trail shows a worktree/branch commit (e.g. detached worktree
  // mid-rebase) with the same SHA the row's phase strip surfaces — they read the
  // same overlay, so they stay consistent (ADR-0007 / multi-ref-projection T5).
  const commitTrailTask = progressTask ? applyWorktreePhaseShas(progressTask) : undefined;

  // Status the popover shows must match the task ROW: the worktree-aware
  // "effective" status (best across refs), not the raw launch-ref status. A
  // task completed on a worktree that hasn't landed on the launch ref reads
  // not_started flat but completed effectively — the row already shows that, so
  // the popover pill must too (ADR-0007 / multi-ref-projection).
  const effectiveStatus = progressTask ? deriveEffectiveStatus(progressTask).status : 'not_started';

  // A work product's status is ALWAYS one of three values: Not Started /
  // In Progress / Complete. Never a TDD stage or review step. Pipeline progress
  // (red, green, review, refactor) lives in the phase strip and the commit-trail
  // footer; conflating a stage into the status slot reads as a phantom status.
  // Superseded is terminal — it ranks with completed ("both are done"), so it
  // folds into Complete here; the superseded reason still shows in the body.
  const getStatusTone = (): StatusTone => {
    switch (effectiveStatus) {
      case 'completed':
      case 'superseded':
        return 'green';
      case 'in_progress':
        return 'blue';
      default:
        return 'gray';
    }
  };

  const getStatusLabel = () => {
    switch (effectiveStatus) {
      case 'completed':
      case 'superseded':
        return 'Complete';
      case 'in_progress':
        return 'In Progress';
      default:
        return 'Not Started';
    }
  };

  // Supersede reason: standard PRD tasks keep it in the body (taskDetail.note,
  // surfaced by the feature-detail endpoint); manual tasks keep it in the
  // frontmatter completionNote (progressTask.note). `||` so an empty string
  // from either source falls through to the other.
  const isSuperseded =
    taskDetail?.status === 'superseded' ||
    progressTask?.status === 'superseded' ||
    effectiveStatus === 'superseded';
  const supersededReason = taskDetail?.note || progressTask?.note;

  // Whether the body has anything to render beyond the header. Heading-only
  // tasks (created with just a description, no detail body) load a taskDetail
  // with an empty description and no files/changes — without this the body
  // would be a blank box, reading as a load failure rather than "nothing more".
  const hasDetailBody = Boolean(
    taskDetail?.description ||
      taskDetail?.filesToModify?.length ||
      taskDetail?.filesToCreate?.length ||
      taskDetail?.expectedChanges?.length,
  );
  const showNoDetailsHint = !hasDetailBody && !(isSuperseded && supersededReason);

  // Slug path — the external task identifier (F6-T5); never the UUID.
  const slugPath = fixId
    ? formatFixTaskSlugPath(fixId, taskNumber)
    : planId && featureId
      ? formatPrdTaskSlugPath(planId, featureId, taskNumber)
      : `Task ${taskNumber}`;

  // Title leads the header; fall back to the progress description (fix/no-API
  // tasks before detail loads) and finally the slug so it's never blank.
  const headerTitle = taskDetail?.title ?? progressTask?.description ?? slugPath;

  return (
    <div className="flex flex-col h-full">
      {/* Header — id + status pill (+ close) lead; title then slug beneath. */}
      <div className="bg-gray-200 dark:bg-gray-900 border-b border-border dark:border-dark-border">
        <div className="p-4 space-y-1.5">
          {/* Line 1: task id · status pill · close */}
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-2 min-w-0">
              <span className="text-xs font-mono text-muted-foreground">task-{taskNumber}</span>
              <StatusPill label={getStatusLabel()} tone={getStatusTone()} />
            </div>
            <button
              onClick={onClose}
              aria-label="Close"
              className="flex-shrink-0 p-1 rounded-md hover:bg-gray-300 dark:hover:bg-gray-800 transition-colors"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
          {/* Line 2: title */}
          <h2 className="text-base font-semibold leading-snug">{headerTitle}</h2>
          {/* Line 3: slug */}
          <div data-testid="task-slug-path" className="text-xs font-mono text-muted-foreground">
            {slugPath}
          </div>
        </div>

        {/* Tab bar */}
        <div className="flex border-b border-border dark:border-dark-border px-4" role="tablist">
          <button
            role="tab"
            aria-selected={activeTab === 'details'}
            onClick={() => setActiveTab('details')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'details'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            Details
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'timeline'}
            onClick={() => setActiveTab('timeline')}
            className={`px-3 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'timeline'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-muted-foreground hover:text-foreground'
            }`}
          >
            Timeline
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4">
        {activeTab === 'timeline' ? (
          telemetryLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : telemetryError ? (
            <div className="flex items-start gap-3 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-red-700 dark:text-red-400">Error loading timeline</p>
                <p className="text-sm text-red-600 dark:text-red-300 mt-1">{telemetryError}</p>
              </div>
            </div>
          ) : (
            <TaskTimeline events={telemetryEvents} />
          )
        ) : (
        <>
        {loading && (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        )}

        {error && (
          <div className="flex items-start gap-3 p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
            <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0 mt-0.5" />
            <div>
              <p className="font-medium text-red-700 dark:text-red-400">Error loading task details</p>
              <p className="text-sm text-red-600 dark:text-red-300 mt-1">{error}</p>
            </div>
          </div>
        )}

        {/* Fallback when there's no API task detail: the header title already
            surfaces the progress description, so the body only carries the
            superseded note (when present) rather than repeating the title. */}
        {!taskDetail && !loading && !error && progressTask && (
          <div className="space-y-6">
            {/* Superseded Note */}
            {isSuperseded && supersededReason && (
              <div className="p-3 bg-orange-50 dark:bg-orange-900/20 rounded-lg border border-orange-200 dark:border-orange-800">
                <h3 className="text-xs font-semibold text-orange-700 dark:text-orange-400 uppercase mb-1">
                  Superseded Reason
                </h3>
                <p className="text-sm text-orange-600 dark:text-orange-300">{supersededReason}</p>
              </div>
            )}
            {showNoDetailsHint && (
              <p data-testid="task-no-details" className="text-sm text-muted-foreground italic">
                No further details recorded — the title above is the task's full description.
              </p>
            )}
          </div>
        )}

        {taskDetail && !loading && !error && (
          <div className="space-y-6">
            {/* Description */}
            {taskDetail.description && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2">
                  Description
                </h3>
                <p className="text-sm whitespace-pre-wrap">{taskDetail.description}</p>
              </div>
            )}

            {/* Files to Modify */}
            {taskDetail.filesToModify && taskDetail.filesToModify.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2 flex items-center gap-2">
                  <FileCode className="h-4 w-4" />
                  Files to Modify
                </h3>
                <ul className="space-y-1">
                  {taskDetail.filesToModify.map((file, index) => (
                    <li
                      key={index}
                      className="text-sm font-mono bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded"
                    >
                      {file}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Files to Create */}
            {taskDetail.filesToCreate && taskDetail.filesToCreate.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2 flex items-center gap-2">
                  <FolderPlus className="h-4 w-4" />
                  Files to Create
                </h3>
                <ul className="space-y-1">
                  {taskDetail.filesToCreate.map((file, index) => (
                    <li
                      key={index}
                      className="text-sm font-mono bg-green-50 dark:bg-green-900/20 px-2 py-1 rounded text-green-700 dark:text-green-400"
                    >
                      {file}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Expected Changes */}
            {taskDetail.expectedChanges && taskDetail.expectedChanges.length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-2 flex items-center gap-2">
                  <CheckSquare className="h-4 w-4" />
                  Expected Changes
                </h3>
                <ul className="space-y-2">
                  {taskDetail.expectedChanges.map((change, index) => (
                    <li key={index} className="text-sm flex items-start gap-2">
                      <span className="text-muted-foreground">•</span>
                      <span>{change}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Superseded Note — for a standard PRD task the reason lives in
                the markdown body (taskDetail.note); progressTask.note is the
                manual-task fallback. See isSuperseded/supersededReason above. */}
            {isSuperseded && supersededReason && (
              <div className="p-3 bg-orange-50 dark:bg-orange-900/20 rounded-lg border border-orange-200 dark:border-orange-800">
                <h3 className="text-xs font-semibold text-orange-700 dark:text-orange-400 uppercase mb-1">
                  Superseded Reason
                </h3>
                <p className="text-sm text-orange-600 dark:text-orange-300">{supersededReason}</p>
              </div>
            )}

            {/* Heading-only task: nothing more than the title to show. */}
            {showNoDetailsHint && (
              <p data-testid="task-no-details" className="text-sm text-muted-foreground italic">
                No further details recorded — the title above is the task's full description.
              </p>
            )}
          </div>
        )}
        </>
        )}
      </div>

      {/* Footer - Commit Trail. Grey-tinted to read as a distinct band below
          the content body; lists every commit on the task — red, green, each
          review commit, and each refactor. */}
      {commitTrailTask && (commitTrailTask.testCommitSha || commitTrailTask.commitSha || commitTrailTask.reviews) && (
        <div className="border-t border-border dark:border-dark-border bg-gray-100 dark:bg-gray-800/40 p-4">
          <h3 className="text-xs font-semibold text-muted-foreground uppercase mb-3">
            Commit Trail
          </h3>
          <div className="space-y-2">
            {commitTrailTask.testCommitSha && (
              <div className="flex items-center justify-between text-sm">
                <span className="text-red-600 dark:text-red-400 font-medium">{getStepEmoji('red')} {getStepLabel('red')}</span>
                <span className="font-mono text-xs">{commitTrailTask.testCommitSha.substring(0, 7)}</span>
              </div>
            )}
            {commitTrailTask.commitSha && (
              <div className="flex items-center justify-between text-sm">
                <span className="text-green-600 dark:text-green-400 font-medium">{getStepEmoji('green')} {getStepLabel('green')}</span>
                <span className="font-mono text-xs">{commitTrailTask.commitSha.substring(0, 7)}</span>
              </div>
            )}
            {commitTrailTask.reviews && Object.entries(commitTrailTask.reviews).flatMap(([type, review]) => {
              const label = getStepLabel(type);
              const items: React.ReactElement[] = [];
              if (review.reviewSha) {
                items.push(
                  <div key={`${type}-review`} className="flex items-center justify-between text-sm">
                    <span className="text-purple-600 dark:text-purple-400 font-medium">
                      {getStepEmoji(type)} {label}
                    </span>
                    <span className="font-mono text-xs">{review.reviewSha.substring(0, 7)}</span>
                  </div>
                );
              }
              if (review.refactorCommitSha) {
                items.push(
                  <div key={`${type}-refactor`} className="flex items-center justify-between text-sm">
                    <span className="text-blue-600 dark:text-blue-400 font-medium">
                      {getStepEmoji('refactor')} {label} Refactor
                    </span>
                    <span className="font-mono text-xs">{review.refactorCommitSha.substring(0, 7)}</span>
                  </div>
                );
              }
              return items;
            })}
          </div>
        </div>
      )}
    </div>
  );
};

const TaskDetailPanel: React.FC<TaskDetailPanelProps> = ({
  isOpen,
  onClose,
  repoId,
  planId,
  featureId,
  fixId,
  taskNumber,
  progressTask,
}) => {
  const { open, close } = useDetailsPopover();

  const handleClose = () => {
    close();
  };

  useEffect(() => {
    if (isOpen) {
      open(
        <TaskDetailContent
          repoId={repoId}
          planId={planId}
          featureId={featureId}
          fixId={fixId}
          taskNumber={taskNumber}
          progressTask={progressTask}
          onClose={handleClose}
        />,
        { width: 'w-[480px]', onClose }
      );
    } else {
      close();
    }
  }, [isOpen, repoId, planId, featureId, fixId, taskNumber, progressTask]);

  return null;
};

export default TaskDetailPanel;
