import React from 'react';
import type { StepScoreResponse } from '../types';
import { tintColor, darkTintColor, borderColor } from '../utils/color';
import { useTheme } from '../contexts/ThemeContext';

export interface QipProgress {
  completed: number;
  total: number;
}

interface QualityStepCardProps {
  step: StepScoreResponse;
  hasQip?: boolean;
  qipProgress?: QipProgress;
}

/** Steps that show a real percentage with gauge bar */
const PERCENTAGE_STEPS = new Set(['coverage']);

export const QualityStepCard: React.FC<QualityStepCardProps> = ({ step, hasQip, qipProgress }) => {
  const { emoji, label, score, threshold, passing, findingsCount, color, packageBreakdown, skippedTests } = step;
  const baseColor = color ?? '#6b7280';
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === 'dark';
  const isPercentage = PERCENTAGE_STEPS.has(step.type);
  const allTasksDone = qipProgress ? qipProgress.total > 0 && qipProgress.completed === qipProgress.total : false;
  const isClean = qipProgress ? allTasksDone : (isPercentage ? passing : findingsCount === 0);
  const hasProblems = qipProgress ? !allTasksDone : (isPercentage ? !passing : findingsCount > 0);

  // Green for clean, orange for issues, default tint otherwise
  const cardBg = isClean
    ? (isDark ? 'oklch(0.25 0.03 145)' : 'oklch(0.96 0.02 145)')
    : hasProblems
    ? (isDark ? 'oklch(0.25 0.04 55)' : 'oklch(0.96 0.03 55)')
    : (isDark ? darkTintColor(baseColor, 0.85) : tintColor(baseColor, 0.92));
  const cardBorder = isClean
    ? (isDark ? 'oklch(0.35 0.05 145)' : 'oklch(0.85 0.05 145)')
    : hasProblems
    ? (isDark ? 'oklch(0.4 0.08 55)' : 'oklch(0.8 0.08 55)')
    : borderColor(baseColor);

  return (
    <div
      className="rounded-lg border p-4"
      style={{
        borderColor: cardBorder,
        backgroundColor: cardBg,
      }}
      data-testid="step-card"
    >
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-lg">{emoji}</span>
          <span className="font-medium text-sm">{label}</span>
          {hasQip && (
            <span className="text-[10px] font-semibold px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-400">
              QIP
            </span>
          )}
        </div>
        {qipProgress ? (
          <span className={`text-sm font-bold ${
            allTasksDone
              ? 'text-green-600 dark:text-green-400'
              : 'text-gray-900 dark:text-gray-100'
          }`}>
            {qipProgress.completed}/{qipProgress.total} tasks
          </span>
        ) : isPercentage ? (
          <span className="text-lg font-bold">{score}%</span>
        ) : (
          <span className={`text-sm font-bold ${
            findingsCount === 0
              ? 'text-green-600 dark:text-green-400'
              : 'text-gray-900 dark:text-gray-100'
          }`}>
            {findingsCount} {findingsCount === 1 ? 'issue' : 'issues'}
          </span>
        )}
      </div>

      {/* Coverage: per-package bars or single gauge (hidden when showing QIP progress) */}
      {!qipProgress && isPercentage && packageBreakdown && Object.keys(packageBreakdown).length > 0 ? (
        <div className="mt-2 space-y-1.5">
          {Object.entries(packageBreakdown)
            .sort(([, a], [, b]) => a.pct - b.pct)
            .map(([pkg, data]) => {
              const pkgPassing = data.pct >= threshold;
              return (
                <div key={pkg}>
                  <div className="flex items-center justify-between text-xs mb-0.5">
                    <span className="text-muted-foreground truncate mr-2">{pkg}</span>
                    <span className={`font-medium ${pkgPassing ? 'text-green-600 dark:text-green-400' : 'text-red-500 dark:text-red-400'}`}>
                      {data.pct.toFixed(0)}%
                    </span>
                  </div>
                  <div className="relative w-full bg-gray-200 dark:bg-gray-700 rounded-full h-1.5">
                    <div
                      className={`h-1.5 rounded-full transition-all ${pkgPassing ? 'bg-green-500 dark:bg-green-400' : 'bg-red-500 dark:bg-red-400'}`}
                      style={{ width: `${Math.min(data.pct, 100)}%` }}
                    />
                    <div
                      className="absolute top-0 h-1.5 w-0.5 bg-gray-500 dark:bg-gray-300"
                      style={{ left: `${threshold}%` }}
                    />
                  </div>
                </div>
              );
            })}
        </div>
      ) : !qipProgress && isPercentage ? (
        <>
          <div className="relative w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mt-2 mb-1">
            <div
              data-testid="step-score-gauge"
              data-state={passing ? 'passing' : 'failing'}
              className={`h-2 rounded-full transition-all ${passing ? 'bg-green-500 dark:bg-green-400' : 'bg-red-500 dark:bg-red-400'}`}
              style={{ width: `${score}%` }}
            />
            <div
              data-testid="step-threshold-marker"
              className="absolute top-0 h-2 w-0.5 bg-gray-500 dark:bg-gray-300"
              style={{ left: `${threshold}%` }}
            />
          </div>
          <div className="flex items-center justify-end text-xs text-muted-foreground">
            <span>threshold: {threshold}%</span>
          </div>
        </>
      ) : null}

      {/* Skipped tests badge (coverage only) */}
      {isPercentage && (skippedTests ?? 0) > 0 && (
        <div className="mt-1.5 text-xs text-amber-600 dark:text-amber-400">
          {skippedTests} skipped {skippedTests === 1 ? 'test' : 'tests'}
        </div>
      )}
    </div>
  );
};
