import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Flag } from 'lucide-react';

export type SpikeOutcomeStatus = 'validated' | 'invalidated' | 'abandoned';

const STATUS_OPTIONS: ReadonlyArray<{
  readonly status: SpikeOutcomeStatus;
  readonly label: string;
  readonly hint: string;
  readonly className: string;
}> = [
  {
    status: 'validated',
    label: 'Validated',
    hint: 'The approach works — record what you proved.',
    className:
      'border-emerald-300 dark:border-emerald-700 text-emerald-700 dark:text-emerald-200 hover:bg-emerald-50 dark:hover:bg-emerald-900/30 data-[selected=true]:bg-emerald-100 data-[selected=true]:dark:bg-emerald-900/40',
  },
  {
    status: 'invalidated',
    label: 'Invalidated',
    hint: 'The approach does not work — record what was disproved.',
    className:
      'border-sky-300 dark:border-sky-700 text-sky-700 dark:text-sky-200 hover:bg-sky-50 dark:hover:bg-sky-900/30 data-[selected=true]:bg-sky-100 data-[selected=true]:dark:bg-sky-900/40',
  },
  {
    status: 'abandoned',
    label: 'Abandoned',
    hint: 'Stopped before reaching a conclusion — record why.',
    className:
      'border-amber-300 dark:border-amber-700 text-amber-700 dark:text-amber-200 hover:bg-amber-50 dark:hover:bg-amber-900/30 data-[selected=true]:bg-amber-100 data-[selected=true]:dark:bg-amber-900/40',
  },
];

export interface SpikeOutcomeCaptureProps {
  readonly repoId: string;
  readonly spikeId: string;
  readonly onCompleted?: () => void;
}

/**
 * Inline outcome-capture card shown on SpikeDetail for in_progress
 * spikes. The user picks one of the three terminal statuses,
 * authors the outcome narrative, and submits — the API writes both
 * the frontmatter status and the doc body's Outcome section. After
 * success the parent refetches so the SpikeDetail pane updates.
 *
 * Kept inline (not a modal) because the outcome narrative often
 * runs to multiple paragraphs — a modal would force the user away
 * from the criteria / question context they were just looking at.
 */
export function SpikeOutcomeCapture({
  repoId,
  spikeId,
  onCompleted,
}: SpikeOutcomeCaptureProps) {
  const [selectedStatus, setSelectedStatus] = useState<SpikeOutcomeStatus | null>(null);
  const [outcome, setOutcome] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const trimmed = outcome.trim();
  const canSubmit = selectedStatus !== null && trimmed.length > 0 && !submitting;

  const submit = async () => {
    if (!canSubmit || selectedStatus === null) return;
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/spikes/${encodeURIComponent(spikeId)}/outcome`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: selectedStatus, outcome: trimmed }),
        },
      );
      if (!mounted.current) return;
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        if (!mounted.current) return;
        setError(
          typeof body.error === 'string'
            ? body.error
            : `Failed to record outcome (${res.status})`,
        );
        return;
      }
      // Parent refetches the spike — that triggers the SpikeDetail to
      // re-render with the terminal status, replacing this card with
      // the outcome banner. Reset internal state in case the parent
      // remounts us (e.g. a different spike of the same id).
      setOutcome('');
      setSelectedStatus(null);
      onCompleted?.();
    } catch (err) {
      if (!mounted.current) return;
      setError(err instanceof Error ? err.message : 'Network error');
    } finally {
      if (mounted.current) setSubmitting(false);
    }
  };

  const hint =
    STATUS_OPTIONS.find((o) => o.status === selectedStatus)?.hint ??
    'Pick a terminal status to record the spike’s outcome.';

  return (
    <Card data-testid="spike-outcome-capture" className="gap-2 py-3">
      <CardHeader className="px-3 pb-0">
        <CardTitle className="text-lg flex items-center gap-2">
          <Flag className="h-5 w-5 text-orange-500" />
          Record Outcome
        </CardTitle>
      </CardHeader>
      <CardContent className="px-3 space-y-3">
        <div className="flex flex-wrap gap-2" role="radiogroup" aria-label="Spike outcome status">
          {STATUS_OPTIONS.map((opt) => (
            <button
              key={opt.status}
              type="button"
              role="radio"
              aria-checked={selectedStatus === opt.status}
              data-selected={selectedStatus === opt.status}
              data-status={opt.status}
              onClick={() => {
                setSelectedStatus(opt.status);
                // Clear a stale error so the alert doesn't linger
                // contradicting the user's new action.
                if (error !== null) setError(null);
              }}
              className={cn(
                'px-3 py-1.5 text-xs font-medium rounded-md border transition-colors',
                opt.className,
              )}
            >
              {opt.label}
            </button>
          ))}
        </div>

        <p className="text-xs text-muted-foreground">{hint}</p>

        <label className="block text-xs text-muted-foreground" htmlFor="spike-outcome-narrative">
          Outcome narrative (markdown)
        </label>
        <textarea
          id="spike-outcome-narrative"
          data-testid="spike-outcome-narrative"
          value={outcome}
          onChange={(e) => {
            setOutcome(e.target.value);
            if (error !== null) setError(null);
          }}
          rows={5}
          className="w-full text-sm rounded border border-muted-foreground/30 px-3 py-2 bg-background font-mono"
          placeholder="What did the spike prove or disprove? Include any surprises, references, follow-ups."
        />

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={submit}
            disabled={!canSubmit}
            className="px-3 py-1.5 text-sm rounded bg-blue-600 text-white disabled:opacity-40 disabled:cursor-not-allowed hover:bg-blue-700"
          >
            {submitting ? 'Recording…' : 'Record Outcome'}
          </button>
          {error && (
            <span role="alert" className="text-xs text-red-600 dark:text-red-400">
              {error}
            </span>
          )}
        </div>
      </CardContent>
    </Card>
  );
}
