import React, { useState, useMemo, useEffect } from 'react';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, FileCode, Wrench, AlertCircle, Archive } from 'lucide-react';
import DetailHeaderBar from './DetailHeaderBar';
import DetailSubHeader from './DetailSubHeader';
import type { DetailSubHeaderDate } from './DetailSubHeader';
import type { Fix } from '../types';
import TestPlanBadge from './TestPlanBadge';
import TestPlanDetail from './TestPlanDetail';
import TaskRow from './TaskRow';
import { usePipelineConfig } from '../hooks/usePipelineConfig';
import { taskPhaseProgress } from '../utils/task-progress';
import { formatTaskComponentSlug } from '../utils/task-slug-path';
import TaskDetailPanel from './TaskDetailPanel';
import { fetchFixContent } from '../services/api';

interface FixDetailProps {
  fix: Fix;
  repoId: string;
  onArchive?: () => void;
  onUnarchive?: () => void;
}

const severityColors = {
  low: 'bg-blue-100 text-blue-800 border-[oklch(0.71_0.13_254)] dark:bg-blue-900 dark:text-blue-300 dark:border-[oklch(0.50_0.13_254)]',
  medium: 'bg-yellow-100 text-yellow-800 border-[oklch(0.82_0.14_90)] dark:bg-yellow-900 dark:text-yellow-300 dark:border-[oklch(0.55_0.11_90)]',
  high: 'bg-orange-100 text-orange-800 border-[oklch(0.75_0.16_55)] dark:bg-orange-900 dark:text-orange-300 dark:border-[oklch(0.55_0.14_55)]',
  critical: 'bg-red-100 text-red-800 border-[oklch(0.64_0.21_27)] dark:bg-red-900 dark:text-red-300 dark:border-[oklch(0.50_0.18_27)]',
};

const statusLabels = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Complete',
  superseded: 'Superseded',
};

const statusColors = {
  not_started: 'bg-gray-500',
  in_progress: 'bg-blue-500',
  completed: 'bg-green-500',
  superseded: 'bg-orange-500',
};

const FixDetail: React.FC<FixDetailProps> = ({ fix, repoId, onArchive, onUnarchive }) => {
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId);
  const [selectedTaskNumber, setSelectedTaskNumber] = useState<number | null>(null);
  const selectedTask = useMemo(() => {
    if (selectedTaskNumber === null) return null;
    const task = fix.tasks[selectedTaskNumber - 1];
    if (!task) return null; // guard against out-of-range after SSE update
    return { taskNumber: selectedTaskNumber, task };
  }, [selectedTaskNumber, fix.tasks]);
  const [activeTab, setActiveTab] = useState<'tasks' | 'details'>('tasks');
  const [fixContent, setFixContent] = useState<string | null>(null);
  const [contentLoading, setContentLoading] = useState(false);

  useEffect(() => {
    if (activeTab === 'details' && fixContent === null && !contentLoading) {
      setContentLoading(true);
      fetchFixContent(repoId, fix.id)
        .then(content => setFixContent(content))
        .catch(() => setFixContent('Failed to load fix content.'))
        .finally(() => setContentLoading(false));
    }
  }, [activeTab, fixContent, repoId, fix.id]);
  const completedCount = fix.tasks.filter(t => t.status === 'completed').length;
  const supersededCount = fix.tasks.filter(t => t.status === 'superseded').length;
  const doneTasks = completedCount + supersededCount;
  const totalTasks = fix.tasks.length;
  const { progress, completedPercent, supersededPercent } = useMemo(() => {
    if (totalTasks === 0) return { progress: 0, completedPercent: 0, supersededPercent: 0 };
    let completedWeight = 0;
    let supersededWeight = 0;
    for (const task of fix.tasks) {
      const fraction = taskPhaseProgress(task, reviewPipeline);
      if (task.status === 'superseded') {
        supersededWeight += fraction;
      } else {
        completedWeight += fraction;
      }
    }
    return {
      progress: Math.round(((completedWeight + supersededWeight) / totalTasks) * 100),
      completedPercent: Math.round((completedWeight / totalTasks) * 100),
      supersededPercent: Math.round((supersededWeight / totalTasks) * 100),
    };
  }, [fix.status, fix.tasks, reviewPipeline]);

  return (
    <div className="h-full flex flex-col">
      {/* Static identity bar — always visible: title + id left, pills + archive right */}
      <DetailHeaderBar
        testId="fix-header-bar"
        title={fix.title}
        id={fix.id}
        idKind="Fix"
        right={
          <>
            <Badge className={cn(severityColors[fix.severity], 'rounded')}>
              {fix.severity}
            </Badge>
            <Badge variant="outline" className="flex items-center gap-1.5 whitespace-nowrap font-normal border-gray-300 dark:border-gray-600 rounded">
              <span className={cn('w-2 h-2 rounded-full', statusColors[fix.status])} />
              {statusLabels[fix.status]}
            </Badge>
            {fix.archived === true ? (
              <>
                <Badge variant="outline" className="whitespace-nowrap font-normal border-gray-300 dark:border-gray-600 rounded">
                  Archived
                </Badge>
                <button
                  role="button"
                  onClick={onUnarchive}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-md border border-gray-300 dark:border-gray-600 text-gray-500 dark:text-gray-400 hover:bg-gray-100 hover:dark:bg-gray-700/50 hover:text-gray-700 dark:hover:text-gray-200 transition-all duration-200"
                  aria-label="Unarchive"
                >
                  <Archive className="h-4 w-4" />
                  Unarchive
                </button>
              </>
            ) : (
              <button
                role="button"
                onClick={onArchive}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-md border border-gray-300 dark:border-gray-600 text-gray-500 dark:text-gray-400 hover:bg-gray-100 hover:dark:bg-gray-700/50 hover:text-gray-700 dark:hover:text-gray-200 transition-all duration-200"
                aria-label="Archive"
              >
                <Archive className="h-4 w-4" />
                Archive
              </button>
            )}
          </>
        }
      />

      {/* Summary card — dates + progress + test plan. Pinned outside the
          scroll container (flex-shrink-0) so progress/dates context stays
          visible while the task list scrolls, below the identity header. */}
      <div className="flex-shrink-0 px-3 pt-3">
        <Card className="py-3">
          <CardContent className="px-3 space-y-3">
          <DetailSubHeader
            progressLabel="Progress"
            progressText={
              totalTasks === 0
                ? '0 tasks'
                : supersededCount > 0
                  ? `${completedCount} completed, ${supersededCount} superseded / ${totalTasks} tasks (${progress}%)`
                  : `${doneTasks}/${totalTasks} tasks (${progress}%)`
            }
            completedPercent={completedPercent}
            supersededPercent={supersededPercent}
            dates={[
              fix.reported ? { label: 'Reported', iso: fix.reported } : null,
              fix.resolved ? { label: 'Resolved', iso: fix.resolved } : null,
            ].filter((d): d is DetailSubHeaderDate => d !== null)}
          />

          {/* Test Plan Summary */}
          {fix.testPlan && (
            <div className="flex items-center gap-2">
              <span className="text-sm text-muted-foreground">Tests:</span>
              <TestPlanBadge testPlan={fix.testPlan} />
            </div>
          )}
          </CardContent>
        </Card>
      </div>

      <div data-testid="fix-scroll" className="flex-1 overflow-auto p-3 space-y-6">
      {/* Resolution Details - shown above tasks for resolved fixes */}
      {fix.resolution && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-lg flex items-center gap-2">
              <CheckCircle2 className="h-5 w-5 text-green-500" />
              Resolution
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Root Cause */}
            {fix.resolution.rootCause && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <AlertCircle className="h-4 w-4" />
                  Root Cause
                </h4>
                <p className="text-sm pl-6">{fix.resolution.rootCause}</p>
              </div>
            )}

            {/* Fix Steps */}
            {fix.resolution.fix && fix.resolution.fix.length > 0 && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <Wrench className="h-4 w-4" />
                  Fix Applied
                </h4>
                <ol className="text-sm pl-6 space-y-1 list-decimal list-inside">
                  {fix.resolution.fix.map((step, i) => (
                    <li key={i} className="text-sm">{typeof step === 'string' ? step : JSON.stringify(step)}</li>
                  ))}
                </ol>
              </div>
            )}

            {/* Files Modified */}
            {fix.resolution.filesModified && fix.resolution.filesModified.length > 0 && (
              <div>
                <h4 className="text-sm font-semibold flex items-center gap-2 mb-2 text-muted-foreground">
                  <FileCode className="h-4 w-4" />
                  Files Modified ({fix.resolution.filesModified.length})
                </h4>
                <ul className="text-xs pl-6 space-y-0.5 font-mono">
                  {fix.resolution.filesModified.map((file, i) => (
                    <li key={i} className="text-muted-foreground">{file}</li>
                  ))}
                </ul>
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Test Plan Detail */}
      <TestPlanDetail testPlan={fix.testPlan} />

      {/* Tabs */}
      <div>
        <div className="flex border-b border-gray-200 dark:border-gray-700" role="tablist">
          <button
            role="tab"
            aria-selected={activeTab === 'tasks'}
            onClick={() => setActiveTab('tasks')}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'tasks'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            Tasks
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'details'}
            onClick={() => setActiveTab('details')}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'details'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            Details
          </button>
        </div>

        {activeTab === 'tasks' && (
          <div className="mt-3">
            {fix.tasks.length === 0 ? (
              <p className="text-muted-foreground text-sm text-center py-4">No tasks defined</p>
            ) : (
              <div className="space-y-1">
                {fix.tasks.map((task, index) => (
                  <TaskRow
                    key={task.id}
                    task={task}
                    repoId={repoId}
                    onClick={() => setSelectedTaskNumber(index + 1)}
                    reviewPipeline={reviewPipeline}
                    slugPath={formatTaskComponentSlug(index + 1)}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'details' && (
          <div className="mt-3">
            {contentLoading ? (
              <p className="text-muted-foreground text-sm text-center py-4">Loading fix content...</p>
            ) : fixContent !== null ? (
              <pre className="text-sm whitespace-pre-wrap font-mono bg-muted/50 rounded-md p-4 overflow-auto max-h-[600px]">{fixContent}</pre>
            ) : (
              <p className="text-muted-foreground text-sm text-center py-4">No content available</p>
            )}
          </div>
        )}
      </div>
      </div>

      {selectedTask && (
        <TaskDetailPanel
          isOpen={true}
          onClose={() => setSelectedTaskNumber(null)}
          repoId={repoId}
          fixId={fix.id}
          taskNumber={selectedTask.taskNumber}
          progressTask={selectedTask.task}
        />
      )}
    </div>
  );
};

export default FixDetail;
