import React, { useEffect, useRef, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Circle, Play, CheckCircle2, FastForward, GitBranch } from 'lucide-react';
import type { TaskRowTask, TddPhase } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { deriveTddPhase } from '../utils/tdd-phases';
import TddPhasePipeline from './TddPhasePipeline';
import { applyDerivedState } from '../utils/apply-derived-state';
import { applyWorktreePhaseShas } from '../utils/worktree-aware-shas';
import { deriveEffectiveStatus } from '../utils/effective-task-status';
import CommitDetailsPopover from './CommitDetailsPopover';
import WorktreeIcon from './WorktreeIcon';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import AdversarialReviewPopover from './AdversarialReviewPopover';

interface ManualCompleteContext {
  readonly planId: string;
  readonly featureId: string;
  readonly taskNumber: number;
}

interface TaskRowProps {
  task: TaskRowTask;
  repoId: string;
  onClick?: () => void;
  reviewPipeline?: PipelineStep[];
  manualCompleteContext?: ManualCompleteContext;
  /**
   * Human slug path for the task (`<prd>/<feature>/task-N` etc.), rendered as
   * a subtle label above the description (stable-uuid-identity F6-T5). The
   * opaque UUID is never shown — slug paths are the only external identifier.
   */
  slugPath?: string;
  /**
   * The worktree the parent feature's work lives on (when uniform). When a task's
   * effective status comes from THIS same worktree, the per-task pill is
   * suppressed — the feature header already shows it. The pill renders only when
   * a task overrides to a different worktree.
   */
  featureWorktreeRef?: string;
}

const phaseLabels: Record<Exclude<TddPhase, 'complete'>, string> = {
  red: 'Writing failing tests (TDD red phase)..',
  green: 'Writing an implementation (TDD green phase)..',
  adversarial: "Reviewing what's been done..",
  'adversarial-refactor': 'Making things better (TDD refactor phase)..',
  mutation: 'Spawning mutants..',
  'mutation-refactor': 'Making things better post mutation (TDD refactor phase)..',
};

const statusConfig: Record<
  TaskRowTask['status'],
  { icon: React.FC<{ className?: string }>; title: string; iconClass: string }
> = {
  not_started: { icon: Circle, title: 'Not started', iconClass: 'text-muted-foreground' },
  in_progress: { icon: Play, title: 'In progress', iconClass: 'text-blue-500' },
  completed: { icon: CheckCircle2, title: 'Completed', iconClass: 'text-green-500' },
  superseded: { icon: CheckCircle2, title: 'Superseded', iconClass: 'text-orange-500' },
};

const phaseToCommitType = (phase: TddPhase): 'test' | 'feat' | 'refactor' => {
  switch (phase) {
    case 'red': return 'test';
    case 'green': return 'feat';
    default: return 'refactor';
  }
};

const TaskRow: React.FC<TaskRowProps> = ({ task, repoId, onClick, reviewPipeline, manualCompleteContext, slugPath, featureWorktreeRef }) => {
  const [selectedCommit, setSelectedCommit] = useState<{ sha: string; type: 'test' | 'feat' | 'refactor' } | null>(null);
  const [selectedReview, setSelectedReview] = useState<{ commitSha: string; reviewType: string } | null>(null);

  const handlePhaseClick = (phase: TddPhase, commitSha: string): void => {
    // Generic pipeline phases: review:{type}
    if (phase.startsWith('review:')) {
      setSelectedReview({ commitSha, reviewType: phase.slice(7) });
    // Legacy hardcoded phases
    } else if (phase === 'adversarial') {
      setSelectedReview({ commitSha, reviewType: 'adversarial' });
    } else if (phase === 'mutation') {
      setSelectedReview({ commitSha, reviewType: 'mutation' });
    } else {
      setSelectedCommit({ sha: commitSha, type: phaseToCommitType(phase) });
    }
  };

  // Overlay telemetry-derived state up front so the click gate and the
  // pipeline strip agree. Commit SHAs often arrive via telemetry
  // (`derivedState`) rather than the raw progress.json snapshot; gating
  // clickability on the raw task would leave every emoji inert even though
  // the strip renders the SHAs from the overlayed task.
  //
  // Then fill any phase SHA still missing on the launch ref from the per-ref
  // lattice (worktree/branch commits), so a task whose work lives only on a
  // worktree shows clickable phases whose tooltip + popover open that ref's own
  // git SHA — the strip and the popover stay consistent because both read this
  // single overlayed task (ADR-0007 / multi-ref-projection T5).
  const overlayed = applyWorktreePhaseShas(applyDerivedState(task, task.derivedState));
  const hasAnyPhaseCommit = !!(overlayed.testCommitSha || overlayed.commitSha);
  const enablePhaseClick = repoId && hasAnyPhaseCommit ? handlePhaseClick : undefined;

  // The row's status reflects the most-advanced ref: the launch-ref status,
  // unless a live worktree is strictly ahead (work completed/superseded there but
  // not on the launch ref). `effectiveTask` drives every status-keyed render —
  // icon, superseded marker, second-row text — so worktree work isn't shown as
  // not_started. `worktreeRef` tags where the status came from.
  const effective = deriveEffectiveStatus(overlayed);
  const effectiveTask = effective.status === overlayed.status ? overlayed : { ...overlayed, status: effective.status };

  // The LHS icon reflects work-in-flight, not only landed commits: once the red
  // phase (or green, if red was skipped) has STARTED, the task reads In progress
  // even before the first commit lands — matching the RHS pipeline strip, which
  // already renders on redStartedAt. These phase-start stamps come from the
  // event-derived live overlay (ADR-0007): this is display only — the persisted
  // git-sourced status is unchanged, so events still never write status.
  const hasStartedPhase = !!(overlayed.redStartedAt || overlayed.greenStartedAt);
  const displayStatus: TaskRowTask['status'] =
    effective.status === 'not_started' && hasStartedPhase ? 'in_progress' : effective.status;
  const { icon: Icon, title, iconClass } = statusConfig[displayStatus] ?? statusConfig.not_started;
  const iconTitle = effective.worktreeRef ? `${title} on ${effective.worktreeRef}` : title;
  // Show the per-task worktree pill only when the task's status comes from a
  // worktree the feature header isn't already showing (an override). When the
  // whole feature shares one worktree, the header carries it and the rows stay
  // clean.
  const showWorktreePill = !!effective.worktreeRef && effective.worktreeRef !== featureWorktreeRef;
  // The branch is the identity (where the status came from). When the task's
  // worktree assignment names the same branch, surface its dir name too — branch
  // and worktree are different axes, so the tooltip distinguishes them.
  const worktreeBranch = effective.worktreeRef;
  const worktreeName =
    task.worktree && task.worktree.branch === worktreeBranch ? task.worktree.name : undefined;
  const worktreeDiverges = !!worktreeName && worktreeName !== worktreeBranch;
  const worktreeTagLabel = worktreeDiverges
    ? `branch ${worktreeBranch}, worktree ${worktreeName}`
    : worktreeBranch;

  const isCompleted = effective.status === 'completed';
  const bgClass = isCompleted
    ? 'bg-green-50 dark:bg-green-950/30 border-green-200 dark:border-green-900'
    : 'border-muted';
  const hoverClass = onClick
    ? isCompleted
      ? 'cursor-pointer hover:bg-green-100 dark:hover:bg-green-950/50'
      : 'cursor-pointer hover:bg-muted/50'
    : '';

  return (
    <div
      className={`flex items-center gap-3 py-1.5 px-3 rounded-lg border ${bgClass} ${hoverClass}`}
      role={onClick ? 'button' : undefined}
      onClick={onClick}
    >
      {/* LHS — the task slug sits above the status icon (stable-uuid-identity
          F6-T5; the opaque UUID is never rendered). */}
      <div className="flex-shrink-0 self-stretch flex flex-col items-center justify-center gap-1.5">
        {slugPath && (
          <span data-testid="task-slug-path" className="font-mono text-[10px] leading-none text-muted-foreground/70 whitespace-nowrap text-center">
            {slugPath}
          </span>
        )}
        <div className="flex justify-center w-full" title={iconTitle}>
          <Icon className={`h-5 w-5 ${iconClass}`} />
        </div>
      </div>

      {/* Vertical separator dividing the LHS status/slug column from the content. */}
      <div className="flex-shrink-0 self-stretch w-px bg-border dark:bg-dark-border" aria-hidden="true" />

      {/* Content */}
      <div className="flex-1 min-w-0">
        {/* Task title */}
        <div className={`text-sm ${effectiveTask.status === 'superseded' ? 'line-through text-muted-foreground' : ''}`}>
          <ReactMarkdown remarkPlugins={[remarkGfm]} components={{ p: ({ children }) => <span>{children}</span> }}>
            {task.description}
          </ReactMarkdown>
        </div>

        {/* Second row — always visible. Reads effectiveTask so worktree-completed
            / -superseded work shows its real second-row text, not "Not started". */}
        {(() => {
          if (effectiveTask.status === 'superseded') {
            return <p className="text-xs text-orange-600 mt-0.5">{effectiveTask.note ?? 'Superseded'}</p>;
          }
          // Manual tasks have their own second-row vocabulary: the
          // completionNote on success, "Awaiting manual completion"
          // otherwise. The TDD-phase derivation below is meaningless for
          // them because they never traverse those phases.
          if (effectiveTask.pipelineType === 'manual') {
            if (effectiveTask.status === 'completed') {
              return (
                <p className="text-xs text-muted-foreground mt-0.5">
                  {effectiveTask.completionNote ?? 'Completed'}
                </p>
              );
            }
            return (
              <p className="text-xs text-muted-foreground italic mt-0.5">
                Awaiting manual completion
              </p>
            );
          }
          // Check for active TDD cycle — phase label takes priority over "Completed"
          const derived = deriveTddPhase(effectiveTask, reviewPipeline);
          if (derived !== 'complete' && derived !== 'red') {
            let label: string | undefined;
            if (derived.startsWith('review:')) {
              const type = derived.slice(7);
              const step = reviewPipeline?.find(s => s.type === type);
              label = step ? `${step.label} review in progress..` : `${type} review in progress..`;
            } else if (derived.startsWith('refactor:')) {
              const type = derived.slice(9);
              const step = reviewPipeline?.find(s => s.type === type);
              label = step ? `Refactoring after ${step.label} review..` : `Refactoring after ${type} review..`;
            } else {
              label = phaseLabels[derived as keyof typeof phaseLabels];
            }
            if (label) {
              return <p className="text-xs text-muted-foreground italic mt-0.5">{label}</p>;
            }
          }
          // Red phase also gets a label when task has started TDD
          if (derived === 'red' && effectiveTask.redStartedAt) {
            return <p className="text-xs text-muted-foreground italic mt-0.5">{phaseLabels.red}</p>;
          }
          if (effectiveTask.status === 'completed') {
            return effectiveTask.completedAt
              ? <p className="text-xs text-muted-foreground mt-0.5">Completed at {new Date(effectiveTask.completedAt).toLocaleDateString()}</p>
              : <p className="text-xs text-muted-foreground mt-0.5">Completed</p>;
          }
          return <p className="text-xs text-muted-foreground mt-0.5">Not started</p>;
        })()}
      </div>

      {/* Right-hand affordance — see renderRightCell. Uses effectiveTask so a
          task superseded on a worktree shows the fast-forward marker. */}
      {renderRightCell({
        task: effectiveTask,
        repoId,
        reviewPipeline,
        manualCompleteContext,
        onPhaseClick: enablePhaseClick,
      })}

      {/* Worktree override — far right, after the phase strip: a vertical divider
          then a branch-icon pill (worktree name on hover). Shown only when this
          task's status comes from a worktree the feature header isn't already
          showing (ADR-0007 / multi-ref-projection). */}
      {showWorktreePill && (
        <>
          <div className="flex-shrink-0 self-stretch w-px bg-border dark:bg-dark-border" aria-hidden="true" />
          <Tooltip>
            <TooltipTrigger asChild>
              <span
                data-testid="effective-status-worktree-tag"
                aria-label={worktreeTagLabel}
                onClick={(e) => e.stopPropagation()}
                className="flex-shrink-0 inline-flex items-center justify-center px-1.5 py-0.5 rounded border border-[oklch(0.72_0.13_300)] dark:border-[oklch(0.55_0.15_300)] bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-300"
              >
                <GitBranch className="h-3 w-3" />
              </span>
            </TooltipTrigger>
            <TooltipContent side="bottom">
              {worktreeDiverges ? (
                <span className="flex flex-col gap-0.5">
                  <span className="flex items-center gap-1">
                    <GitBranch className="h-3 w-3 flex-shrink-0" />
                    {worktreeBranch}
                  </span>
                  <span className="flex items-center gap-1">
                    <WorktreeIcon />
                    {worktreeName}
                  </span>
                </span>
              ) : (
                <span className="flex items-center gap-1">
                  <GitBranch className="h-3 w-3 flex-shrink-0" />
                  {worktreeName && <WorktreeIcon />}
                  {worktreeBranch}
                </span>
              )}
            </TooltipContent>
          </Tooltip>
        </>
      )}

      <CommitDetailsPopover
        commitSha={selectedCommit?.sha ?? ''}
        commitType={selectedCommit?.type ?? 'test'}
        repoId={repoId}
        open={selectedCommit !== null}
        onOpenChange={(open) => { if (!open) setSelectedCommit(null); }}
      />

      <AdversarialReviewPopover
        commitSha={selectedReview?.commitSha ?? ''}
        repoId={repoId}
        reviewType={selectedReview?.reviewType ?? 'adversarial'}
        open={selectedReview !== null}
        onOpenChange={(open) => { if (!open) setSelectedReview(null); }}
      />
    </div>
  );
};

/**
 * Decides what (if anything) renders in the right-hand cell of a TaskRow.
 * Manual tasks get the markdown-edit affordance (suppressing the TDD
 * timeline entirely); everything else falls back to the standard pipeline
 * timeline, which itself only renders once the task has activity.
 */
interface RenderRightCellArgs {
  task: TaskRowTask;
  repoId: string;
  reviewPipeline?: PipelineStep[];
  manualCompleteContext?: ManualCompleteContext;
  onPhaseClick?: (phase: TddPhase, commitSha: string) => void;
}

function renderRightCell({
  task,
  repoId,
  reviewPipeline,
  manualCompleteContext,
  onPhaseClick,
}: RenderRightCellArgs): React.ReactNode {
  if (task.status === 'superseded') {
    // Superseded tasks skipped the pipeline. The orange tick on the left
    // marks the terminal state; this fast-forward marker echoes that the
    // task was fast-forwarded past, sitting where the pipeline strip would.
    return (
      <div className="flex-shrink-0 flex justify-center" title="Superseded — skipped">
        <FastForward className="h-5 w-5 text-orange-500" />
      </div>
    );
  }

  if (task.pipelineType === 'manual') {
    // No manualCompleteContext means the parent hasn't plumbed the
    // identifiers through yet — render nothing rather than a half-broken
    // UI. Add the context at the call site to enable the affordance.
    if (!manualCompleteContext) return null;
    return (
      <div className="flex-shrink-0" onClick={(e) => e.stopPropagation()}>
        <ManualCompleteAffordance
          task={task}
          repoId={repoId}
          context={manualCompleteContext}
        />
      </div>
    );
  }

  // `task` is already telemetry-overlayed by the caller (TaskRow), so the
  // strip and the click gate read the same derived fields. The overlay
  // makes derived fields win where present and falls back to the raw task
  // fields where derivedState is empty (legacy tasks, fresh clones,
  // missing-hooks scenarios). See fix: dashboard-pipeline-not-derived-from-telemetry
  // (the embed/overlay) and pipeline-emoji-popover-not-clickable (the
  // single-overlay hoist).
  const hasTddActivity = !!(task.redStartedAt || task.testCommitSha);
  if (task.status === 'not_started' && !hasTddActivity) return null;

  return (
    <div className="flex-shrink-0" onClick={(e) => e.stopPropagation()}>
      <TddPhasePipeline
        task={task}
        repoId={repoId}
        reviewPipeline={reviewPipeline}
        onPhaseClick={onPhaseClick}
      />
    </div>
  );
}

/**
 * Inline button → expanded note form for manual-pipelineType tasks.
 * Closed state shows "Mark complete"; open state shows a textarea + Submit,
 * which POSTs to the manual-complete endpoint and lets the dashboard's
 * existing file-watcher pick up the resulting sync.
 *
 * The note is optional. Trivial gates ("verify staging works") submit fine
 * with empty input; the server omits the `completionNote:` markdown line
 * entirely when there's nothing to record.
 */
interface ManualCompleteAffordanceProps {
  task: TaskRowTask;
  repoId: string;
  context: ManualCompleteContext;
}

const ManualCompleteAffordance: React.FC<ManualCompleteAffordanceProps> = ({ task, repoId, context }) => {
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // On success the file-watcher refreshes this task to status: completed,
  // which causes the right-hand cell to swap and this component to unmount
  // mid-`fetch`. Guard the post-await state writes so React doesn't warn
  // (and so error/submitting flags don't get re-set on the dead instance).
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  if (task.status === 'completed') return null;

  const trimmed = note.trim();
  // The note is optional — trivial gates like "verify staging works"
  // don't need an audit blurb. Only `submitting` disables the button.
  const canSubmit = !submitting;

  const submit = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/plans/${encodeURIComponent(context.planId)}/features/${encodeURIComponent(context.featureId)}/tasks/${context.taskNumber}/manual-complete`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completionNote: trimmed }),
        },
      );
      if (!mounted.current) return;
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        if (!mounted.current) return;
        setError(typeof body.error === 'string' ? body.error : `Failed (${res.status})`);
        return;
      }
      setOpen(false);
      setNote('');
    } catch (err) {
      if (!mounted.current) return;
      setError(err instanceof Error ? err.message : 'Network error');
    } finally {
      if (mounted.current) setSubmitting(false);
    }
  };

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="px-2 py-1 text-xs rounded border border-blue-300 text-blue-700 hover:bg-blue-50 dark:border-blue-700 dark:text-blue-300 dark:hover:bg-blue-950/30"
      >
        Mark complete
      </button>
    );
  }

  return (
    <div className="flex flex-col gap-1 min-w-[220px]">
      <label className="text-xs text-muted-foreground" htmlFor={`manual-note-${task.id}`}>
        Completion note
      </label>
      <textarea
        id={`manual-note-${task.id}`}
        value={note}
        onChange={(e) => setNote(e.target.value)}
        rows={2}
        className="text-xs rounded border border-muted-foreground/30 px-2 py-1 bg-background"
        placeholder="What was verified / done?"
      />
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={submit}
          disabled={!canSubmit}
          className="px-2 py-1 text-xs rounded bg-blue-600 text-white disabled:opacity-40 disabled:cursor-not-allowed hover:bg-blue-700"
        >
          Submit
        </button>
        <button
          type="button"
          onClick={() => { setOpen(false); setError(null); }}
          className="px-2 py-1 text-xs rounded border border-muted-foreground/30 hover:bg-muted/50"
        >
          Cancel
        </button>
        {error && <span role="alert" className="text-xs text-red-600">{error}</span>}
      </div>
    </div>
  );
};

export default TaskRow;
