import { useState } from 'react';
import { ChevronDown, ChevronUp } from 'lucide-react';
import type { TelemetryEvent } from '@magic-ingredients/tiny-brain-core';
import { getStepEmoji, getStepLabel } from '../utils/step-display';

interface PhaseGroup {
  readonly phase: string;
  readonly events: TelemetryEvent[];
  readonly duration_ms?: number;
  readonly sha?: string;
}

interface Attempt {
  readonly attempt: number;
  readonly groups: PhaseGroup[];
}

/**
 * The phase an event belongs to, or null for "attach-only" events
 * (task.completed, reminders, …) that join whatever group is open
 * rather than defining one. A commit.tracked maps to its TDD phase —
 * workers emit it just *before* the phase.entered for that phase, so a
 * test/feat/refactor commit anchors the red/green/refactor group it
 * precedes.
 */
function semanticPhase(event: TelemetryEvent): string | null {
  switch (event.kind) {
    case 'phase.entered':
    case 'phase.completed':
      return event.phase;
    case 'commit.tracked':
      if (event.type === 'test') return 'red';
      if (event.type === 'feat' || event.type === 'fix') return 'green';
      if (event.type === 'refactor') return 'refactor:post-review';
      return 'unknown';
    case 'pipeline.decision':
    case 'persist.review_written':
      return `review:${event.gate}`;
    default:
      return null;
  }
}

/**
 * review-verdict-as-its-own-commit Task 6: a review is one thing. Once the
 * verdict has its own `persist.review_written` event, a `pipeline.decision` for
 * the same (gate, sha) is the redundant duplicate the timeline used to render as
 * a second "Decision" row. Drop it so the timeline reads as the four-step shape
 * (review written · refactor) — but only when a sibling persist exists. A legacy
 * `pipeline.decision` with no persist is the sole review signal and stays.
 */
function isRedundantDecision(event: TelemetryEvent, all: readonly TelemetryEvent[]): boolean {
  if (event.kind !== 'pipeline.decision') return false;
  return all.some(
    (e) =>
      e.kind === 'persist.review_written' &&
      e.gate === event.gate &&
      e.sha === event.sha,
  );
}

// Collapse phase variants to a family key for grouping: every refactor:*
// is one Refactor group; review gates stay distinct (adversarial vs
// mutation are separate phases); red/green/complete/unknown are themselves.
function phaseFamily(phase: string): string {
  if (phase.startsWith('refactor:')) return 'refactor';
  return phase;
}

/**
 * Sort events by timestamp, then group into attempts → phases.
 *
 * A re-run (rebase + re-execute) produces multiple full red→green→refactor
 * cycles in one log. Each cycle is its own "attempt": a `red` phase that
 * opens after the current attempt has already advanced past red starts a
 * fresh attempt. Within an attempt, consecutive events of the same phase
 * family coalesce into one group — so the (commit, phase.entered) pairs the
 * producer emits, and any repeated phase.entered, render as a single phase
 * section instead of duplicating. No commit-relocation splice: chronological
 * order is the contract.
 */
function groupIntoAttempts(events: readonly TelemetryEvent[]): Attempt[] {
  const sorted = [...events].sort(
    (a, b) => new Date(a.ts).getTime() - new Date(b.ts).getTime(),
  );

  const attempts: Attempt[] = [];
  let currentAttempt: Attempt | null = null;
  let current: PhaseGroup | null = null;
  let attemptAdvanced = false; // this attempt has progressed past its red phase

  const openAttempt = () => {
    currentAttempt = { attempt: attempts.length + 1, groups: [] };
    attempts.push(currentAttempt);
    attemptAdvanced = false;
    current = null;
  };

  for (const event of sorted) {
    const sem = semanticPhase(event);

    if (sem === null) {
      if (!currentAttempt) openAttempt();
      if (!current) {
        current = { phase: 'unknown', events: [] };
        currentAttempt!.groups.push(current);
      }
      current.events.push(event);
      continue;
    }

    const family = phaseFamily(sem);
    const sameGroup = current !== null && phaseFamily(current.phase) === family;

    if (!sameGroup) {
      if (family === 'red' && attemptAdvanced) {
        openAttempt();
      } else if (!currentAttempt) {
        openAttempt();
      }
      current = { phase: sem, events: [] };
      currentAttempt!.groups.push(current);
      if (family !== 'red') attemptAdvanced = true;
    }

    current!.events.push(event);

    if (event.kind === 'phase.completed') {
      const updated: PhaseGroup = { ...current!, duration_ms: event.duration_ms, sha: event.sha };
      currentAttempt!.groups[currentAttempt!.groups.length - 1] = updated;
      current = updated;
    }
  }

  // Derive a duration for any phase that didn't get one from an explicit
  // phase.completed event — red/green never do (the producer emits no
  // phase.completed for them), so without this they'd render no timing. The
  // span of the group's events (last ts − first ts) is the phase wall-clock:
  // phase.entered{X} (start) → its commit/decision (end). 'complete' is special
  // (its total is filled by withCompleteTotal), and 'unknown'/pre-work groups
  // aren't phases — skip both.
  return attempts.map((attempt) => ({
    ...attempt,
    groups: attempt.groups.map((group) => {
      if (
        group.duration_ms !== undefined ||
        group.phase === 'complete' ||
        phaseFamily(group.phase) === 'unknown'
      ) {
        return group;
      }
      // Only attach a derived duration for a phase that actually spans time —
      // a single-event (in-flight) phase has a zero span, and leaving it
      // undefined keeps it silent while preserving an explicit phase.completed
      // of 0 ms (which renders "<1 sec", not nothing).
      const span = spanMs(group.events);
      return span > 0 ? { ...group, duration_ms: span } : group;
    }),
  }));
}

/** Wall-clock span of a group's events (last ts − first ts); 0 for <2 events. */
function spanMs(events: readonly TelemetryEvent[]): number {
  if (events.length < 2) return 0;
  // events arrive pre-sorted chronologically (groupIntoAttempts sorts first),
  // so the first and last bound the span — no need to re-scan with min/max.
  return new Date(events[events.length - 1].ts).getTime() - new Date(events[0].ts).getTime();
}

/**
 * Compute total task wall-clock for the ✅ Complete header.
 *
 * The complete phase isn't a real worker phase — its duration is the
 * elapsed time from the earliest phase.entered to the task.completed
 * event, including idle gaps between phases. Without a task.completed
 * the total is unknown, so we leave the Complete header silent.
 *
 * Earliest is computed by timestamp (not first-in-array) so re-ordered
 * telemetry — say, a reconciliation backfill — doesn't anchor the
 * total to whichever phase.entered happens to be first in the slice.
 */
function totalTaskMs(events: readonly TelemetryEvent[]): number | undefined {
  const completed = events.find((e) => e.kind === 'task.completed');
  const phaseStarts = events.filter((e) => e.kind === 'phase.entered');
  if (!completed || phaseStarts.length === 0) return undefined;

  const earliestStartMs = Math.min(
    ...phaseStarts.map((e) => new Date(e.ts).getTime()),
  );
  const totalMs = new Date(completed.ts).getTime() - earliestStartMs;
  return totalMs < 0 ? undefined : totalMs;
}

function withCompleteTotal(
  attempts: readonly Attempt[],
  events: readonly TelemetryEvent[],
): Attempt[] {
  const totalMs = totalTaskMs(events);
  if (totalMs === undefined) return [...attempts];

  return attempts.map((a) => ({
    ...a,
    groups: a.groups.map((g) => (g.phase === 'complete' ? { ...g, duration_ms: totalMs } : g)),
  }));
}

function formatDuration(ms: number): string {
  // Sub-second renders as "<1 sec" so a quick phase doesn't print a
  // misleading "0 sec". Above one second we go verbose: sec / min sec /
  // hr min. Hour-scale collapses seconds — at that timescale they're
  // not informative.
  if (ms < 1000) return '<1 sec';
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (hours > 0) {
    return `${hours} hr${minutes > 0 ? ` ${minutes} min` : ''}`;
  }
  if (minutes > 0) {
    return `${minutes} min${seconds > 0 ? ` ${seconds} sec` : ''}`;
  }
  return `${seconds} sec`;
}

function phaseLabel(phase: string): string {
  if (phase.startsWith('review:')) {
    const gate = phase.slice('review:'.length);
    return `${getStepEmoji(gate)} ${getStepLabel(gate)}`;
  }
  if (phase.startsWith('refactor:')) return `${getStepEmoji('refactor')} ${getStepLabel('refactor')}`;
  if (phase === 'unknown') return '❓';
  return `${getStepEmoji(phase)} ${getStepLabel(phase)}`;
}

const SOURCE_STYLES: Record<string, string> = {
  agent: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  watcher: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  reconciliation: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300',
};

function eventSummary(event: TelemetryEvent): string {
  switch (event.kind) {
    case 'phase.entered': return `Entered ${event.phase}`;
    case 'phase.completed': return `Completed ${event.phase}`;
    case 'commit.tracked': return `${event.type} commit ${event.sha.substring(0, 7)}`;
    case 'persist.review_written': return `Review written`;
    case 'pipeline.decision': return `Decision`;
    case 'pipeline.advance.rejected':
      return `Rejected 2nd commit ${event.rejectedSha.substring(0, 7)} (already complete)`;
    case 'inbox.reminder_written': return `Reminder written (${event.reminder_id})`;
    case 'inbox.reminder_drained': return `Reminder drained (${event.reminder_id})`;
    case 'task.completed': return `Task completed (${event.final_sha.substring(0, 7)})`;
    case 'task.superseded': return `Task superseded (${event.superseding_sha.substring(0, 7)})`;
    case 'task.worktree_assigned': return `Worktree assigned (${event.worktreeName})`;
    case 'task.shas_rolled_back': return `SHAs rolled back (${event.reason})`;
    case 'task.removed': return `Task removed`;
    case 'task.markdown_synced': return `Markdown synced`;
    case 'task.uuid_stamped': return `UUID stamped (${event.fields.uuid.substring(0, 8)})`;
  }
  // Exhaustive over TelemetryEvent['kind']; a new kind will fail to
  // compile here (TS2366) until it gets a case — deliberate, so the
  // timeline never silently drops an event type.
}

const DECISION_PILL_STYLES: Record<string, string> = {
  clean: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
  dirty: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-300',
};

function verdictLabel(verdict: string): string {
  if (verdict === 'dirty') return 'Needs refactor';
  if (verdict === 'clean') return 'Passed';
  return verdict;
}

function EventRow({ event, index, expanded, onToggle }: {
  event: TelemetryEvent;
  index: number;
  expanded: boolean;
  onToggle: () => void;
}) {
  const isNoop = event.kind === 'pipeline.decision' && event.was_noop;

  return (
    <div
      data-testid={`event-row-${index}`}
      className={`py-1.5 pl-6 border-l-2 border-gray-200 dark:border-gray-700 ${isNoop ? 'opacity-50' : ''}`}
    >
      <div className="flex items-center gap-2 text-sm">
        <span className="text-xs text-muted-foreground font-mono whitespace-nowrap">
          {new Date(event.ts).toLocaleTimeString()}
        </span>
        <span className="text-sm flex-1 truncate">
          {eventSummary(event)}
        </span>
        {event.kind === 'pipeline.decision' && (
          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${DECISION_PILL_STYLES[event.decision] ?? ''}`}>
            {verdictLabel(event.decision)}
          </span>
        )}
        {event.kind === 'persist.review_written' && event.verdict && (
          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${DECISION_PILL_STYLES[event.verdict] ?? ''}`}>
            {verdictLabel(event.verdict)}
          </span>
        )}
        {event.kind === 'pipeline.decision' && (
          <span className={`text-xs px-1.5 py-0.5 rounded-full font-medium ${SOURCE_STYLES[event.source] ?? ''}`}>
            {event.source}
          </span>
        )}
        <button
          onClick={onToggle}
          aria-label="details"
          className="text-muted-foreground hover:text-foreground px-1"
        >
          {expanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
        </button>
      </div>
      {expanded && (
        <pre
          data-testid={`event-detail-${index}`}
          className="mt-1 ml-4 p-2 bg-gray-100 dark:bg-gray-800 rounded text-xs overflow-auto max-h-40"
        >
          {JSON.stringify(event, null, 2)}
        </pre>
      )}
    </div>
  );
}

function PhaseSection({ group }: { group: PhaseGroup }) {
  // mt-6 puts a clear gap above each phase; mb-2 keeps the header close to its
  // own event rows (the rows below it carry the connector).
  return (
    <div className="mt-6 mb-2">
      <div data-testid="phase-header" className="flex items-center gap-2 mb-2 text-sm font-semibold">
        <span>{phaseLabel(group.phase)}</span>
        {group.duration_ms != null && (
          <span className="text-xs text-muted-foreground font-normal">
            ({formatDuration(group.duration_ms)})
          </span>
        )}
        {group.sha && (
          <span className="text-xs font-mono text-muted-foreground font-normal">
            {group.sha.substring(0, 7)}
          </span>
        )}
      </div>
    </div>
  );
}

export function TaskTimeline({ events }: { events: TelemetryEvent[] }) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(null);

  if (events.length === 0) {
    return (
      <div className="text-sm text-muted-foreground text-center py-8">
        No telemetry events yet for this task
      </div>
    );
  }

  // Markdown-sync events happen at fix/task authoring time and carry no
  // semantic phase; surface them in a dedicated "Pre Work" section rather than
  // letting them fall into the ❓ unknown phase group (fix:
  // phase-entered-timed-to-commit-not-phase-start).
  const preWorkEvents = events
    .filter((e) => e.kind === 'task.markdown_synced')
    .sort((a, b) => new Date(a.ts).getTime() - new Date(b.ts).getTime());
  const timelineEvents = events
    .filter((e) => e.kind !== 'task.markdown_synced')
    .filter((e) => !isRedundantDecision(e, events));

  const completedIdx = timelineEvents.findIndex(e => e.kind === 'task.completed');
  const pipelineEvents = completedIdx >= 0 ? timelineEvents.slice(0, completedIdx + 1) : timelineEvents;
  const postCompletionEvents = completedIdx >= 0 ? timelineEvents.slice(completedIdx + 1) : [];
  const rawAttempts = groupIntoAttempts(pipelineEvents);
  const attempts = withCompleteTotal(rawAttempts, pipelineEvents);
  // Headline total wall-clock — same source as the ✅ Complete footer total, so
  // the two never disagree. Undefined (silent) until the task has completed.
  const totalMs = totalTaskMs(pipelineEvents);
  // Only label attempts when there's more than one cycle — a single-run
  // task shouldn't carry an "Attempt 1" header.
  const showAttemptHeaders = attempts.length > 1;

  // Pre-work rows take the first index slots, then phases continue from there.
  let globalIndex = preWorkEvents.length;

  return (
    <div className="space-y-2">
      {preWorkEvents.length > 0 && (
        <div data-testid="pre-work-section" className="mb-4 pb-4 border-b border-dashed border-gray-300 dark:border-gray-600">
          <div className="text-xs text-muted-foreground font-semibold mb-2">Pre Work</div>
          {preWorkEvents.map((event, ei) => (
            <EventRow
              key={ei}
              event={event}
              index={ei}
              expanded={expandedIndex === ei}
              onToggle={() => setExpandedIndex(expandedIndex === ei ? null : ei)}
            />
          ))}
        </div>
      )}
      {totalMs !== undefined && (
        <div
          data-testid="total-time-taken"
          className="mb-4 pb-4 border-b border-dashed border-gray-300 dark:border-gray-600 flex items-baseline gap-2"
        >
          <span className="text-xs text-muted-foreground font-semibold uppercase tracking-wide">
            Total time taken
          </span>
          <span className="text-sm font-semibold">{formatDuration(totalMs)}</span>
        </div>
      )}
      {attempts.map((attempt) => (
        <div key={`attempt-${attempt.attempt}`}>
          {showAttemptHeaders && (
            <div
              data-testid="attempt-header"
              className="flex items-center gap-2 mb-2 mt-4 text-xs font-semibold uppercase tracking-wide text-muted-foreground"
            >
              Attempt {attempt.attempt}
            </div>
          )}
          {attempt.groups.map((group, gi) => {
            const startIdx = globalIndex;
            const rows = group.events.map((event, ei) => {
              const idx = startIdx + ei;
              return (
                <EventRow
                  key={idx}
                  event={event}
                  index={idx}
                  expanded={expandedIndex === idx}
                  onToggle={() => setExpandedIndex(expandedIndex === idx ? null : idx)}
                />
              );
            });
            globalIndex += group.events.length;
            return (
              <div key={gi}>
                <PhaseSection group={group} />
                {/* ml-2 nudges the event rows' left connector to sit under the
                    middle of the phase emoji in the header above. */}
                <div className="ml-2">{rows}</div>
              </div>
            );
          })}
        </div>
      ))}
      {postCompletionEvents.length > 0 && (
        <div data-testid="post-completion-section" className="mt-4 pt-4 border-t border-dashed border-gray-300 dark:border-gray-600">
          <div className="text-xs text-muted-foreground font-semibold mb-2">Post-completion activity</div>
          {postCompletionEvents.map((event, ei) => {
            const idx = globalIndex + ei;
            return (
              <EventRow
                key={idx}
                event={event}
                index={idx}
                expanded={expandedIndex === idx}
                onToggle={() => setExpandedIndex(expandedIndex === idx ? null : idx)}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}
