import React, { useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Archive } from 'lucide-react';
import ProgressBar from './ProgressBar';
import WorktreePill from './WorktreePill';
import { SelectableCard } from './ui/selectable-card';
import type { Fix } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { taskPhaseProgress } from '../utils/task-progress';

interface FixCardProps {
  fix: Fix;
  isSelected: boolean;
  onClick: () => void;
  reviewPipeline?: PipelineStep[];
}

// Mirror FixDetail's header severity pills exactly (incl. the oklch borders).
const severityColors = {
  low: 'bg-blue-100 text-blue-800 border-[oklch(0.71_0.13_254)] dark:bg-blue-900 dark:text-blue-300 dark:border-[oklch(0.50_0.13_254)]',
  medium: 'bg-yellow-100 text-yellow-800 border-[oklch(0.82_0.14_90)] dark:bg-yellow-900 dark:text-yellow-300 dark:border-[oklch(0.55_0.11_90)]',
  high: 'bg-orange-100 text-orange-800 border-[oklch(0.75_0.16_55)] dark:bg-orange-900 dark:text-orange-300 dark:border-[oklch(0.55_0.14_55)]',
  critical: 'bg-red-100 text-red-800 border-[oklch(0.64_0.21_27)] dark:bg-red-900 dark:text-red-300 dark:border-[oklch(0.50_0.18_27)]',
};

const displayStatus: Record<Fix['status'], string> = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Complete',
  superseded: 'Superseded',
};

const FixCard: React.FC<FixCardProps> = ({ fix, isSelected, onClick, reviewPipeline }) => {
  // Branches this fix's work lives on, each flagged with whether a live worktree
  // exists — the fix analogue of PlanCard's marker. Keyed on the BRANCH (the
  // stable identity) so the same physical worktree, surfacing as both a
  // task/source dir-name and a lattice branch ref, collapses to one entry.
  // Lattice refs are filtered to live worktrees (isWorktree) STRICTLY AHEAD of
  // the launch ref; explicit task/source worktrees surface regardless of ahead-
  // status so a fresh/undiverged worktree still shows.
  const worktreeBranches = useMemo(() => {
    const rank: Record<string, number> = { not_started: 0, in_progress: 1, completed: 2, superseded: 2 };
    const byBranch = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
    const add = (branch: string, hasWorktree: boolean, worktreeName?: string) => {
      const prev = byBranch.get(branch);
      byBranch.set(branch, {
        hasWorktree: (prev?.hasWorktree ?? false) || hasWorktree,
        worktreeName: prev?.worktreeName ?? worktreeName,
      });
    };

    if (fix.sourceWorktree) add(fix.sourceWorktree.branch, true, fix.sourceWorktree.name);
    for (const task of fix.tasks) {
      if (task.worktree) add(task.worktree.branch, true, task.worktree.name);
      const cells = task.statusByRef || [];
      const launchRank = rank[cells.find(c => c.isLaunchRef)?.status ?? 'not_started'] ?? 0;
      for (const cell of cells) {
        if (cell.isLaunchRef || !cell.isWorktree) continue;
        if ((rank[cell.status] ?? 0) <= launchRank) continue;
        add(cell.ref, true); // lattice refs carry no dir name
      }
    }
    return [...byBranch].map(([branch, v]) => ({ branch, ...v }));
  }, [fix.sourceWorktree, fix.tasks]);

  const { progress, completedPercent, supersededPercent } = useMemo(() => {
    if (fix.status === 'completed' || fix.status === 'superseded') {
      const pct = fix.status === 'superseded' ? 'supersededPercent' : 'completedPercent';
      return { progress: 100, completedPercent: pct === 'completedPercent' ? 100 : 0, supersededPercent: pct === 'supersededPercent' ? 100 : 0 };
    }
    const total = fix.tasks.length;
    if (total === 0) return { progress: 0, completedPercent: 0, supersededPercent: 0 };

    // Sum fractional progress per task (pipeline-phase-aware)
    let completedWeight = 0;
    let supersededWeight = 0;
    for (const task of fix.tasks) {
      const fraction = taskPhaseProgress(task, reviewPipeline);
      if (task.status === 'superseded') {
        supersededWeight += fraction;
      } else {
        completedWeight += fraction;
      }
    }

    return {
      progress: Math.round(((completedWeight + supersededWeight) / total) * 100),
      completedPercent: Math.round((completedWeight / total) * 100),
      supersededPercent: Math.round((supersededWeight / total) * 100),
    };
  }, [fix.status, fix.tasks, reviewPipeline]);

  const isResolved = fix.status === 'completed' || fix.status === 'superseded';
  const isInProgress = fix.status === 'in_progress';
  const isArchived = fix.archived === true;

  return (
      <SelectableCard
        isSelected={isSelected}
        isCompleted={isResolved}
        onClick={onClick}
        className={cn(
          isArchived && "opacity-60",
          isInProgress && "bg-blue-100/60 dark:bg-blue-900/30"
        )}
        data-testid={isArchived ? 'archived-card' : undefined}
      >
        <div className="flex items-start justify-between gap-2">
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              {isArchived && <Archive data-testid="archive-icon" className="h-3.5 w-3.5 text-muted-foreground flex-shrink-0" />}
              <h3 className="font-medium text-sm line-clamp-2">{fix.title}</h3>
            </div>
          </div>
          <Badge className={cn(severityColors[fix.severity], 'rounded')}>
            {fix.severity}
          </Badge>
        </div>

        {/* Progress */}
        <div className="space-y-2 mt-2">
          <div className="flex justify-between text-xs">
            <span className={cn(
              isResolved ? "text-green-600 dark:text-green-400 font-medium" :
              isInProgress ? "text-blue-600 dark:text-blue-400 font-medium"
                : "text-gray-500 dark:text-gray-400"
            )}>{isResolved ? '✅ Complete!' : displayStatus[fix.status]}</span>
            <span className={cn("text-muted-foreground", isResolved && "font-bold text-green-600 dark:text-green-400")}>{progress}%</span>
          </div>
          <ProgressBar
            progress={progress}
            isSelected={isSelected}
            isInProgress={isInProgress}
            completedPercent={completedPercent}
            supersededPercent={supersededPercent}
          />
        </div>

        {/* Bottom row: reported/resolved dates on the left, a single deduped
            worktree pill (doc origin / per-task / unmerged-work, merged) right. */}
        {(fix.reported || worktreeBranches.length > 0) && (
          <div className="mt-2 flex items-center justify-between gap-2 text-xs text-muted-foreground">
            <span>
              {fix.reported && <>Reported: {new Date(fix.reported).toLocaleDateString()}</>}
              {fix.resolved && (
                <span className="ml-2">
                  Resolved: {new Date(fix.resolved).toLocaleDateString()}
                </span>
              )}
            </span>
            <WorktreePill branches={worktreeBranches} className="ml-auto" />
          </div>
        )}

        {/* Active-run footer (Task 10 of run-lifecycle): glance row
            showing which worker is on this fix and where it's
            running. 🤖 for a local-worker driver, ☁️ for cloud-
            remote, both when a worker is driving a remote run. */}
        {fix.activeRun && (
          <div
            data-testid="active-run-footer"
            className="mt-2 flex items-center gap-1.5 text-xs text-muted-foreground"
            title={fix.activeRun.worktreePath}
          >
            {/* Robot when a worker is driving (always for local;
                only when `worker` is set for cloud-remote). */}
            {(fix.activeRun.target === 'local-worktree' ||
              fix.activeRun.worker !== undefined) && (
              <span aria-label="local worker">🤖</span>
            )}
            {fix.activeRun.target === 'cloud-remote' && (
              <span aria-label="cloud remote">☁️</span>
            )}
            {fix.activeRun.worktreePath && (
              <span className="truncate">
                {fix.activeRun.worktreePath.split('/').filter(Boolean).slice(-1)[0]}
              </span>
            )}
          </div>
        )}
      </SelectableCard>
  );
};

export default FixCard;
