/**
 * SSE-driven refetch trigger for the dashboard's reviews surface.
 *
 * Fix `dashboard-drops-filewatcher-sse-events`, Task 3 — the server broadcasts
 * `review-change` (kind `pending` for `reviews/pending.json`, kind `decided`
 * for `reviews/decided/<gate>/<sha>.json`) whenever a review file changes, but
 * the client had no listener so the reviews surface never live-updated. This
 * hook listens to that channel scoped to `repoId` and invokes `onChange` so the
 * parent can refetch — mirroring `useSpikeDocLive`.
 */

import { useEffect } from 'react';
import { sseManager, type SSEEvent } from '../services/SSEManager';

export interface UseReviewLiveOptions {
  /**
   * Narrow `decided` events to a single review commit. When set, a `decided`
   * review-change for a DIFFERENT sha is ignored (an open popover keyed to one
   * commit shouldn't refetch when an unrelated review is decided). `pending`
   * events carry no sha and always fire — they're repo-level.
   */
  commitSha?: string;
  enabled?: boolean;
}

export function useReviewLive(
  repoId: string | null,
  onChange: () => void,
  options: UseReviewLiveOptions = {},
): void {
  const { commitSha, enabled = true } = options;
  useEffect(() => {
    if (!enabled || !repoId) return;

    const handle = (event: SSEEvent): void => {
      if (event.type !== 'reviewChange') return;
      if (event.repoId !== repoId) return;
      // A decided event for a different commit isn't relevant to a sha-scoped
      // consumer; pending events (no sha) always pass.
      if (commitSha !== undefined && event.kind === 'decided' && event.sha !== commitSha) return;
      onChange();
    };

    return sseManager.on('reviewChange', handle);
  }, [repoId, commitSha, enabled, onChange]);
}
