import React from 'react';
import { formatDistanceToNow } from 'date-fns';
import { formatDateTime } from '../utils/format-date';

export interface DetailSubHeaderDate {
  /** Row label, e.g. "Reported" / "Created" / "Resolved". */
  readonly label: string;
  /** ISO timestamp (or date-only string) for the date value. */
  readonly iso: string;
}

export interface DetailSubHeaderProps {
  /** Label for the progress row (e.g. "Progress"). */
  readonly progressLabel: string;
  /** Right-aligned progress summary text (e.g. "3/5 tasks (60%)"). */
  readonly progressText: string;
  /** Width percent of the completed (green/blue) segment. */
  readonly completedPercent: number;
  /** Width percent of the superseded (orange) segment. */
  readonly supersededPercent: number;
  /** Dates rendered as "Label: <absolute> (<relative> ago)". */
  readonly dates: readonly DetailSubHeaderDate[];
  /** Optional right-aligned slot (e.g. a spike's timebox countdown). */
  readonly right?: React.ReactNode;
}

/**
 * Shared subheader for the Fix and Spike detail views: a progress bar on
 * top, then a row of labelled dates — each carrying both an absolute value
 * and a relative "(x ago)" offset — with an optional right-aligned slot
 * (spikes pass their timebox countdown here). Extracted so the two views
 * stop hand-rolling near-identical markup that drifts apart.
 */
const DetailSubHeader: React.FC<DetailSubHeaderProps> = ({
  progressLabel,
  progressText,
  completedPercent,
  supersededPercent,
  dates,
  right,
}) => {
  // The completed segment goes green once the whole bar is filled (all tasks
  // done or superseded); blue while work remains. Derived here so callers
  // can't drift a separate `progress` value out of sync with the segments.
  const isComplete = completedPercent + supersededPercent >= 100;
  return (
    <div className="space-y-3">
      <div>
        <div className="flex items-center justify-between text-sm mb-2">
          <span className="text-muted-foreground">{progressLabel}</span>
          <span className="font-medium">{progressText}</span>
        </div>
        <div
          className="h-2 bg-gray-300/50 dark:bg-gray-600/50 ring-1 ring-gray-400/30 dark:ring-gray-500/30 rounded-full overflow-hidden flex"
          data-testid="progress-bar"
        >
          {completedPercent > 0 && (
            <div
              data-testid="progress-completed"
              className={`h-full transition-all ${isComplete ? 'bg-green-500' : 'bg-blue-500'}`}
              style={{ width: `${completedPercent}%` }}
            />
          )}
          {supersededPercent > 0 && (
            <div
              data-testid="progress-superseded"
              className="h-full bg-orange-400 transition-all"
              style={{ width: `${supersededPercent}%` }}
            />
          )}
        </div>
      </div>

      {(dates.length > 0 || right) && (
        <div className="flex items-center justify-between gap-4 text-sm text-muted-foreground">
          <div className="flex items-center gap-4">
            {dates.map((d) => (
              <span key={d.label}>
                {`${d.label}: ${formatDateTime(d.iso)} (${formatDistanceToNow(new Date(d.iso), { addSuffix: true })})`}
              </span>
            ))}
          </div>
          {right && <div className="flex-shrink-0">{right}</div>}
        </div>
      )}
    </div>
  );
};

export default DetailSubHeader;
