import type { SpikeStatus } from '@magic-ingredients/tiny-brain-core';

/**
 * Per-status badge background/border colour styles. The PRD's
 * "validated and invalidated are both visually positive (different
 * colour, neither red)" requirement is encoded here as concrete
 * colour tokens — emerald for validated (the "we proved it" green),
 * sky for invalidated (the "we disproved it, still useful" blue),
 * amber for abandoned. not_started/in_progress use neutral and
 * indigo. Single source of truth so SpikeCard and any future spike
 * UI consume the same palette.
 */
export const SPIKE_STATUS_STYLES: Record<SpikeStatus, string> = {
  not_started:
    'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 border-gray-300 dark:border-gray-500',
  in_progress:
    'bg-indigo-100 dark:bg-indigo-900/40 text-indigo-800 dark:text-indigo-200 border-indigo-300 dark:border-indigo-700',
  validated:
    'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-800 dark:text-emerald-200 border-emerald-300 dark:border-emerald-700',
  invalidated:
    'bg-sky-100 dark:bg-sky-900/40 text-sky-800 dark:text-sky-200 border-sky-300 dark:border-sky-700',
  abandoned:
    'bg-amber-100 dark:bg-amber-900/40 text-amber-800 dark:text-amber-200 border-amber-300 dark:border-amber-700',
};

/**
 * The dot colour used by SpikeDetail's Badge variant (the badge there
 * is outlined, not filled, so it needs a solid dot to carry the
 * status colour). Mirrors the saturation level FixDetail uses for its
 * status dots.
 */
export const SPIKE_STATUS_DOT_COLORS: Record<SpikeStatus, string> = {
  not_started: 'bg-gray-500',
  in_progress: 'bg-blue-500',
  validated: 'bg-emerald-500',
  invalidated: 'bg-sky-500',
  abandoned: 'bg-amber-500',
};

/** Title-Case labels for human-facing status text. */
export const SPIKE_STATUS_LABEL: Record<SpikeStatus, string> = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  validated: 'Validated',
  invalidated: 'Invalidated',
  abandoned: 'Abandoned',
};

export const SPIKE_TERMINAL_STATUSES = new Set<SpikeStatus>([
  'validated',
  'invalidated',
  'abandoned',
]);

/**
 * Narrow an arbitrary string (SpikeProgress.status / SpikeSummary.status
 * are `SpikeStatus | string` at the type level) to a known SpikeStatus,
 * falling back to `not_started` for anything unrecognised. Without the
 * fallback, an unknown status would index status maps with `undefined`
 * and render a blank badge with no visual signal.
 */
export function narrowSpikeStatus(s: string): SpikeStatus {
  return (s in SPIKE_STATUS_LABEL ? s : 'not_started') as SpikeStatus;
}
