import { useState, useEffect, useMemo, useCallback } from 'react';
import type { TelemetryEvent, TelemetryTaskRef } from '@magic-ingredients/tiny-brain-core';
import { sseManager, type SSEEvent } from '../services/SSEManager';

interface FixTaskRefInput {
  readonly kind: 'fix';
  readonly fixId: string;
  readonly taskId: string;
  /**
   * Soak-window back-compat keys for historical events that predate the
   * UUID join (dashboard-timeline-queries-stale-positional-key). The
   * canonical `taskId` is the task UUID; these carry the positional
   * `task-N` id and the free-text description so the server's reader
   * OR-matches every scheme and the timeline shows new + old events.
   */
  readonly legacyTaskKeys?: readonly string[];
}

interface PrdTaskRefInput {
  readonly kind: 'prd';
  readonly prdId: string;
  readonly featureId: string;
  readonly taskId: string;
  /** See {@link FixTaskRefInput.legacyTaskKeys}. */
  readonly legacyTaskKeys?: readonly string[];
}

export type TaskRefInput = FixTaskRefInput | PrdTaskRefInput;

/**
 * Build the timeline task ref from a projected task. The canonical join
 * key is the task UUID; the positional id and description ride along as
 * soak-window legacy keys (deduped against the canonical). Falls back to
 * the positional id when the task is unstamped (no UUID yet). Returns
 * null when there's no task or no fix/prd identifiers to anchor it.
 *
 * When both a `fixId` and a `planId`/`featureId` are supplied, the fix ref
 * wins — a task belongs to one or the other, and the caller passes only the
 * relevant identifier in practice.
 */
export function timelineTaskRef(
  progressTask: { id: string; uuid?: string; description?: string } | undefined,
  ids: { planId?: string; featureId?: string; fixId?: string },
): TaskRefInput | null {
  if (!progressTask) return null;
  const positional = progressTask.id;
  const canonical = progressTask.uuid ?? positional;
  if (!canonical) return null;
  const legacyTaskKeys = [positional, progressTask.description].filter(
    (k): k is string => typeof k === 'string' && k.length > 0 && k !== canonical,
  );
  if (ids.fixId) {
    return { kind: 'fix', fixId: ids.fixId, taskId: canonical, legacyTaskKeys };
  }
  if (ids.planId && ids.featureId) {
    return { kind: 'prd', prdId: ids.planId, featureId: ids.featureId, taskId: canonical, legacyTaskKeys };
  }
  return null;
}

interface UseTaskTelemetryResult {
  readonly events: TelemetryEvent[];
  readonly loading: boolean;
  readonly error: string | null;
}

function taskRefsMatch(a: TelemetryTaskRef, b: TelemetryTaskRef): boolean {
  if (a.kind !== b.kind) return false;
  if (a.kind === 'prd' && b.kind === 'prd') {
    return a.prd === b.prd && a.feature === b.feature && a.task === b.task;
  }
  if (a.kind === 'fix' && b.kind === 'fix') {
    return a.fix === b.fix && a.task === b.task;
  }
  return false;
}

function encodeSegment(s: string): string {
  return encodeURIComponent(s);
}

function buildUrl(repoId: string, taskRef: TaskRefInput): string {
  const base = taskRef.kind === 'fix'
    ? `/api/repos/${encodeSegment(repoId)}/tasks/fix:${encodeSegment(taskRef.fixId)}/${encodeSegment(taskRef.taskId)}/telemetry`
    : `/api/repos/${encodeSegment(repoId)}/tasks/prd:${encodeSegment(taskRef.prdId)}/${encodeSegment(taskRef.featureId)}/${encodeSegment(taskRef.taskId)}/telemetry`;
  const keys = taskRef.legacyTaskKeys ?? [];
  if (keys.length === 0) return base;
  // One repeated `legacyTaskKey=` param per key — the server reads them
  // all via `c.req.queries('legacyTaskKey')`.
  const query = keys.map((k) => `legacyTaskKey=${encodeSegment(k)}`).join('&');
  return `${base}?${query}`;
}

function taskRefKey(taskRef: TaskRefInput | null): string {
  if (!taskRef) return '';
  // The legacy keys are part of the cache identity: a parent re-render
  // that changes only a legacy key (e.g. the doc heading got renamed)
  // MUST re-fire the fetch effect. Without them in the key, the effect
  // deps reduce to a stale URL and the back-compat events for the new
  // key never arrive. The literal `\x1f` (US separator) is used so a
  // description containing the delimiter can't collide with id
  // boundaries.
  const legacy = (taskRef.legacyTaskKeys ?? []).join('\x1f');
  if (taskRef.kind === 'fix') return `fix:${taskRef.fixId}/${taskRef.taskId}\x1f${legacy}`;
  return `prd:${taskRef.prdId}/${taskRef.featureId}/${taskRef.taskId}\x1f${legacy}`;
}

function toTelemetryTaskRef(input: TaskRefInput): TelemetryTaskRef {
  if (input.kind === 'fix') {
    return { kind: 'fix', fix: input.fixId, task: input.taskId };
  }
  return { kind: 'prd', prd: input.prdId, feature: input.featureId, task: input.taskId };
}

export function useTaskTelemetry(repoId: string, taskRef: TaskRefInput | null, enabled: boolean): UseTaskTelemetryResult {
  const [events, setEvents] = useState<TelemetryEvent[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cacheKey = useMemo(() => taskRefKey(taskRef), [taskRef]);
  const coreRef = useMemo(() => taskRef ? toTelemetryTaskRef(taskRef) : null, [cacheKey]);

  useEffect(() => {
    if (!enabled || !taskRef) return;

    let cancelled = false;
    setLoading(true);
    setError(null);

    fetch(buildUrl(repoId, taskRef))
      .then(async (res) => {
        if (cancelled) return;
        if (!res.ok) {
          const body = await res.json().catch(() => ({}));
          throw new Error(body.error ?? `Failed to fetch telemetry (${res.status})`);
        }
        const data = await res.json();
        setEvents(data.events);
      })
      .catch((err: Error) => {
        if (cancelled) return;
        setEvents([]);
        setError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [repoId, cacheKey, enabled]);

  const handleSSE = useCallback((sseEvent: SSEEvent) => {
    if (sseEvent.type !== 'telemetryChange') return;
    if (sseEvent.repoId !== repoId) return;
    if (!coreRef) return;
    if (!taskRefsMatch(sseEvent.event.taskRef, coreRef)) return;
    // Dedupe by the event's unique id: the SSE stream can re-deliver events
    // already in the fetched set (filewatcher tick after a commit, reconnect,
    // batch replay). Appending blindly doubled every timeline row
    // (dashboard-timeline-doubles-sse-redelivered-events). An event with no id
    // (legacy/rare) can't be deduped, so it is appended as before.
    setEvents(prev =>
      sseEvent.event.id !== undefined && prev.some(e => e.id === sseEvent.event.id)
        ? prev
        : [...prev, sseEvent.event],
    );
    // A panel opened before any commits resolves 404 -> empty + error.
    // A matching live event means the task now has telemetry, so clear the
    // stale empty/error state — otherwise the already-open Timeline tab stays
    // stuck on "no telemetry" until a manual refresh
    // (dashboard-timeline-no-refetch-on-commit-accrual). The fetch effect owns
    // the loading lifecycle via its `.finally`, so we don't touch it here.
    setError(null);
  }, [repoId, coreRef]);

  useEffect(() => {
    if (!enabled || !coreRef) return;
    const unsubscribe = sseManager.on('telemetryChange', handleSSE);
    return unsubscribe;
  }, [enabled, coreRef, handleSSE]);

  return { events, loading, error };
}
