import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import type {
  SpikeProgress,
  SpikeProgressTask,
  SpikeWorktreeStatus,
} from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { CheckCircle2, HelpCircle, ListChecks } from 'lucide-react';
import DetailHeaderBar from './DetailHeaderBar';
import DetailSubHeader from './DetailSubHeader';
import { SpikeLaunchSnippet } from './SpikeLaunchSnippet';
import { OrphanedWorktreeBanner } from './OrphanedWorktreeBanner';
import { SpikeOutcomeCapture } from './SpikeOutcomeCapture';
import TaskRow from './TaskRow';
import { formatTaskComponentSlug } from '../utils/task-slug-path';
import { TimeboxCountdown } from './TimeboxCountdown';
import {
  SPIKE_STATUS_DOT_COLORS,
  SPIKE_STATUS_LABEL,
  SPIKE_TERMINAL_STATUSES,
  narrowSpikeStatus,
} from './spike-status';
import type { TaskRowTask } from '../types';
import type {
  PipelineStep,
  ReviewVerdict,
} from '@magic-ingredients/tiny-brain-core/phase-derivation';

export interface SpikeDetailProps {
  spike: SpikeProgress;
  worktreeStatus: SpikeWorktreeStatus;
  repoId: string;
  onWorktreeCleared?: () => void;
  onOutcomeRecorded?: () => void;
}

/**
 * Hermetic spike pipeline — see `pipelines/spike.ts` in core. The
 * default spike strategy runs `green → complete` with no review gate,
 * so the dashboard passes an empty pipeline and TaskRow renders just
 * the Green pill per task. Correctness for a spike is captured by the
 * terminal frontmatter status (validated / invalidated / abandoned),
 * not a pipeline review.
 */
const SPIKE_PIPELINE_STEPS: PipelineStep[] = [];

/**
 * Map an outcome-table result marker to a badge colour. The well-known
 * tokens (PASS / FAIL / PARTIAL / SKIP) get coloured chips; anything
 * else gets a neutral chip so new vocabulary the author invents on a
 * spike-by-spike basis still renders something readable.
 */
function criterionResultTone(marker: string): string {
  const token = marker.trim().toUpperCase();
  if (token === 'PASS' || token === 'PASSED') {
    return 'border-green-500/40 text-green-600 dark:text-green-400 bg-green-500/10';
  }
  if (token === 'FAIL' || token === 'FAILED') {
    return 'border-red-500/40 text-red-600 dark:text-red-400 bg-red-500/10';
  }
  if (token === 'PARTIAL' || token === 'PARTIALLY') {
    return 'border-amber-500/40 text-amber-600 dark:text-amber-400 bg-amber-500/10';
  }
  if (token === 'SKIP' || token === 'SKIPPED' || token === 'N/A') {
    return 'border-muted-foreground/30 text-muted-foreground';
  }
  return 'border-muted-foreground/30 text-muted-foreground';
}

const VALID_VERDICTS: ReadonlySet<ReviewVerdict> = new Set<ReviewVerdict>([
  'clean',
  'needs-refactoring',
]);

/**
 * SpikeProgressTask carries a wider `verdict?: string` than the
 * dashboard's ReviewRecord (`'clean' | 'needs-refactoring'`). Narrow at
 * the boundary: drop any verdict the renderer doesn't know about rather
 * than smuggle a wider type through with a cast.
 */
function toTaskRowTask(task: SpikeProgressTask): TaskRowTask {
  const reviews: TaskRowTask['reviews'] = task.reviews
    ? Object.fromEntries(
        Object.entries(task.reviews).map(([key, value]) => [
          key,
          {
            ...value,
            verdict:
              value.verdict && VALID_VERDICTS.has(value.verdict as ReviewVerdict)
                ? (value.verdict as ReviewVerdict)
                : undefined,
          },
        ]),
      )
    : undefined;
  return {
    ...task,
    status: (task.status as TaskRowTask['status']) ?? 'not_started',
    pipelineType: task.pipelineType ?? 'spike',
    reviews,
  };
}

export function SpikeDetail({
  spike,
  worktreeStatus,
  repoId,
  onWorktreeCleared,
  onOutcomeRecorded,
}: SpikeDetailProps) {
  const status = narrowSpikeStatus(spike.status);
  const isTerminal = SPIKE_TERMINAL_STATUSES.has(status);

  // Spikes run the hermetic green→complete pipeline (no review gate), so a
  // task is either done or not — progress is a simple done/total ratio.
  const totalTasks = spike.tasks.length;
  const completedCount = spike.tasks.filter((t) => t.status === 'completed').length;
  const supersededCount = spike.tasks.filter((t) => t.status === 'superseded').length;
  const doneTasks = completedCount + supersededCount;
  const completedPercent = totalTasks > 0 ? Math.round((completedCount / totalTasks) * 100) : 0;
  const supersededPercent = totalTasks > 0 ? Math.round((supersededCount / totalTasks) * 100) : 0;
  const progress = completedPercent + supersededPercent;

  return (
    <div className="h-full flex flex-col">
      {/* Shared identity bar (consistent with PRD/Fix): title + id-copy + status.
          Pinned outside the scroll container (flex-shrink-0 via DetailHeaderBar)
          so it stays visible while the body scrolls. */}
      <DetailHeaderBar
        testId="spike-header-bar"
        title={spike.title}
        id={spike.id}
        idKind="Spike"
        right={
          <Badge
            data-testid={`spike-status-${spike.id}`}
            data-status={status}
            variant="outline"
            className="flex items-center gap-1.5 whitespace-nowrap rounded font-normal"
          >
            <span className={cn('w-2 h-2 rounded-full', SPIKE_STATUS_DOT_COLORS[status])} />
            {SPIKE_STATUS_LABEL[status]}
          </Badge>
        }
      />

      {/* Summary subheader — also pinned (progress + timebox stay in view),
          lifted out of the scroll container below. */}
      <div className="flex-shrink-0 px-3 pt-3">
        <Card className="py-3">
          <CardContent className="px-3">
            <DetailSubHeader
              progressLabel="Progress"
              progressText={
                totalTasks === 0 ? '0 tasks' : `${doneTasks}/${totalTasks} tasks (${progress}%)`
              }
              completedPercent={completedPercent}
              supersededPercent={supersededPercent}
              dates={[{ label: 'Created', iso: spike.created }]}
              right={
                <TimeboxCountdown
                  created={spike.created}
                  timebox={spike.timebox}
                  status={status}
                />
              }
            />
          </CardContent>
        </Card>
      </div>

      <div data-testid="spike-scroll" className="flex-1 overflow-auto p-3 space-y-6">
      {/* Worktree launch — copy button only; the inline command is
          visual noise once the user knows what the button does */}
      {worktreeStatus.kind === 'present' && (
        <div className="pt-1">
          <SpikeLaunchSnippet path={worktreeStatus.path} spikeId={spike.id} />
        </div>
      )}
      {worktreeStatus.kind === 'orphaned' && (
        <OrphanedWorktreeBanner
          repoId={repoId}
          spikeId={spike.id}
          branch={worktreeStatus.branch}
          onCleared={onWorktreeCleared}
        />
      )}

      {/* Question — the spike's reason for existing, called out in its
          own card so it doesn't get mistaken for ambient header copy */}
      <Card className="gap-2 py-3">
        <CardHeader className="px-3 pb-0">
          <CardTitle className="text-lg flex items-center gap-2">
            <HelpCircle className="h-5 w-5 text-blue-500" />
            Question
          </CardTitle>
        </CardHeader>
        <CardContent className="px-3">
          <p className="text-sm whitespace-pre-line">{spike.question}</p>
        </CardContent>
      </Card>

      {/* Acceptance criteria — separate card so the checklist isn't
          visually melded into the question or task list */}
      <Card className="gap-2 py-3">
        <CardHeader className="px-3 pb-0">
          <CardTitle className="text-lg flex items-center gap-2">
            <ListChecks className="h-5 w-5 text-purple-500" />
            Acceptance Criteria
          </CardTitle>
        </CardHeader>
        <CardContent className="px-3">
          <ul data-testid="spike-criteria" className="text-sm space-y-2">
            {spike.acceptanceCriteria.map((criterion, i) => {
              const marker = spike.criterionResults?.[i] ?? null;
              return (
                <li key={i} className="flex items-start gap-2">
                  <span
                    aria-hidden="true"
                    className="mt-1 inline-block w-1.5 h-1.5 rounded-full bg-purple-400 flex-shrink-0"
                  />
                  <span className="flex-1">{criterion}</span>
                  {marker && (
                    <Badge
                      data-testid="spike-criterion-result"
                      variant="outline"
                      className={cn(
                        'text-xs flex-shrink-0',
                        criterionResultTone(marker),
                      )}
                    >
                      {marker}
                    </Badge>
                  )}
                </li>
              );
            })}
          </ul>
        </CardContent>
      </Card>

      {/* Outcome capture — shown only while the spike is in_progress.
          Records the terminal status + outcome narrative via the
          /outcome API; on success the parent refetches and this card
          disappears in favour of the Outcome banner below. */}
      {status === 'in_progress' && (
        <SpikeOutcomeCapture
          repoId={repoId}
          spikeId={spike.id}
          onCompleted={onOutcomeRecorded}
        />
      )}

      {/* Outcome — shown above tasks once terminal, mirrors FixDetail's
          Resolution card. When the API supplies outcomeBody (the doc's
          `## Outcome` markdown) we render it inline so the reader
          doesn't have to leave the page; older spike docs without the
          field fall back to the file-pointer hint. */}
      {isTerminal && (
        <Card data-testid="spike-outcome" data-status={status} className="gap-2 py-3">
          <CardHeader className="px-3 pb-0">
            <CardTitle className="text-lg flex items-center gap-2">
              <CheckCircle2 className="h-5 w-5 text-green-500" />
              Outcome — {SPIKE_STATUS_LABEL[status]}
            </CardTitle>
          </CardHeader>
          <CardContent className="px-3">
            {spike.outcomeBody ? (
              <div className="prose prose-sm dark:prose-invert max-w-none text-sm">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{spike.outcomeBody}</ReactMarkdown>
              </div>
            ) : (
              <p className="text-sm text-muted-foreground">
                See the spike doc body for the outcome narrative
                (<code className="font-mono">docs/spikes/{spike.id}.md</code>).
              </p>
            )}
          </CardContent>
        </Card>
      )}

      {/* Tasks — uses the shared TaskRow component (same as PRDs/Fixes),
          driven by the hermetic spike pipeline (green → complete; no
          review gate) */}
      <div>
        <div className="flex items-center gap-2 mb-3">
          <h3 className="text-lg font-semibold">Tasks</h3>
          <span className="text-sm text-muted-foreground">
            {spike.tasks.length} {spike.tasks.length === 1 ? 'task' : 'tasks'}
          </span>
        </div>
        {spike.tasks.length === 0 ? (
          <p className="text-muted-foreground text-sm text-center py-4">
            No tasks yet — they appear after the first{' '}
            <code className="font-mono">tb task sync</code>.
          </p>
        ) : (
          <div className="space-y-1">
            {spike.tasks.map((task, index) => (
              <TaskRow
                key={task.id}
                task={toTaskRowTask(task)}
                repoId={repoId}
                reviewPipeline={SPIKE_PIPELINE_STEPS}
                slugPath={formatTaskComponentSlug(index + 1)}
              />
            ))}
          </div>
        )}
      </div>
      </div>
    </div>
  );
}
