import { useState, useEffect } from 'react';

interface CliStatus {
  hasClaudeCli: boolean;
  isLoading: boolean;
  error: string | null;
}

export function useApiKeyStatus(): CliStatus {
  const [hasClaudeCli, setHasClaudeCli] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkCliStatus = async () => {
      try {
        const response = await fetch('/api/config/credentials');
        if (!response.ok) {
          setHasClaudeCli(false);
          setIsLoading(false);
          return;
        }
        const data = await response.json();
        setHasClaudeCli(data.hasClaudeCli ?? false);
        setError(null);
      } catch {
        setHasClaudeCli(false);
        setError('Failed to check CLI status');
      } finally {
        setIsLoading(false);
      }
    };

    checkCliStatus();
  }, []);

  return { hasClaudeCli, isLoading, error };
}
