interface RepoInfo {
  id: string
  name: string
  path: string
  contextFile?: string
  lastAnalyzed?: string
}

type TabType = 'setup' | 'plans' | 'fixes' | 'spikes' | 'quality' | 'agents' | 'skills' | 'plugins' | 'hooks'

// Helper to get/set localStorage with prefix
const getStorageKey = (repoId: string, key: string) => `tiny-brain:repo:${repoId}:${key}`

const getStoredValue = <T,>(repoId: string, key: string, defaultValue: T): T => {
  try {
    const stored = localStorage.getItem(getStorageKey(repoId, key))
    return stored ? JSON.parse(stored) : defaultValue
  } catch {
    return defaultValue
  }
}

const setStoredValue = <T,>(repoId: string, key: string, value: T): void => {
  try {
    localStorage.setItem(getStorageKey(repoId, key), JSON.stringify(value))
  } catch {
    // Ignore storage errors
  }
}

const planStatusLabels: Record<string, string> = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Complete',
  superseded: 'Superseded',
}

const planStatusColors: Record<string, string> = {
  not_started: 'bg-gray-500',
  in_progress: 'bg-blue-500',
  completed: 'bg-green-500',
  superseded: 'bg-orange-500',
}

export default function RepoDetailPage() {
  const { repoId } = useParams<{ repoId: string }>()
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId ?? '')
  const { setRepo: setCurrentRepo } = useCurrentRepo()

  // Initialize state from localStorage
  const [activeTab, setActiveTabState] = useState<TabType>(() =>
    repoId ? getStoredValue(repoId, 'activeTab', 'setup' as TabType) : 'setup'
  )
  const [selectedPlanId, setSelectedPlanIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedPlanId', null) : null
  )
  const [selectedFixId, setSelectedFixIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedFixId', null) : null
  )
  const [selectedAgentId, setSelectedAgentIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedAgentId', null) : null
  )
  const [selectedSkillId, setSelectedSkillIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedSkillId', null) : null
  )
  const [selectedPluginId, setSelectedPluginIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedPluginId', null) : null
  )
  const [selectedQualityRunId, setSelectedQualityRunIdState] = useState<string | null>(() =>
    repoId ? getStoredValue(repoId, 'selectedQualityRunId', null) : null
  )

  // Wrapped setters that persist to localStorage
  const setActiveTab = (tab: TabType) => {
    setActiveTabState(tab)
    if (repoId) setStoredValue(repoId, 'activeTab', tab)
  }
  const setSelectedPlanId = (id: string | null) => {
    setSelectedPlanIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedPlanId', id)
  }
  const setSelectedFixId = (id: string | null) => {
    setSelectedFixIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedFixId', id)
  }
  const setSelectedAgentId = (id: string | null) => {
    setSelectedAgentIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedAgentId', id)
  }
  const setSelectedSkillId = (id: string | null) => {
    setSelectedSkillIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedSkillId', id)
  }
  const setSelectedPluginId = (id: string | null) => {
    setSelectedPluginIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedPluginId', id)
  }
  const setSelectedQualityRunId = (id: string | null) => {
    setSelectedQualityRunIdState(id)
    if (repoId) setStoredValue(repoId, 'selectedQualityRunId', id)
  }
  const [viewMode] = useState<'summary' | 'details' | 'json'>('details')
  const [repoPlans, setRepoPlans] = useState<Plan[]>([])
  const [repoFixes, setRepoFixes] = useState<Fix[]>([])
  const [repoSpikes, setRepoSpikes] = useState<SpikeSummary[]>([])
  const [selectedSpikeId, setSelectedSpikeId] = useState<string | null>(null)
  const [selectedSpike, setSelectedSpike] = useState<SpikeProgress | null>(null)
  const [repoWorktrees, setRepoWorktrees] = useState<Worktree[]>([])
  // Default true because the page fetches spikes immediately on mount
  // (see the repoId-keyed effect below). Starting false would let the
  // tab-fallback effect fire before the fetch has even kicked off,
  // bouncing a Spikes-preferring user to setup on every page load.
  const [spikesLoading, setSpikesLoading] = useState(true)
  const [spikeDetailLoading, setSpikeDetailLoading] = useState(false)
  const [repoAgents, setRepoAgents] = useState<Agent[]>([])
  const [repoSkills, setRepoSkills] = useState<Skill[]>([])
  const [repoPlugins, setRepoPlugins] = useState<RepoPlugin[]>([])
  const [repoHooks, setRepoHooks] = useState<AllHooks>({ pluginHooks: [], repoHooks: [], gitHooks: [] })
  const [repoQualityRuns, setRepoQualityRuns] = useState<QualityRunSummary[]>([])
  const [, setLatestQualityGrade] = useState<string | null>(null)
  const [, setLatestQualityScore] = useState<number | null>(null)
  const [qualityCriteria, setQualityCriteria] = useState<{ passing: number; total: number } | null>(null)
  const [selectedQualityRun, setSelectedQualityRun] = useState<QualityRunDetail | null>(null)
  const [repoInfo, setRepoInfo] = useState<RepoInfo | null>(null)
  const [loading, setLoading] = useState(true)
  const [fixesLoading, setFixesLoading] = useState(false)
  const [agentsLoading, setAgentsLoading] = useState(false)

  // Status filters for plans and fixes
  const [planStatusFilter, setPlanStatusFilter] = useState<StatusFilter>(null)
  const [fixStatusFilter, setFixStatusFilter] = useState<StatusFilter>(null)
  const [spikeStatusFilter, setSpikeStatusFilter] = useState<StatusFilter>(null)
  // Shared list search query (over the sidebar), reset when the tab changes.
  const [listSearch, setListSearch] = useState('')
  const [showArchivedPlans, setShowArchivedPlans] = useState(false)
  const [showArchivedFixes, setShowArchivedFixes] = useState(false)
  const [skillsLoading, setSkillsLoading] = useState(false)
  const [pluginsLoading, setPluginsLoading] = useState(false)
  const [hooksLoading, setHooksLoading] = useState(false)
  const [, setQualityLoading] = useState(false)
  const [selectedHook, setSelectedHook] = useState<Hook | null>(null)
  const [setupComplete, setSetupComplete] = useState(false)

  // Filter plans based on archive toggle (memoized to stabilize useEffect deps)
  const plans = useMemo(() => showArchivedPlans
    ? repoPlans.filter(p => p.type === 'archived')
    : repoPlans.filter(p => p.type !== 'archived'),
  [repoPlans, showArchivedPlans])

  // Calculate plan status counts (count plans by their status)
  const planStatusCounts = plans.reduce(
    (acc, plan) => {
      if (plan.status === 'completed') {
        acc.complete++;
      } else if (plan.status === 'in_progress') {
        acc.inProgress++;
      } else {
        // 'not_started' or undefined
        acc.notStarted++;
      }
      return acc;
    },
    { notStarted: 0, inProgress: 0, complete: 0 }
  );

  // Filter fixes based on archive toggle (memoized to stabilize useEffect deps)
  const fixes = useMemo(() => showArchivedFixes
    ? repoFixes.filter(f => f.archived === true)
    : repoFixes.filter(f => f.archived !== true),
  [repoFixes, showArchivedFixes])

  // Calculate fix status counts (count fixes by their status)
  const fixStatusCounts = fixes.reduce(
    (acc, fix) => {
      if (fix.status === 'completed' || fix.status === 'superseded') {
        acc.complete++;
      } else if (fix.status === 'in_progress') {
        acc.inProgress++;
      } else {
        acc.notStarted++;
      }
      return acc;
    },
    { notStarted: 0, inProgress: 0, complete: 0 }
  );

  // Calculate spike status counts (validated/invalidated/abandoned = complete; in_progress; not_started)
  const spikeStatusCounts = repoSpikes.reduce(
    (acc, spike) => {
      const s = spike.status as string;
      if (s === 'validated' || s === 'invalidated' || s === 'abandoned') {
        acc.complete++;
      } else if (s === 'in_progress') {
        acc.inProgress++;
      } else {
        acc.notStarted++;
      }
      return acc;
    },
    { notStarted: 0, inProgress: 0, complete: 0 }
  );

  // Filter spikes based on status filter
  const filteredSpikes = (spikeStatusFilter
    ? repoSpikes.filter(spike => {
        const s = spike.status as string;
        if (spikeStatusFilter === 'complete') {
          return s === 'validated' || s === 'invalidated' || s === 'abandoned';
        } else if (spikeStatusFilter === 'in_progress') {
          return s === 'in_progress';
        } else {
          return s === 'not_started';
        }
      })
    : repoSpikes
  ).filter(spike => matchesSearch(listSearch, spike.title, spike.id));

  // Filter plans based on status filter
  const filteredPlans = (planStatusFilter
    ? plans.filter(plan => {
        if (planStatusFilter === 'complete') {
          return plan.status === 'completed';
        } else if (planStatusFilter === 'in_progress') {
          return plan.status === 'in_progress';
        } else {
          // not_started
          return plan.status === 'not_started' || !plan.status;
        }
      })
    : plans
  ).filter(plan => matchesSearch(listSearch, plan.title, plan.name, plan.prdId));

  // Filter fixes based on status filter
  const filteredFixes = (fixStatusFilter
    ? fixes.filter(fix => {
        if (fixStatusFilter === 'complete') {
          return fix.status === 'completed' || fix.status === 'superseded';
        } else if (fixStatusFilter === 'in_progress') {
          return fix.status === 'in_progress';
        } else {
          return fix.status === 'not_started' || !fix.status;
        }
      })
    : fixes
  ).filter(fix => matchesSearch(listSearch, fix.title, fix.id));

  const selectedPlan = selectedPlanId ? plans.find((p: Plan) => p.id === selectedPlanId) : null

  // Fetch repo info
  const fetchRepoInfo = async () => {
    try {
      console.log('[RepoDetailPage] Fetching repo info for:', repoId);
      const response = await fetch(`/api/repos/${repoId}`)
      console.log('[RepoDetailPage] Repo info response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received repo info:', data);
        setRepoInfo(data.repo || null)
        setCurrentRepo(data.repo || null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo info:', error)
    }
  }

  // Fetch plans for this repo
  const fetchRepoPlans = async () => {
    try {
      console.log('[RepoDetailPage] Fetching plans for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/plans`)
      console.log('[RepoDetailPage] Response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received data:', data);
        console.log('[RepoDetailPage] Plans count:', data.plans?.length);
        setRepoPlans(data.plans || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo plans:', error)
    } finally {
      setLoading(false)
    }
  }

  // Fetch fixes for this repo
  const fetchRepoFixes = async () => {
    try {
      setFixesLoading(true)
      console.log('[RepoDetailPage] Fetching fixes for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/fixes`)
      console.log('[RepoDetailPage] Fixes response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received fixes:', data);
        console.log('[RepoDetailPage] Fixes count:', data.fixes?.length);
        setRepoFixes(data.fixes || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo fixes:', error)
    } finally {
      setFixesLoading(false)
    }
  }

  // Fetch spikes for this repo
  const fetchRepoSpikes = async () => {
    if (!repoId) return
    try {
      setSpikesLoading(true)
      const response = await fetch(`/api/repos/${repoId}/spikes`)
      if (!response.ok) {
        // Distinguish a real failure from "no spikes yet" — both
        // resolve to an empty list in the UI, but a server-side 500
        // is something we want surfaced in the console for triage.
        console.error(
          '[RepoDetailPage] Spikes fetch failed:',
          response.status,
          await response.text().catch(() => '(no body)'),
        )
        return
      }
      const data = await response.json()
      setRepoSpikes(data.spikes ?? [])
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo spikes:', error)
    } finally {
      setSpikesLoading(false)
    }
  }

  // Fetch worktrees so SpikeDetail can derive present/orphaned status
  // for its launch snippet / orphan banner. Bounded by repo size, cheap.
  const fetchRepoWorktrees = async () => {
    if (!repoId) return
    try {
      const response = await fetch(`/api/repos/${repoId}/worktrees`)
      if (response.ok) {
        const data = await response.json()
        setRepoWorktrees(data.worktrees ?? [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo worktrees:', error)
    }
  }

  // Fetch full spike detail when the user selects a row. List endpoint
  // only carries summaries (cheap to refresh); detail carries tasks +
  // outcome body which only matter once the user is looking at one
  // spike.
  //
  // AbortController guards against the stale-response race: if the
  // user clicks spike A then B and A's response lands last, the
  // controller from A's call is aborted by B's, so the outdated
  // payload never reaches setSelectedSpike.
  const fetchSpikeDetail = async (
    spikeId: string,
    signal: AbortSignal,
  ): Promise<void> => {
    if (!repoId) return
    try {
      setSpikeDetailLoading(true)
      const response = await fetch(
        `/api/repos/${repoId}/spikes/${encodeURIComponent(spikeId)}`,
        { signal },
      )
      if (signal.aborted) return
      if (!response.ok) {
        console.error(
          '[RepoDetailPage] Spike detail fetch failed:',
          response.status,
          await response.text().catch(() => '(no body)'),
        )
        setSelectedSpike(null)
        return
      }
      const data = await response.json()
      if (!signal.aborted) setSelectedSpike(data.spike ?? null)
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') return
      console.error('[RepoDetailPage] Error fetching spike detail:', error)
      setSelectedSpike(null)
    } finally {
      if (!signal.aborted) setSpikeDetailLoading(false)
    }
  }

  // Fetch agents for this repo
  const fetchRepoAgents = async () => {
    try {
      setAgentsLoading(true)
      console.log('[RepoDetailPage] Fetching agents for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/agents`)
      console.log('[RepoDetailPage] Agents response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received agents:', data);
        console.log('[RepoDetailPage] Agents count:', data.agents?.length);
        setRepoAgents(data.agents || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo agents:', error)
    } finally {
      setAgentsLoading(false)
    }
  }

  // Fetch skills for this repo
  const fetchRepoSkills = async () => {
    try {
      setSkillsLoading(true)
      console.log('[RepoDetailPage] Fetching skills for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/skills`)
      console.log('[RepoDetailPage] Skills response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received skills:', data);
        console.log('[RepoDetailPage] Skills count:', data.skills?.length);
        setRepoSkills(data.skills || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo skills:', error)
    } finally {
      setSkillsLoading(false)
    }
  }

  // Fetch plugins for this repo
  const fetchRepoPlugins = async () => {
    try {
      setPluginsLoading(true)
      console.log('[RepoDetailPage] Fetching plugins for repo:', repoId);
      // Use the repo path from repoInfo, or decode the repoId
      const repoPath = repoInfo?.path || decodeURIComponent(repoId || '')
      const response = await fetch(`/api/plugins/repo/${encodeURIComponent(repoPath)}`)
      console.log('[RepoDetailPage] Plugins response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received plugins:', data);
        console.log('[RepoDetailPage] Plugins count:', data.plugins?.length);
        setRepoPlugins(data.plugins || [])
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo plugins:', error)
    } finally {
      setPluginsLoading(false)
    }
  }

  // Fetch hooks for this repo
  const fetchRepoHooks = async () => {
    try {
      setHooksLoading(true)
      console.log('[RepoDetailPage] Fetching hooks for repo:', repoId);
      const repoPath = repoInfo?.path || decodeURIComponent(repoId || '')
      const response = await fetch(`/api/hooks?repoPath=${encodeURIComponent(repoPath)}`)
      console.log('[RepoDetailPage] Hooks response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received hooks:', data);
        setRepoHooks(data)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo hooks:', error)
    } finally {
      setHooksLoading(false)
    }
  }

  // Eagerly fetch quality criteria for tab badge
  const fetchQualityCriteria = async () => {
    try {
      const response = await fetch(`/api/repos/${repoId}/quality-scores`)
      if (response.ok) {
        const data = await response.json()
        if (data.readiness) {
          setQualityCriteria(data.readiness)
        }
      }
    } catch {
      // Ignore — criteria will be set when QualityTab renders
    }
  }

  // Fetch quality runs for this repo
  const fetchRepoQualityRuns = async () => {
    try {
      setQualityLoading(true)
      console.log('[RepoDetailPage] Fetching quality runs for repo:', repoId);
      const response = await fetch(`/api/repos/${repoId}/quality`)
      console.log('[RepoDetailPage] Quality response status:', response.status, response.ok);
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received quality runs:', data);
        console.log('[RepoDetailPage] Quality runs count:', data.runs?.length);
        setRepoQualityRuns(data.runs || [])
        setLatestQualityGrade(data.latestGrade || null)
        setLatestQualityScore(data.latestScore ?? null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching repo quality runs:', error)
    } finally {
      setQualityLoading(false)
    }
  }

  // Fetch quality run details
  const fetchQualityRunDetail = async (runId: string) => {
    try {
      console.log('[RepoDetailPage] Fetching quality run detail:', runId);
      const response = await fetch(`/api/repos/${repoId}/quality/${runId}`)
      if (response.ok) {
        const data = await response.json()
        console.log('[RepoDetailPage] Received quality run detail:', data);
        setSelectedQualityRun(data.run || null)
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error fetching quality run detail:', error)
    }
  }

  // Check setup status (lightweight: 3 small fetches)
  const checkSetupStatus = async () => {
    try {
      const [healthRes, analysisRes, recsRes] = await Promise.all([
        fetch(`/api/repos/${repoId}/config-health`),
        fetch(`/api/repos/${repoId}/analysis`),
        fetch(`/api/repos/${repoId}/recommendations`),
      ])
      const isHealthy = healthRes.ok && (await healthRes.json()).health?.status === 'healthy'
      const analysisExists = analysisRes.ok && (await analysisRes.json()).exists
      const noRecs = recsRes.ok && ((await recsRes.json()).recommendations ?? []).length === 0
      setSetupComplete(isHealthy && analysisExists && noRecs)
    } catch {
      // Silently handle — setupComplete stays false
    }
  }

  useEffect(() => {
    if (repoId) {
      // Selection state from the previous repo would otherwise persist
      // across the switch — the spike-detail effect would then try to
      // fetch the old spike id against the new repo's API. Reset
      // up-front so the detail pane stays empty until the user picks
      // a row in the new repo's sidebar.
      setSelectedSpikeId(null)
      setSelectedSpike(null)
      fetchRepoInfo()
      fetchRepoPlans()
      fetchRepoFixes()
      fetchRepoSpikes()
      fetchRepoWorktrees()
      fetchRepoAgents()
      fetchRepoSkills()
      fetchRepoQualityRuns()
      fetchQualityCriteria()
      checkSetupStatus()
    }
  }, [repoId])

  // Clear current-repo context when leaving the page so the header reverts
  useEffect(() => {
    return () => setCurrentRepo(null)
  }, [setCurrentRepo])

  // If the user's persisted activeTab is 'spikes' but the repo has no
  // spikes (tab is hidden), fall through to the setup tab so the page
  // isn't stuck on a hidden tab's content. Uses the un-persisting
  // setActiveTabState so the user's stored preference is preserved —
  // they should be bounced visually only; their saved choice stays
  // intact for repos that DO have spikes.
  useEffect(() => {
    if (activeTab === 'spikes' && !spikesLoading && repoSpikes.length === 0) {
      setActiveTabState('setup')
    }
  }, [activeTab, spikesLoading, repoSpikes.length])

  // Refetch spike detail when the user picks a different row. The
  // effect's cleanup aborts the in-flight request — rapid A→B clicks
  // can't leave A's data showing under B's selection.
  useEffect(() => {
    if (!selectedSpikeId) {
      setSelectedSpike(null)
      setSpikeDetailLoading(false)
      return
    }
    const controller = new AbortController()
    fetchSpikeDetail(selectedSpikeId, controller.signal)
    return () => controller.abort()
    // fetchSpikeDetail closes over repoId, which is captured by the
    // outer effect's deps; safe to omit from this effect's deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedSpikeId])

  // Live overlay (PRD progress-json-as-event-projection F4/T5): a
  // server-side `spike-doc-change` event for the currently-selected
  // spike refetches the projection. The hook no-ops when nothing is
  // selected — no SSE bookkeeping in the idle case.
  useSpikeDocLive(
    repoId ?? null,
    selectedSpikeId,
    () => {
      // Fresh AbortController per refetch — the previous controller
      // belongs to the original selection effect and is torn down
      // there.
      fetchSpikeDetail(selectedSpikeId!, new AbortController().signal)
    },
  )

  // Live overlay (Fix: dashboard-drops-filewatcher-sse-events): a
  // markdown edit to a PRD/feature or fix doc emits prd-doc-change /
  // fix-doc-change (not the git-ref `invalidate` this view otherwise
  // relies on). Bridge those into a repo-scoped refetch so the per-repo
  // plans/fixes update live on edit, mirroring the spike doc overlay.
  usePrdDocLive(repoId ?? null, () => fetchRepoPlans())
  useFixDocLive(repoId ?? null, () => fetchRepoFixes())

  // Fetch plugins and hooks after repoInfo is loaded (they need the repo path)
  useEffect(() => {
    if (repoInfo?.path) {
      fetchRepoPlugins()
      fetchRepoHooks()
    }
  }, [repoInfo?.path])

  // Auto-select first plan or validate persisted selection
  useEffect(() => {
    if (plans.length > 0) {
      // If no selection or persisted selection no longer exists, select first
      if (!selectedPlanId || !plans.find(p => p.id === selectedPlanId)) {
        setSelectedPlanId(plans[0].id)
      }
    }
  }, [plans, selectedPlanId])

  // Auto-select first fix or validate persisted selection
  useEffect(() => {
    if (fixes.length > 0) {
      if (!selectedFixId || !fixes.find(f => f.id === selectedFixId)) {
        setSelectedFixId(fixes[0].id)
      }
    }
  }, [fixes, selectedFixId])

  // Auto-select first agent or validate persisted selection
  useEffect(() => {
    if (repoAgents.length > 0) {
      if (!selectedAgentId || !repoAgents.find(a => a.id === selectedAgentId)) {
        setSelectedAgentId(repoAgents[0].id)
      }
    }
  }, [repoAgents, selectedAgentId])

  // Auto-select first skill or validate persisted selection
  useEffect(() => {
    if (repoSkills.length > 0) {
      if (!selectedSkillId || !repoSkills.find(s => s.id === selectedSkillId)) {
        setSelectedSkillId(repoSkills[0].id)
      }
    }
  }, [repoSkills, selectedSkillId])

  // Auto-select first plugin or validate persisted selection
  useEffect(() => {
    if (repoPlugins.length > 0) {
      if (!selectedPluginId || !repoPlugins.find(p => p.path === selectedPluginId)) {
        setSelectedPluginId(repoPlugins[0].path)
      }
    }
  }, [repoPlugins, selectedPluginId])

  // Auto-select first quality run or validate persisted selection
  useEffect(() => {
    if (repoQualityRuns.length > 0) {
      if (!selectedQualityRunId || !repoQualityRuns.find(r => r.runId === selectedQualityRunId)) {
        setSelectedQualityRunId(repoQualityRuns[0].runId)
      }
    }
  }, [repoQualityRuns, selectedQualityRunId])

  // Auto-select first hook when hooks load
  useEffect(() => {
    const allHooks = [...repoHooks.pluginHooks, ...(repoHooks.repoHooks ?? []), ...repoHooks.gitHooks]
    if (allHooks.length > 0 && !selectedHook) {
      setSelectedHook(allHooks[0])
    }
  }, [repoHooks, selectedHook])

  // Fetch quality run details when selection changes
  useEffect(() => {
    if (selectedQualityRunId) {
      fetchQualityRunDetail(selectedQualityRunId)
    } else {
      setSelectedQualityRun(null)
    }
  }, [selectedQualityRunId, repoId])

  // Listen to SSE invalidate events and replace entities in state
  useSSEEvent<InvalidateEvent>('invalidate', (event) => {
    // Only process events for this repo
    if (event.repoId && event.repoId !== repoId) {
      return;
    }

    // Entities are Plan[] when resource is plan/plans, Fix[] when fix/fixes.
    // TypeScript can't narrow the union from the resource discriminant, so we cast.
    switch (event.resource) {
      case 'plan':
        // Specific plan(s) changed — replace matching entities
        setRepoPlans(prevPlans => {
          const updatedPlans = [...prevPlans];
          for (const entity of event.entities as Plan[]) {
            const idx = updatedPlans.findIndex(p => p.id === entity.id);
            if (idx !== -1) {
              updatedPlans[idx] = entity;
            }
          }
          return updatedPlans;
        });
        break;

      case 'plans':
        // Plan list changed (added) — merge into existing list
        setRepoPlans(prevPlans => {
          const updatedPlans = [...prevPlans];
          for (const entity of event.entities as Plan[]) {
            const idx = updatedPlans.findIndex(p => p.id === entity.id);
            if (idx !== -1) {
              updatedPlans[idx] = entity;
            } else {
              updatedPlans.push(entity);
            }
          }
          return updatedPlans;
        });
        break;

      case 'fix':
        // Specific fix(es) changed — replace matching entities
        setRepoFixes(prevFixes => {
          const updatedFixes = [...prevFixes];
          for (const entity of event.entities as Fix[]) {
            const idx = updatedFixes.findIndex(f => f.id === entity.id);
            if (idx !== -1) {
              updatedFixes[idx] = entity;
            }
          }
          return updatedFixes;
        });
        break;

      case 'fixes':
        // Fix list changed (added) — merge into existing list
        setRepoFixes(prevFixes => {
          const updatedFixes = [...prevFixes];
          for (const entity of event.entities as Fix[]) {
            const idx = updatedFixes.findIndex(f => f.id === entity.id);
            if (idx !== -1) {
              updatedFixes[idx] = entity;
            } else {
              updatedFixes.push(entity);
            }
          }
          return updatedFixes;
        });
        break;
    }
  });

  // Listen to SSE quality-change events and refetch quality data
  useSSEEvent('qualityChange', (event: any) => {
    console.log('[RepoDetailPage] Received quality-change event:', event.eventType, event);

    // Only process events for this repo
    if (event.repoId && event.repoId !== repoId) {
      console.log('[RepoDetailPage] Ignoring quality event for different repo:', event.repoId);
      return;
    }

    // Refetch quality runs to get the latest data
    console.log('[RepoDetailPage] Refetching quality runs after SSE event');
    fetchRepoQualityRuns();
  });

  const handlePlanSelect = (planId: string) => {
    setSelectedPlanId(planId)
  }

  const handleFixSelect = (fixId: string) => {
    setSelectedFixId(fixId)
  }

  const handleAgentSelect = (agentId: string) => {
    setSelectedAgentId(agentId)
  }

  const handleSkillSelect = (skillId: string) => {
    setSelectedSkillId(skillId)
  }

  const handlePluginSelect = (pluginId: string) => {
    setSelectedPluginId(pluginId)
  }

  const handleQualityRunSelect = (runId: string) => {
    setSelectedQualityRunId(runId)
  }

  const handleHookSelect = (hook: Hook) => {
    setSelectedHook(hook)
  }

  const handleArchivePlan = async (planId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/plans/${planId}/archive`, { method: 'POST' })
      if (response.ok) {
        setRepoPlans(prev => prev.map(p =>
          p.id === planId ? { ...p, type: 'archived' } : p
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error archiving plan:', error)
    }
  }

  const handleUnarchivePlan = async (planId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/plans/${planId}/unarchive`, { method: 'POST' })
      if (response.ok) {
        setRepoPlans(prev => prev.map(p =>
          p.id === planId ? { ...p, type: 'active' } : p
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error unarchiving plan:', error)
    }
  }

  const handleArchiveFix = async (fixId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}/archive`, { method: 'POST' })
      if (response.ok) {
        setRepoFixes(prev => prev.map(f =>
          f.id === fixId ? { ...f, archived: true } : f
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error archiving fix:', error)
    }
  }

  const handleUnarchiveFix = async (fixId: string) => {
    try {
      const response = await fetch(`/api/repos/${repoId}/fixes/${fixId}/unarchive`, { method: 'POST' })
      if (response.ok) {
        setRepoFixes(prev => prev.map(f =>
          f.id === fixId ? { ...f, archived: false } : f
        ))
      }
    } catch (error) {
      console.error('[RepoDetailPage] Error unarchiving fix:', error)
    }
  }

  const selectedFix = selectedFixId ? fixes.find((f: Fix) => f.id === selectedFixId) : null
  const selectedAgent = selectedAgentId ? repoAgents.find((a: Agent) => a.id === selectedAgentId) : null
  const selectedSkill = selectedSkillId ? repoSkills.find((s: Skill) => s.id === selectedSkillId) : null
  const selectedPlugin = selectedPluginId ? repoPlugins.find((p: RepoPlugin) => p.path === selectedPluginId) : null

  return (
    <DetailsPopoverProvider>
    <div className="flex flex-col h-full overflow-hidden">
      {/* Navigation Toggle */}
      <div className="border-b px-4 py-3 bg-background flex-shrink-0 flex items-center justify-between gap-6">
        {/* Work Items: Plans, Fixes, Quality */}
        <ToggleGroup value={activeTab} onValueChange={(value) => { setActiveTab(value as TabType); setListSearch(''); }}>
          <ToggleGroupItem
            value="setup"
            style={setupComplete ? {
              background: 'linear-gradient(to right, rgba(236, 72, 153, 0.15), rgba(59, 130, 246, 0.15))',
              borderColor: 'rgba(236, 72, 153, 0.3)',
            } : undefined}
          >
            <Rocket className="h-4 w-4 text-orange-500" />
            Setup
            {setupComplete && <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />}
          </ToggleGroupItem>
          <ChevronRight className="h-4 w-4 text-muted-foreground flex-shrink-0" />
          <ToggleGroupItem
            value="quality"
            style={qualityCriteria && qualityCriteria.total > 0 ? {
              background: `linear-gradient(to right, rgba(34, 197, 94, 0.35) ${(qualityCriteria.passing / qualityCriteria.total) * 100}%, transparent ${(qualityCriteria.passing / qualityCriteria.total) * 100}%)`,
            } : undefined}
          >
            <BarChart3 className="h-4 w-4" />
            Quality
            {qualityCriteria && (
              <span className="text-xs text-muted-foreground">{qualityCriteria.passing}/{qualityCriteria.total}</span>
            )}
          </ToggleGroupItem>
          <ChevronRight className="h-4 w-4 text-muted-foreground flex-shrink-0" />
          <ToggleGroupItem
            value="plans"
            statusCounts={planStatusCounts}
            activeStatusFilter={planStatusFilter}
            onStatusFilterChange={setPlanStatusFilter}
            showArchived={showArchivedPlans}
            onArchiveToggle={() => setShowArchivedPlans(!showArchivedPlans)}
          >
            <FileText className="h-4 w-4" />
            Plans
          </ToggleGroupItem>
          <ToggleGroupItem
            value="fixes"
            statusCounts={fixStatusCounts}
            activeStatusFilter={fixStatusFilter}
            onStatusFilterChange={setFixStatusFilter}
            showArchived={showArchivedFixes}
            onArchiveToggle={() => setShowArchivedFixes(!showArchivedFixes)}
          >
            <Bolt className="h-4 w-4" />
            Fixes
          </ToggleGroupItem>
          {/* Hidden when the repo has no spikes — cleaner UI for users
              who don't use the workflow. The /spike skill is taught
              elsewhere (welcome flow, docs); once the first spike doc
              lands the tab appears for that repo. */}
          {repoSpikes.length > 0 && (
            <ToggleGroupItem
              value="spikes"
              statusCounts={spikeStatusCounts}
              activeStatusFilter={spikeStatusFilter}
              onStatusFilterChange={setSpikeStatusFilter}
            >
              <Zap className="h-4 w-4" />
              Spikes
            </ToggleGroupItem>
          )}
        </ToggleGroup>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden">
        {activeTab === 'setup' ? (
          <SetupTab repoId={repoId!} repoPath={repoInfo?.path} onNavigateToPlans={() => setActiveTab('plans')} onSetupComplete={setSetupComplete} />
        ) : activeTab === 'quality' ? (
          repoId ? (
            <QualityTab
              repoId={repoId}
              runs={repoQualityRuns}
              selectedRun={selectedQualityRun}
              selectedRunId={selectedQualityRunId}
              onSelectRun={handleQualityRunSelect}
              onCriteriaChange={setQualityCriteria}
              onRunDeleted={() => {
                setSelectedQualityRunId(null)
                setSelectedQualityRun(null)
                fetchRepoQualityRuns()
              }}
            />
          ) : null
        ) : (
        <ResizablePanelGroup direction="horizontal">
          {/* Sidebar */}
          <ResizablePanel defaultSize={30} minSize={20} maxSize={40}>
            <div className="h-full flex flex-col">
              {/* Search bar over the sidebar — styled to match DetailHeaderBar so
                  the two read as one full-width section bar across the columns. */}
              {(activeTab === 'plans' || activeTab === 'fixes' || activeTab === 'spikes') && (
                <div className="flex-shrink-0 border-b px-4 h-[60px] flex items-center bg-fixed bg-gradient-to-r from-tb-blue-50 to-[oklch(0.97_0.015_320)] dark:from-tb-blue-900 dark:to-[oklch(0.30_0.03_320)]">
                  <ListSearchBox
                    value={listSearch}
                    onChange={setListSearch}
                    placeholder={`Search ${activeTab}…`}
                  />
                </div>
              )}
              <div className="flex-1 overflow-auto">
                {activeTab === 'plans' && (
                  loading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <PlanList
                      plans={filteredPlans}
                      selectedPlanId={selectedPlanId}
                      onSelectPlan={handlePlanSelect}
                    />
                  )
                )}
                {activeTab === 'fixes' && (
                  fixesLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <FixList
                      fixes={filteredFixes}
                      selectedFixId={selectedFixId}
                      onSelectFix={handleFixSelect}
                      reviewPipeline={reviewPipeline}
                    />
                  )
                )}
                {activeTab === 'spikes' && (
                  spikesLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <SpikesList
                      spikes={filteredSpikes}
                      selectedSpikeId={selectedSpikeId}
                      onSelectSpike={setSelectedSpikeId}
                    />
                  )
                )}
                {activeTab === 'agents' && (
                  agentsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <AgentList
                      agents={repoAgents}
                      selectedAgentId={selectedAgentId}
                      onSelectAgent={handleAgentSelect}
                    />
                  )
                )}
                {activeTab === 'skills' && (
                  skillsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <SkillList
                      skills={repoSkills}
                      selectedSkillId={selectedSkillId}
                      onSelectSkill={handleSkillSelect}
                      repoId={repoId || ''}
                    />
                  )
                )}
                {activeTab === 'plugins' && (
                  pluginsLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <RepoPluginList
                      plugins={repoPlugins}
                      selectedPluginId={selectedPluginId}
                      onSelectPlugin={handlePluginSelect}
                    />
                  )
                )}
                {activeTab === 'hooks' && (
                  hooksLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
                    </div>
                  ) : (
                    <HooksList
                      hooks={repoHooks}
                      selectedHook={selectedHook}
                      onSelectHook={handleHookSelect}
                    />
                  )
                )}
              </div>
            </div>
          </ResizablePanel>

          {/* The divider line is transparent for the top 60px (behind the
              header bar) and the real border colour below, so the splitter
              starts beneath the header — the header reads as one continuous
              strip while the list/detail divider stays visible and draggable. */}
          <ResizableHandle
            withHandle
            className="!bg-transparent bg-[linear-gradient(to_bottom,transparent_60px,#e5e7eb_60px)] dark:bg-[linear-gradient(to_bottom,transparent_60px,#252d3a_60px)]"
          />

          {/* Details */}
          <ResizablePanel defaultSize={70}>
            <div className="h-full flex flex-col">
              {activeTab === 'plans' && (
                selectedPlan ? (
                  <>
                    {/* PRD Header — shared identity bar (consistent across PRD/Fix/Spike) */}
                    <DetailHeaderBar
                      testId="prd-header-bar"
                      title={selectedPlan.title || selectedPlan.name || ''}
                      id={selectedPlan.prdId || selectedPlan.id}
                      idKind="PRD"
                      right={
                        <>
                          {selectedPlan.status && (
                            <Badge variant="outline" className="flex items-center gap-1.5 whitespace-nowrap font-normal border-gray-300 dark:border-gray-600 rounded">
                              <span className={cn('w-2 h-2 rounded-full', planStatusColors[selectedPlan.status])} />
                              {planStatusLabels[selectedPlan.status] ?? selectedPlan.status}
                            </Badge>
                          )}
                          {selectedPlan.type === 'archived' ? (
                            <button
                              onClick={() => handleUnarchivePlan(selectedPlan.id)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-md border border-gray-300 dark:border-gray-600 text-gray-500 dark:text-gray-400 hover:bg-gray-100 hover:dark:bg-gray-700/50 hover:text-gray-700 dark:hover:text-gray-200 transition-all duration-200"
                              aria-label="Unarchive"
                            >
                              <Archive className="h-4 w-4" />
                              Unarchive
                            </button>
                          ) : (
                            <button
                              onClick={() => handleArchivePlan(selectedPlan.id)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-md border border-gray-300 dark:border-gray-600 text-gray-500 dark:text-gray-400 hover:bg-gray-100 hover:dark:bg-gray-700/50 hover:text-gray-700 dark:hover:text-gray-200 transition-all duration-200"
                              aria-label="Archive"
                            >
                              <Archive className="h-4 w-4" />
                              Archive
                            </button>
                          )}
                        </>
                      }
                    />
                    <div className="flex-1 overflow-auto">
                      <PlanDetails
                        plan={selectedPlan}
                        viewMode={viewMode}
                        repoId={repoId}
                      />
                    </div>
                  </>
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {loading ? 'Loading plans...' : 'No plans found for this repository'}
                  </div>
                )
              )}
              {activeTab === 'fixes' && (
                selectedFix ? (
                  <FixDetail
                    fix={selectedFix}
                    repoId={repoId!}
                    onArchive={() => handleArchiveFix(selectedFix.id)}
                    onUnarchive={() => handleUnarchiveFix(selectedFix.id)}
                  />
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-muted-foreground gap-2">
                    <Bolt className="h-10 w-10" aria-hidden="true" />
                    <span>{fixesLoading ? 'Loading fixes...' : 'No fixes found for this repository'}</span>
                  </div>
                )
              )}
              {activeTab === 'spikes' && (
                selectedSpike ? (
                  <SpikeDetail
                    spike={selectedSpike}
                    worktreeStatus={getSpikeWorktreeStatus(selectedSpike.worktree, repoWorktrees)}
                    repoId={repoId ?? ''}
                    onWorktreeCleared={() => {
                      // The fire-and-forget refetch can't be cancelled
                      // from a callback — the AbortController earlier
                      // here was decorative. The existing
                      // selectedSpikeId effect's cleanup is the real
                      // serialisation point against rapid switches.
                      if (selectedSpikeId) {
                        fetchSpikeDetail(selectedSpikeId, new AbortController().signal)
                      }
                      fetchRepoWorktrees()
                    }}
                    onOutcomeRecorded={() => {
                      // Refetch both the detail (status flipped to
                      // terminal, outcome banner appears) and the
                      // sidebar (the spike's status badge updates).
                      if (selectedSpikeId) {
                        fetchSpikeDetail(selectedSpikeId, new AbortController().signal)
                      }
                      fetchRepoSpikes()
                    }}
                  />
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-muted-foreground gap-2">
                    <Zap className="h-10 w-10" aria-hidden="true" />
                    <span>
                      {spikeDetailLoading
                        ? 'Loading spike…'
                        : selectedSpikeId
                          ? 'Spike not found'
                          : 'Pick a spike to see its detail'}
                    </span>
                  </div>
                )
              )}
              {activeTab === 'agents' && (
                selectedAgent ? (
                  <AgentDetail agent={selectedAgent} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {agentsLoading ? 'Loading agents...' : 'No agents installed in this repository'}
                  </div>
                )
              )}
              {activeTab === 'skills' && (
                selectedSkill ? (
                  <SkillDetail skill={selectedSkill} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {skillsLoading ? 'Loading skills...' : 'No skills installed in this repository'}
                  </div>
                )
              )}
              {activeTab === 'plugins' && (
                selectedPlugin ? (
                  <RepoPluginDetail plugin={selectedPlugin} />
                ) : (
                  <div className="h-full flex items-center justify-center text-muted-foreground">
                    {pluginsLoading ? 'Loading plugins...' : 'No plugins available for this repository'}
                  </div>
                )
              )}
              {activeTab === 'hooks' && (
                <HookDetail
                  hook={selectedHook}
                  repoPath={repoInfo?.path || decodeURIComponent(repoId || '')}
                />
              )}
            </div>
          </ResizablePanel>
        </ResizablePanelGroup>
        )}
      </div>

    </div>
    </DetailsPopoverProvider>
  )
}
