import React, { useEffect, useState } from 'react';
import type { TaskRowTask, TddPhase } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { ADVERSARIAL_STEP } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';
import { deriveTddPhase, isPhaseComplete, isPhaseInProgress } from '../utils/tdd-phases';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';

interface TddPhasePipelineProps {
  task: TaskRowTask;
  repoId?: string;
  reviewPipeline?: PipelineStep[];
  onPhaseClick?: (phase: TddPhase, commitSha: string) => void;
}

interface PhaseIcon {
  readonly emoji: string;
  readonly label: string;
  readonly phase: TddPhase;
  readonly groupType?: string;
  readonly groupRole?: 'review' | 'refactor';
}

const DEFAULT_REVIEW_EMOJI = '\u{1F50D}'; // 🔍

function buildPipelinePhases(
  reviewPipeline: PipelineStep[],
  pipelineType?: string,
  pipelineSnapshot?: readonly string[],
): PhaseIcon[] {
  // Spike tasks have no red phase — the strategy enters at green and
  // stamps `testCommitSha: 'skipped'` at the event layer. Rendering a
  // red pill (even struck through) for spike would imply the phase was
  // ever in play, which it wasn't. Omit it entirely so the timeline
  // matches the spike strategy's actual shape: green → review → refactor.
  const phases: PhaseIcon[] = pipelineType === 'spike'
    ? [{ emoji: '\u{1F7E2}', label: 'Green', phase: 'green' }]
    : [
        { emoji: '\u{1F534}', label: 'Red', phase: 'red' },
        { emoji: '\u{1F7E2}', label: 'Green', phase: 'green' },
      ];
  // Gate set + order: prefer the task's immutable pipelineSnapshot (the
  // gate names captured at first red/green entry) so a later reviewPipeline
  // change can't retroactively alter which gates a completed task is shown
  // to have traversed. Presentation (label/emoji) doesn't vary per task, so
  // it's joined from the live pipeline catalog by type \u2014 with a default
  // fallback for a gate that's no longer present in the catalog.
  const catalog = new Map(reviewPipeline.map(s => [s.type, s]));
  const gateTypes = pipelineSnapshot
    ?? reviewPipeline.filter(s => !s.hook).map(s => s.type);
  for (const type of gateTypes) {
    const step = catalog.get(type);
    const label = step?.label || type.charAt(0).toUpperCase() + type.slice(1);
    const emoji = step?.emoji || DEFAULT_REVIEW_EMOJI;
    phases.push({ emoji, label, phase: `review:${type}`, groupType: type, groupRole: 'review' });
    phases.push({ emoji: '\u21A9\uFE0F', label: 'Refactor', phase: `refactor:${type}`, groupType: type, groupRole: 'refactor' });
  }
  return phases;
}

// The reviewed (green) sha the on-disk review file is named by, for a review
// gate — distinct from the displayed `reviewSha`, which on a `review:` carrier
// is the verdict commit's own sha (fix
// dashboard-review-popover-blank-after-verdict-commit). Falls back to reviewSha
// for the event-overlay window (pre-verdict-commit, where reviewSha already IS
// the green sha). Used everywhere review detail is FETCHED (popover, coverage
// tooltip), so the fetch resolves the <greenSha>.json file.
const getReviewFetchSha = (task: TaskRowTask, type: string): string | undefined => {
  const review = task.reviews?.[type];
  return review?.reviewedSha ?? review?.reviewSha ?? undefined;
};

const getPhaseCommitSha = (task: TaskRowTask, phase: TddPhase): string | undefined => {
  // Generic pipeline phases — read from reviews map
  if (phase.startsWith('review:')) {
    const type = phase.slice(7);
    return task.reviews?.[type]?.reviewSha ?? undefined;
  }
  if (phase.startsWith('refactor:')) {
    const type = phase.slice(9);
    return task.reviews?.[type]?.refactorCommitSha ?? undefined;
  }
  // Legacy flat fields
  switch (phase) {
    case 'red': return task.testCommitSha;
    case 'green': return task.commitSha;
    case 'adversarial': return task.adversarialReviewSha ?? task.commitSha;
    case 'adversarial-refactor': return task.adversarialRefactorCommitSha;
    case 'mutation': return task.mutationReviewSha ?? task.commitSha;
    case 'mutation-refactor': return task.mutationRefactorCommitSha;
    default: return undefined;
  }
};

const isPhaseEffectivelyComplete = (
  task: TaskRowTask,
  phase: TddPhase,
  phases: readonly PhaseIcon[],
  index: number,
): boolean => {
  if (isPhaseComplete(task, phase)) {
    return true;
  }

  // Skip-through: if a refactor phase is not complete but a subsequent phase IS complete,
  // treat the refactor as complete (applies to both legacy and generic refactor phases)
  if (phase === 'adversarial-refactor' || phase.startsWith('refactor:')) {
    const subsequentPhases = phases.slice(index + 1);
    return subsequentPhases.some((p) => isPhaseComplete(task, p.phase));
  }

  return false;
};

const isPhaseSkipped = (task: TaskRowTask, phase: TddPhase): boolean => {
  // RED skipped via --green
  if (phase === 'red' && task.testCommitSha === 'skipped') return true;
  // Refactor auto-skipped after clean verdict or max attempts exceeded
  if (phase.startsWith('refactor:')) {
    const type = phase.slice(9);
    const sha = task.reviews?.[type]?.refactorCommitSha;
    return sha === 'skipped' || sha === 'max-attempts-exceeded';
  }
  // Legacy flat fields
  if (phase === 'adversarial-refactor' && task.adversarialRefactorCommitSha === 'skipped') return true;
  if (phase === 'mutation-refactor' && task.mutationRefactorCommitSha === 'skipped') return true;
  return false;
};

const isRefactorNotNeeded = (task: TaskRowTask, phase: TddPhase, reviewPipeline?: PipelineStep[]): boolean => {
  const derived = deriveTddPhase(task, reviewPipeline);

  // Generic pipeline refactor phases
  if (phase.startsWith('refactor:')) {
    const type = phase.slice(9);
    const review = task.reviews?.[type];
    return !!review?.reviewSha && !review?.refactorCommitSha && derived === 'complete';
  }

  // Legacy flat fields
  if (phase === 'adversarial-refactor') {
    return !!task.adversarialReviewSha && !task.adversarialRefactorCommitSha
      && derived === 'complete';
  }
  if (phase === 'mutation-refactor') {
    return !!task.mutationReviewSha && !task.mutationRefactorCommitSha
      && derived === 'complete';
  }
  return false;
};

// A review gate whose tool could not run is recorded with verdict 'failed'
// (pipeline-step-failed-verdict). It is terminal (no refactor owed) but must be
// surfaced distinctly from a clean/dirty review, not as a passing "complete".
const isPhaseFailed = (task: TaskRowTask, phase: TddPhase): boolean => {
  if (!phase.startsWith('review:')) return false;
  const type = phase.slice(7);
  return task.reviews?.[type]?.verdict === 'failed';
};

const getPhaseTitle = (label: string, complete: boolean, inProgress: boolean, notNeeded: boolean, commitSha: string | undefined): string => {
  if (complete && commitSha) {
    return `${label}: ${commitSha.substring(0, 7)}`;
  }
  if (complete) {
    return `${label}: complete`;
  }
  if (notNeeded) {
    return `${label}: not needed`;
  }
  if (inProgress) {
    return `${label}: in progress`;
  }
  return `${label}: not yet started`;
};

const TddPhasePipeline: React.FC<TddPhasePipelineProps> = ({
  task,
  repoId,
  reviewPipeline,
  onPhaseClick,
}) => {
  // Always use generic pipeline mode — default to adversarial if not specified
  const effectivePipeline = reviewPipeline ?? [ADVERSARIAL_STEP];
  const phases = buildPipelinePhases(effectivePipeline, task.pipelineType, task.pipelineSnapshot);

  // Build config once outside the loop — combineRedGreenCommits is false
  // because the dashboard always renders separate red/green phase icons
  const pipelineConfig = reviewPipeline ? { combineRedGreenCommits: false, reviewPipeline } : undefined;

  // Fetch coverage data for completed coverage reviews (for tooltip)
  const [coverageData, setCoverageData] = useState<{ percent?: number; threshold: number; verdict?: string } | undefined>();
  // Fetch by the reviewed (green) sha the file is named by — not reviewSha,
  // which the verdict commit re-keys to its own sha (same blank-after-verdict
  // bug as the popover, fix dashboard-review-popover-blank-after-verdict-commit).
  const coverageSha = getReviewFetchSha(task, 'coverage');
  useEffect(() => {
    if (!repoId || !coverageSha || coverageSha === 'skipped') return;
    fetch(`/api/repos/${repoId}/reviews/coverage/${coverageSha}`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!data) return;
        const pct = data.coveragePercent ?? data.overallCoverage;
        setCoverageData({
          percent: typeof pct === 'number' ? pct : undefined,
          threshold: data.threshold ?? 80,
          verdict: data.verdict,
        });
      })
      .catch(() => {});
  }, [repoId, coverageSha]);

  const renderPhaseTooltip = (phaseIcon: PhaseIcon, index: number): React.ReactNode => {
    const key = `${phaseIcon.phase}-${index}`;
    const complete = isPhaseEffectivelyComplete(task, phaseIcon.phase, phases, index);
    const commitSha = getPhaseCommitSha(task, phaseIcon.phase);
    // The sha to FETCH review detail by — the reviewed (green) sha for review
    // gates, the displayed commit otherwise. Distinct from commitSha, which the
    // title shows (the verdict commit on a review: carrier). At the click site
    // below it's `fetchSha ?? commitSha`: the fallback is runtime-dead (fetchSha
    // is defined whenever the icon is clickable) but type-required — commitSha is
    // narrowed to string by the isClickable const-alias, fetchSha is not.
    const fetchSha = phaseIcon.phase.startsWith('review:')
      ? getReviewFetchSha(task, phaseIcon.phase.slice(7))
      : commitSha;
    const isCurrent = task.status !== 'completed' && task.status !== 'superseded' && isPhaseInProgress(task, phaseIcon.phase, pipelineConfig);
    const skipped = isPhaseSkipped(task, phaseIcon.phase);
    const isClickable = complete && !skipped && commitSha !== undefined && onPhaseClick !== undefined;
    const notNeeded = isRefactorNotNeeded(task, phaseIcon.phase, reviewPipeline);
    const failed = isPhaseFailed(task, phaseIcon.phase);
    const isCoverageReview = phaseIcon.phase === 'review:coverage';
    const title = skipped
      ? `${phaseIcon.label}: skipped`
      : failed
        ? `${phaseIcon.label}: failed`
        : getPhaseTitle(phaseIcon.label, complete, isCurrent, notNeeded, commitSha);
    const coverageTooltip = isCoverageReview && complete && coverageData;
    const coveragePassing = coverageData?.percent != null
      ? coverageData.percent >= coverageData.threshold
      : coverageData?.verdict === 'clean';

    const baseClass = `text-base w-8 h-8 flex items-center justify-center rounded-full${isCurrent ? ' animate-ring-pulse bg-gradient-to-br from-blue-300/70 to-pink-300/70 dark:from-blue-800/40 dark:to-pink-800/40' : ''}`;
    const emojiContent = (
      <span className="relative inline-flex items-center justify-center" style={{ opacity: skipped ? 0.6 : failed ? 0.5 : complete ? 1 : 0.25 }}>
        {phaseIcon.emoji}
        {skipped && (
          <span
            className="absolute inset-0 pointer-events-none opacity-70 dark:opacity-85"
            style={{
              background: 'linear-gradient(to bottom right, transparent calc(50% - 1.5px), currentColor calc(50% - 1.5px), currentColor calc(50% + 1.5px), transparent calc(50% + 1.5px))',
            }}
          />
        )}
      </span>
    );

    const ariaLabel = coverageTooltip && coverageData?.percent != null
      ? `Coverage now at ${coverageData.percent}%`
      : title;

    const trigger = isClickable ? (
      <TooltipTrigger asChild>
        <button
          type="button"
          aria-label={ariaLabel}
          className={`${baseClass} cursor-pointer border-0 bg-transparent p-0`}
          onClick={(e) => { e.stopPropagation(); onPhaseClick(phaseIcon.phase, fetchSha ?? commitSha); }}
        >
          {emojiContent}
        </button>
      </TooltipTrigger>
    ) : (
      <TooltipTrigger asChild>
        <span aria-label={ariaLabel} role="img" className={baseClass}>
          {emojiContent}
        </span>
      </TooltipTrigger>
    );

    const tooltipContent = coverageTooltip ? (
      <span className="inline-flex items-center gap-1">
        Coverage now at{' '}
        <span className={`font-bold ${coveragePassing ? 'text-green-400' : 'text-red-400'}`}>
          {coverageData?.percent != null ? `${coverageData.percent}%` : coverageData?.verdict ?? '—'}
        </span>
      </span>
    ) : title;

    return (
      <Tooltip key={key}>
        {trigger}
        <TooltipContent side="bottom">{tooltipContent}</TooltipContent>
      </Tooltip>
    );
  };

  // Build render items: standalone phases (red/green) and grouped review+refactor pairs
  const renderItems: React.ReactNode[] = [];
  const processedIndices = new Set<number>();

  for (let i = 0; i < phases.length; i++) {
    if (processedIndices.has(i)) continue;

    const phaseIcon = phases[i];

    if (phaseIcon.groupRole === 'review' && phaseIcon.groupType) {
      // Find the matching refactor phase (should be the next one)
      const refactorIndex = phases.findIndex(
        (p, j) => j > i && p.groupType === phaseIcon.groupType && p.groupRole === 'refactor'
      );
      if (refactorIndex !== -1) {
        processedIndices.add(i);
        processedIndices.add(refactorIndex);

        // Determine if refactor should be visible (slide out when active, slide back when skipped)
        const refactorPhase = phases[refactorIndex];
        const refactorSha = getPhaseCommitSha(task, refactorPhase.phase);
        const refactorInProgress = task.status !== 'completed' && task.status !== 'superseded'
          && isPhaseInProgress(task, refactorPhase.phase, pipelineConfig);
        const reviewInProgress = task.status !== 'completed' && task.status !== 'superseded'
          && isPhaseInProgress(task, phaseIcon.phase, pipelineConfig);
        const refactorHasCommit = !!refactorSha && refactorSha !== 'skipped' && refactorSha !== 'max-attempts-exceeded';
        const refactorVisible = refactorInProgress || refactorHasCommit;
        const pairActive = refactorInProgress || reviewInProgress;

        renderItems.push(
          <span
            key={`review-group-${phaseIcon.groupType}`}
            data-testid={`review-group-${phaseIcon.groupType}`}
            className="inline-flex items-center p-1 -m-1"
          >
            {renderPhaseTooltip(phaseIcon, i)}
            <span
              className={`inline-flex items-center transition-all duration-300 ease-in-out ${
                refactorVisible ? 'max-w-14 opacity-100 overflow-visible' : 'max-w-0 opacity-0 overflow-hidden'
              }`}
            >
              <span
                data-testid={`review-connector-${phaseIcon.groupType}`}
                className={`w-3 h-[3px] bg-current opacity-70 dark:opacity-85 shrink-0 ${pairActive ? 'mx-1' : '-mx-0.5'}`}
              />
              {renderPhaseTooltip(refactorPhase, refactorIndex)}
            </span>
          </span>
        );
        continue;
      }
    }

    renderItems.push(renderPhaseTooltip(phaseIcon, i));
  }

  return (
    <span className="inline-flex items-center gap-3 mr-1 p-1">
      {renderItems}
    </span>
  );
};

export default TddPhasePipeline;
